#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
agentify :: scripts/verify_artifacts.py -- deterministic post-build checks.

Phase 8.  Reads the build manifest written in phase 7, then proves -- without
asking the model to eyeball anything -- that what was built is well formed,
loadable, idempotent, contained inside the repo, and free of secrets.

    python3 "$SKILL_DIR/scripts/verify_artifacts.py" \\
        --repo "$PWD" --manifest docs/agentic-setup/build-manifest.json

    cat build-manifest.json | python3 .../verify_artifacts.py --repo "$PWD" --manifest -

Exit codes follow the shared contract in `lib/emit.py`'s module docstring,
which is the single normative statement -- do not restate it here and do not
invent a code.  This script is the one place the exit-1 branch is reachable on
a normal run: the manifest is the required input, so a manifest that is
missing, empty, unparseable, or not a manifest exits 1 with a JSON `error`
object.  Everything else is exit 0, INCLUDING a build that fails every check
-- a failed check is data, not a crash.  The `summary` counts are what phase 8
reports to the user.

Run `python3 scripts/verify_artifacts.py --selftest` for a sub-second sanity
check: imports resolve, emit round-trips, regexes compile, a synthetic
two-artifact build verifies clean, a deliberately broken one is caught, and
each unreadable-manifest path exits 1 with JSON.  Hooks are never executed by
the selftest.


HOOK EXECUTION IS OPT-IN  (read this before changing anything below)
-------------------------------------------------------------------------------

This script is the only part of the agentify toolchain that can execute code the
tool itself wrote, and therefore the only remaining path to the network in a tool
whose headline guarantee is "local only, no network calls" (PRD 13).  It cannot
be removed -- PRD 7.9 requires a hook smoke test -- so it is fenced instead:

  * DEFAULT: hooks are NOT executed.  They get static checks only -- the file
    exists, carries the execute bit, starts with a shebang, and passes a static
    scan for network calls.  `hook_smoke` reports `warn` saying so.
  * `--exec-hooks` turns execution on.  SKILL.md passes it ONLY after asking the
    user, in phase 8, in as many words, and getting an explicit yes.  It is never
    passed on the default path and never inferred from any earlier answer.
  * `--no-exec` is still accepted; it is the default, and it wins if both flags
    are given.  Nothing that already passes `--no-exec` breaks.

Even with `--exec-hooks`, a hook is executed ONLY when both are true:

    1. its resolved script path is inside the repo root, AND
    2. that same path is listed in THIS run's build manifest.

Anything else -- a pre-existing hook, a wrapper pointing at `/usr/local/bin/x`,
a script the user wrote by hand -- reports
`hook_smoke: warn -- not executed: hook not generated by this run`.
agentify smoke-tests what agentify built, and nothing else.

A hook whose static scan finds a network call (`curl`, `wget`, `nc`, `ssh`,
`python -c` with `urllib`, `node` with `fetch`/`http`, `/dev/tcp`, a package
install, a remote `git` operation, ...) is a FAIL naming the offending line, and
is never executed regardless of flags.

When a hook is executed, the blast radius is cut down first:

  * environment is rebuilt from an allowlist -- `PATH` and `HOME` only, plus
    `AGENTIFY_VERIFY` and the variables THE TARGET's own harness sets
    (`CLAUDE_PROJECT_DIR` on Claude Code, `CODEX_HOME` on Codex; the profile
    table decides).  Every `*_KEY`, `*_TOKEN`, `*_SECRET`, `AWS_*`, and in fact
    everything else in the parent environment is gone, and a second explicit
    filter re-checks that.
  * `HOME`, those variables and `cwd` all point inside a throwaway fixture
    directory -- NOT the user's repo and NOT the real `${CODEX_HOME}` -- so a
    hook that writes relative paths cannot touch the working tree.
  * `shell=False` always.  The command is `shlex.split` when it parses cleanly;
    when it genuinely needs a shell the argv is the visible, literal
    `["/bin/sh", "-c", cmd]`.
  * a hard timeout (`--hook-timeout-s`, default 5s), killed by process group.


THE BUILD MANIFEST  (phase 7 writes this; SKILL.md must emit exactly this shape)
-------------------------------------------------------------------------------

One JSON object, conventionally at `docs/agentic-setup/build-manifest.json`:

    {
      "schema_version": 1,
      "tool": "agentify",
      "generated": "2026-09-04",
      "target": "claude-code",
      "repo_root": "/abs/path/to/repo",
      "branch": "agentic-setup/2026-09-04",
      "_agentify": {
        "agentify-id": "build-manifest",
        "agentify-version": 1,
        "agentify-generated": "2026-09-04",
        "agentify-evidence": "index of the 12 artifacts this run built",
        "note": "Inert metadata, the same shape mcp.json.tmpl and plugin.json.tmpl
                 emit. Nothing reads it at runtime; it exists so a rerun can
                 recognise its own manifest. Safe to delete or edit."
      },
      "mode": "branch",
      "base_branch": "main",
      "base_commit": "ba6d13d...",
      "created_dirs": [".claude/hooks", ".claude/rules", "docs/agentic-setup", ".claude"],
      "committed_paths": ["CLAUDE.md", "docs/agentic-setup/plan.md"],
      "uncommitted_paths": [".claude/rules/db-access-layer.md",
                            ".claude/hooks/pre-commit-typecheck.sh"],
      "artifacts": [
        {
          "id": "add-api-endpoint",
          "type": "skill",
          "path": ".claude/skills/add-api-endpoint/SKILL.md",
          "action": "created",
          "evidence": "request_shapes: 'add endpoint with tests' x7 in 5 sessions"
        },
        {
          "id": "db-access-layer",
          "type": "rule",
          "path": ".claude/rules/db-access-layer.md",
          "action": "created",
          "evidence": "cochange src/db/*.ts + src/api/*.ts, support 11",
          "ignored": true,
          "ignored_by": ".gitignore:6:.claude/"
        },
        {
          "id": "pre-commit-typecheck",
          "type": "hook",
          "path": ".claude/hooks/pre-commit-typecheck.sh",
          "action": "created",
          "evidence": "corrections: 'run tsc first' x4",
          "command": "\\"$CLAUDE_PROJECT_DIR/.claude/hooks/pre-commit-typecheck.sh\\"",
          "ignored": true,
          "ignored_by": ".gitignore:6:.claude/"
        },
        {
          "id": "index-doc",
          "type": "index-doc",
          "path": "CLAUDE.md",
          "action": "modified",
          "evidence": "discovery: bun + next + drizzle; 6 package scripts",
          "ignored": false,
          "pre_existing_sha256": "8f14e45fce...",
          "restore": "head"
        },
        {
          "id": "agentic-setup-plan",
          "type": "plan",
          "path": "docs/agentic-setup/plan.md",
          "action": "created",
          "evidence": "the approved plan of record for this run: 12 artifacts, 4 skipped"
        },
        {
          "id": "build-manifest",
          "type": "manifest",
          "path": "docs/agentic-setup/build-manifest.json",
          "action": "created",
          "evidence": "index of the 12 artifacts this run built"
        },
        {
          "id": "agentic-setup-report",
          "type": "report",
          "path": "docs/agentic-setup/report.md",
          "action": "created",
          "evidence": "handoff for the 12 artifacts built and 4 skipped"
        }
      ]
    }

AGENTIFY'S OWN OUTPUT IS VERIFIED TOO.  `plan.md`, `report.md` and this manifest
are generated files like every other one, and the last three entries above are
how they get checked.  Before those types existed they were the only files the
tool wrote and never looked at -- the 2026-09-04 dogfood run shipped a manifest
with no `agentify-id` anywhere in it and nothing noticed.  Two ordering facts
make the self-listing work, and verification.md section 9 spells out the
sequence phase 8 must follow:

  * The manifest may list ITSELF.  Its own checks are existence, non-emptiness,
    valid JSON and the `_agentify` identity -- none of them depends on the
    manifest's content -- so appending an entry after it was verified does not
    invalidate the earlier pass.  There is no hash and no chicken-and-egg.
  * `report.md` does NOT exist during the first static pass; it is written from
    the results of that pass.  Its entry is therefore appended AFTER the report
    is written, and the static pass is run once more to cover it.  Listing it
    earlier would be a guaranteed `file_exists` FAIL, which is why phase 8 must
    not add it up front.

Per-artifact fields:

    id        REQUIRED. Kebab-case, unique across the whole manifest.  It is
              the same string as the file's `agentify-id` and the id carried by
              the begin/end markers of a modified file.
    type      REQUIRED. One of: skill, subagent, rule, hook, index-doc,
              settings, mcp, plugin, command, reference, plan, report,
              manifest, other.
              Common synonyms are accepted (agent -> subagent, skills -> skill,
              mcp-config -> mcp, build-manifest -> manifest, ...); an unknown
              type is checked as `other` and warned about.  `plan`, `report`
              and `manifest` are agentify's own phase 6/7/8 output; `manifest`
              is a JSON type, so it is exempt from the markdown-only checks
              exactly as `settings`, `mcp` and `plugin` are.
    path      REQUIRED. Repo-relative (preferred) or absolute inside the repo.
              Anything that resolves outside the repo root, or that traverses
              out with `..` or via a symlink, FAILS `path_containment` and no
              further check reads it.
    action    REQUIRED. "created" or "modified".  A modified file must carry
              exactly one agentify begin/end marker pair for its id.
    evidence  REQUIRED, non-empty.  One line with counts.  An artifact with no
              evidence should never have been built (PRD 8), so an empty one is
              a `manifest_entry` FAIL, not a warn.
    command   OPTIONAL, hooks only.  The exact command line registered in the
              target's hook registry, when it differs from `path` -- wrapper
              args, a `${CLAUDE_PROJECT_DIR}` prefix on Claude Code, or the
              `"$(git rev-parse --show-toplevel)/.codex/hooks/<name>.sh"`
              spelling Codex uses because it defines no such variable.
              Defaults to `path`.
    name      OPTIONAL. Expected frontmatter `name`.  Defaults to the skill
              directory name / the file stem.
    ignored   OPTIONAL, boolean, from phase 7's `git check-ignore -v`.  True
              means `git add` refuses this path, so it can only reach the undo
              through an explicit per-file step -- `undo_partition` checks it
              against `committed_paths` rather than trusting it.
    ignored_by  OPTIONAL, the `<file>:<line>:<pattern>` check-ignore printed.
              Reported back in the passing `undo_partition` row, so the user
              learns WHICH rule kept the file off the branch.
    restore   OPTIONAL, `head` or `span`, on `action: modified` entries.  `head`
              means git holds the pre-run bytes on `base_commit`; `span` means
              it does not, and committing such a file makes the undo DELETE it.
    pre_existing_sha256   OPTIONAL, on `action: modified` entries: the file's
              hash before the run.  verification.md 10.3 checks it against git;
              this script only carries it.

THE UNDO RECORD  (top level; phase 8 generates the removal steps from it)
-------------------------------------------------------------------------------

`mode`, `branch`, `base_branch`, `base_commit`, `committed`, `pushed`,
`pr_url`, `created_dirs`, `committed_paths`, `uncommitted_paths`.  Two of them
are checked here because they are the only thing that decides which mechanism
removes a given file: `committed_paths` and `uncommitted_paths` must partition
every artifact, and `created_dirs` must be repo-relative and deepest-first.
`mode` alone cannot choose the undo -- a run is routinely half committed and
half not.  A manifest with neither list gets one WARN, not a wall of failures,
so a hand-written manifest still verifies.

Also accepted, so a hand-written manifest still verifies:
  * a bare top-level JSON list of artifact objects;
  * `files` or `entries` as the key instead of `artifacts`.


MARKER CONVENTION  (canonical form -- templates must emit this)
---------------------------------------------------------------

A file that agentify only *appends to* (CLAUDE.md, an existing settings file,
an existing index doc) is delimited so a rerun can rewrite in place:

    <!-- agentify:begin id=index-doc -->
    ...generated content...
    <!-- agentify:end id=index-doc -->

For files whose comment syntax is `#` (shell, YAML, TOML):

    # agentify:begin id=pre-commit-typecheck
    # agentify:end id=pre-commit-typecheck

The parser is deliberately tolerant: any comment lead-in (`<!--`, `#`, `//`,
`/*`, `--`, `;`, `%`, or none), any of `agentify:begin` / `agentify-begin` /
`agentify begin` in any case, and the id given as `id=x`, `id: x`, or as a bare
trailing token.  An unlabelled pair is accepted as a WARN, never a pass.


WHAT IS CHECKED  (one `checks[]` entry each)
--------------------------------------------

    manifest_loaded     the manifest was read; `detail` carries the artifact
                        count and the repo it declares them for
    path_containment    resolved path is inside the repo root, no traversal
    manifest_entry      required fields present and well typed
    file_exists         exists and is non-empty
    markers             modified files: exactly one begin/end pair for the id
    frontmatter         markdown frontmatter parses (hand-rolled, no pyyaml)
    metadata            agentify-id / -version / -generated / -evidence present
                        and the id matches the manifest
    evidence_match      the file's `agentify-evidence` line is the SAME STRING
                        as its manifest entry's `evidence`
    id_unique           ids are globally unique across the manifest
    name_unique         no two skills, and no two subagents, share a name
    skill_frontmatter   name + description; name == directory name;
                        description non-empty and < 1024 chars
    subagent_frontmatter    the subagent's identity, read in ITS OWN FORMAT:
                        `name` + `description` from YAML frontmatter on Claude
                        Code; from TOML (plus `developer_instructions`, and a
                        filename stem equal to `name`) on Codex
    subagent_tools      declared tools all look like real tool names (WARN);
                        on Codex, where there is no per-agent allowlist, that
                        none was invented and `sandbox_mode` is not
                        `danger-full-access` (FAIL)
    rule_scope          PROSE rules only -- scope present, globs valid
    rule_body           PROSE rules only -- body is not empty
    rule_wired          PROSE rules only -- the rule is referenced from an
                        index doc, so something actually loads it
    rule_policy_syntax  COMMAND POLICIES only -- `.codex/rules/*.rules` parses
                        as Starlark and declares at least one policy rule
    rule_policy_decision    every `decision` is allow/prompt/forbidden (FAIL:
                        any other value is a fatal Codex startup error)
    rule_policy_pattern every rule's command prefix is non-empty
    rule_policy_examples    `match` is declared and every example behaves as
                        written -- Codex enforces this at load time
    rule_policy_execpolicy  `codex execpolicy check` agreed, when a Codex
                        binary resolved and `--exec-hooks` was passed
    hook_script         command resolves, is executable, starts with a shebang
    hook_static_scan    no network call in the script or in the command line
    hook_smoke          runs with `{}` on stdin, exits 0 within the timeout --
                        only with `--exec-hooks`, and only for a hook this run
                        generated inside the repo; otherwise `warn`, not run
    hook_wired          something actually registers the hook: a command in
                        the target's own registry (`.claude/settings.json`,
                        `settings.local.json` or a plugin manifest on Claude
                        Code; `.codex/hooks.json` on Codex; either target's
                        user-scoped file), or -- for a native git hook -- its
                        name and its location
    settings_json       the target's hook registry is valid JSON, and (on a
                        target whose registry rejects unknown top-level keys,
                        i.e. Codex's `.codex/hooks.json`) carries none
    settings_hook_command   each hook command in it resolves to an existing,
                        executable file (or to a binary on PATH)
    mcp_json            the MCP config is valid IN ITS OWN FORMAT: JSON with
                        `mcpServers` on Claude Code, `[mcp_servers.<name>]`
                        TOML tables on Codex
    mcp_secrets         no literal-looking secret in it (FAIL, not warn)
    rule_contradiction  PROSE rules only -- opposing directives on the same
                        subject (WARN), two rules picking different members of
                        one exclusive category (WARN), and -- with
                        `--discovery` -- a rule that contradicts a discovered
                        convention (FAIL when the convention is a hard fact,
                        WARN when it is a soft one).  Fenced blocks,
                        NEGATIVE-EXAMPLE SECTIONS (`## Incorrect`, `## Avoid`,
                        ... -- matched as a WHOLE heading label, so
                        `## Never-cached routes` keeps its section) and
                        AGENTIFY'S OWN METADATA (`## Evidence`, the frontmatter
                        block, any `agentify-*:` line) are never directives
    core_set            blueprint.md 1.3's core set is present -- at least one
                        skill, `setup-manager`, a reviewer subagent, and (with
                        `--discovery`) the db, qa, analytics and env-leak
                        artifacts the repo licenses.  WARN only: a core
                        artifact the user dropped at the gate is a correct
                        outcome; one the walk never proposed is the defect
    undo_partition      `committed_paths` and `uncommitted_paths` cover every
                        artifact exactly once, and a gitignored or
                        `restore: span` artifact is in the second list
    undo_created_dirs   `created_dirs` is repo-relative, on disk, deepest-first
                        and COMPLETE -- every directory the created artifact
                        paths prove the run made is listed, so the undo's
                        `rmdir` steps leave none behind empty
    uninstall           the undo this run will publish, proved rather than
                        described: every artifact reachable by a mechanism its
                        FORMAT allows, every committed path actually on the
                        branch (across ALL its commits) AND byte-identical to
                        the working tree, and report.md's removal steps
                        self-consistent in the order they print

Severity rules worth knowing before reading the output:

  * `manifest_entry` is a FAIL when `id`, `path`, `action` or `evidence` is
    missing, and a WARN only for the softer problems (an unrecognised `type`).
    Empty `evidence` is deliberately on the fatal side of that line: the whole
    product claim is that artifacts are evidence-derived, so one that reached
    the build with nothing behind it is a defect in the run, not a nitpick.
  * `metadata` is a FAIL for markdown and script artifacts, and a WARN for JSON
    artifacts (JSON cannot carry a comment header) and for `action: modified`
    files (the begin marker already carries the id).
  * `mcp_secrets` is a FAIL.  `${VAR}`, `$VAR`, `<placeholder>` and the usual
    dummy values are recognised as placeholders and never counted.
  * `evidence_match` is a FAIL.  SKILL.md phase 7 requires the evidence line in
    the file to be the same string the candidate carried in phase 4 and the
    plan carried in phase 6, and that line is the whole product claim
    (evidence-derived, not templated).  A file whose evidence has drifted from
    its manifest entry is either mis-generated or hand-edited, and either way
    it is no longer the artifact the user approved.  The one softened case is
    truncation: when one side is a prefix of the other and both are at least 20
    characters, it is the same claim cut short, and that WARNs.
  * `rule_wired` is a FAIL.  A rules directory is a repo convention, not a
    load path -- Claude Code reads `CLAUDE.md`, Codex reads `AGENTS.md`, and
    neither walks a rules directory -- so a rule the index doc does not point
    at does nothing at all.  Both adapters say so (`adapters/claude-code.md` 4.2,
    `adapters/codex.md` 4.2) and both make it a fail.  The search is a plain
    `grep -F "<name>.md"` over the whole index doc, exactly as the adapters
    spell it: a rule the user wired by hand in their own prose is wired, and
    failing that would delete a good rule.  It applies to PROSE rules only:
    `.codex/rules/*.rules` is a native load path Codex reads on its own, and
    demanding a pointer for one failed a correct artifact.
  * ONE TYPE, TWO FILE SHAPES -- read the shape, never the type name.  Three
    manifest types mean different formats on the two targets, and applying one
    target's reader to the other's file FAILS a correct artifact.  A false FAIL
    is the most damaging verdict here: SKILL.md phase 8 step 3 tells the model
    to fix or remove a failing artifact, so it destroys good work, and a check
    documented to fail on a correct artifact is not a check but a trap.  The
    three, all measured on the 2026-09-05 Codex dogfood:
      - `rule`     prose markdown with `scope:` frontmatter, OR a Codex
                   Starlark command policy (`.codex/rules/*.rules`).
      - `subagent` markdown with YAML frontmatter, OR Codex TOML.
      - `mcp`      `.mcp.json`, OR Codex `[mcp_servers.*]` TOML.
    Each gets the checks written for its own shape (`rule_policy_*`, the TOML
    readers), and the shared plumbing -- markers, un-merge routing -- keys on
    `_is_json_path`, never on the type name.
  * `hook_wired` is a FAIL, and it is `rule_wired`'s defect class arriving from
    the opposite side.  `settings_hook_command` walks the commands IN
    the registry and proves each lands on a file; nothing proved that every
    generated hook is named by one, so a hook script that was never registered
    was a dead file the run reported as a success.  Two registrations exist and
    each is checked as what it is: a command in the TARGET's own hook registry
    (`.claude/settings.json` / `settings.local.json` / a plugin manifest on
    Claude Code, `.codex/hooks.json` on Codex, plus either target's user-scoped
    file -- all the same three-level `hooks` shape), or a native git hook's
    NAME plus LOCATION.  There is no target on which a hook artifact fails by
    construction: BOTH targets have a full native hook system, and Codex's has
    12 events and a JSON permission-decision protocol (adapters/codex.md 4.3).
    Matching is as permissive as `rule_wired`'s grep: a resolved path, then the
    repo-relative path in the command text, then the file name -- except in a
    USER-scoped registry, shared by every repo on the machine, where a bare
    file name proves nothing and a path must match.  A `.agentify` side-file written beside a
    hook that already existed is a WARN, not a FAIL: it is inert on purpose
    until the user merges it (adapters/codex.md 4.3 rule 2).
  * `undo_partition` is a FAIL.  Phase 8 generates the report's removal steps
    from `committed_paths` and `uncommitted_paths`, so an artifact in neither is
    a file no undo removes -- the turborepo failure verification.md 10.2 exists
    to catch, where the branch delete printed `Deleted branch` and left five
    generated files on disk.  `ignored: true` in `committed_paths` is the same
    bug from the other end (`git add` refuses the path, so the branch never held
    it), and `action: modified` with `restore: span` in `committed_paths` is
    worse than a reporting bug: `git checkout <base_branch>` DELETES that file
    and the user's own content with it.  A manifest carrying neither list is one
    WARN saying phase 8 cannot generate the removal section from it.
  * `uninstall` is a FAIL, and it is the check the three shipped undo defects
    should have been caught by.  `undo_partition` proves the manifest agrees
    with itself; it cannot prove the undo WORKS, and coverage is necessary but
    not sufficient -- a step that names a path and then no-ops reads as covered
    by every enumeration ever written.  So this asks three further questions:
    (1) FORMAT -- a JSON config routed to the marker script is a FAIL, because
    JSON holds no comment, so the script prints `SKIP`, exits 0 and removes
    nothing (measured, the axios defect); a file that existed before the run
    routed to `rm` is a FAIL, because it deletes the user's own file; (2) THE
    BRANCH -- every `committed_paths` entry must be in
    `git diff --name-only <base>..<branch>`, which spans ALL of the branch's
    commits, never `git show`, which sees the tip alone and on an empty branch
    prints the BASE commit's files with exit 0; (3) THE RENDERED BLOCK -- the
    steps in report.md's removal section must survive being run in the order
    they are printed, unless the step's own comment says when to run it.  The
    only WARNs are the cases where an input could not be READ (no undo record
    in the manifest, or git unusable), and they say which.  The passing row is
    the one verification.md 10.5 publishes, detail and all: it is generated so
    the report never has to author it.
  * `subagent_tools` is a best-effort heuristic and never exceeds WARN.  So are
    two of `rule_contradiction`'s three kinds.  It reads rules CLAUSE by
    clause, not sentence by sentence: "Always use bun, never npm" is two
    directives, and a sentence-level reader keeps only the first, which is how
    the textbook contradiction used to pass.  Its PASS row states whether
    conventions were checked at all, because without `--discovery` half of
    PRD 7.9 did not run.
  * `rule_contradiction`'s `contradicts-convention` kind is a FAIL when the
    convention came from a HARD source -- `discovery.package_managers` or a
    `discovery.commands.*` line, what the repo actually runs.  verification.md
    section 6's own Fail example is exactly that ("a rule saying 'use npm' in a
    repo with bun.lockb and packageManager: bun") and the remedy it prescribes
    -- the repo wins, rewrite or delete the rule -- is the fix-or-remove loop
    that only a fail triggers.  The other two kinds stay WARN because they are
    one piece of generated prose read against another; this one is generated
    prose against a machine-extracted fact.  A clash with a SOFT source
    (`frameworks` / `languages`, which are name scans over file statistics)
    stays WARN: a JavaScript repo whose rule says "write new modules in
    TypeScript" has an intent, not a defect.  A rule worded as intent ("we are
    moving to X") is exempt from this check entirely.
  * `hook_static_scan` is a FAIL, and it suppresses execution: a hook that
    reaches the network is never smoke-tested, only reported.
  * `hook_smoke` treats a timeout as a FAIL: a hook that hangs blocks the user
    whatever directory it hangs in.  A launch failure is a FAIL too.  A non-zero
    EXIT is only a WARN, because the hook ran in an empty fixture and may be
    reacting to the missing repo rather than to its input -- verification.md
    section 5 settles that against a populated fixture.  Not being executed is a
    WARN, never a pass: an unexecuted hook has not been proven to work.

Local only, stdlib only, no network.  Python 3.9+.  One JSON object on stdout;
diagnostics on stderr.
"""

import ast
import fnmatch
import hashlib
import json
import os
import re
import shlex
import shutil
import subprocess
import sys
import tempfile
from typing import Any, Dict, List, Optional, Sequence, Tuple

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))

from lib import emit as emit_lib  # noqa: E402
from lib import scrub as scrub_lib  # noqa: E402

TOOL = "verify_artifacts.py"
SCHEMA_VERSION = emit_lib.SCHEMA_VERSION

#: Generous: `checks` is protected from trimming, so this only bounds the
#: incidental fields.  The entry cap below is the real guard.
CAP_CHARS = 60000

#: Hard ceiling on emitted check entries, so a 400-artifact manifest cannot
#: produce an unreadable wall of JSON.
MAX_CHECKS = 400

