#: Types whose markdown MUST carry frontmatter.
FRONTMATTER_REQUIRED = frozenset(["skill", "subagent", "rule", "command"])

#: Types that live in JSON, where a comment header is impossible: no markdown
#: frontmatter, no begin/end markers, and `agentify-*` metadata is read from an
#: inert `_agentify` object instead (see collect_metadata).
JSON_TYPES = frozenset(["settings", "mcp", "plugin", "manifest"])

#: The two files agentify changes by MERGING INTO A DATA STRUCTURE rather than
#: by appending a marked block.  JSON has no comment syntax, so neither ever
#: carried a marker and neither ever can: handed one, the report's marker script
#: prints `SKIP <path>: no agentify block id=...`, exits 0, and removes nothing
#: while every other step succeeds around it.  That is the axios defect, and it
#: is the reason `uninstall` asks the FORMAT question and not only the coverage
#: one.  `plugin` and `manifest` are JSON too but agentify owns them whole, so
#: they are removed with `rm` -- they are in JSON_TYPES and not here.
MERGED_JSON_TYPES = frozenset(["settings", "mcp"])

#: Written in phase 8 step 5, AFTER phase 8 step 1's static pass runs: their
#: paths are reserved in the undo lists at verification.md 9 step 4a while the
#: branch does not hold them yet.  `uninstall` exempts exactly these from its
#: branch-containment assertion and says how many it exempted.
PHASE8_COMMITTED_TYPES = frozenset(["report", "manifest"])

#: `report.md`'s removal section, and the pieces of it `uninstall` reads.
_REMOVAL_HEADING_RE = re.compile(r"^(#{2,6})[ \t]+How to remove everything[ \t]*$", re.I | re.M)
#: A fenced block, closed by the same fence it opened with.
_FENCE_RE = re.compile(r"^[ \t]*(```+|~~~+)[^\n]*\n(.*?)^[ \t]*\1[ \t]*$", re.S | re.M)
#: The marker script's `BLOCKS = [...]` / the un-merge script's `UNMERGE = [...]`,
#: captured as the LIST LITERAL only.  Never the script body around it: a
#: `print("SKIP %s: not present")` in there is not an operand.
_SCRIPT_LIST_RE = re.compile(r"^[ \t]*(BLOCKS|UNMERGE)[ \t]*=[ \t]*\[(.*?)^[ \t]*\][ \t]*$", re.S | re.M)
_SCRIPT_TUPLE_RE = re.compile(r"""\(\s*["']([^"'\n]*)["']""")
_RM_RE = re.compile(r"(?:^|[;&|]\s*)rm[ \t]+(.+)$")
_RMDIR_RE = re.compile(r"(?:^|[;&|]\s*)rmdir[ \t]+(.+)$")
_BRANCH_DELETE_RE = re.compile(r"\bgit\s+(?:-C\s+\S+\s+)?branch\s+(?:-\S+\s+)*-[dD]\s+(\S+)")
_GIT_SHOW_RE = re.compile(r"\bgit\s+(?:-C\s+\S+\s+)?show\s+(?:-\S+\s+)*([^\s:]+):(\S+)")
_GIT_CHECKOUT_RE = re.compile(r"\bgit\s+(?:-C\s+\S+\s+)?(?:checkout|switch)\s+(?!-)(\S+)\s*$")
_GIT_RESTORE_RE = re.compile(r"\bgit\s+(?:-C\s+\S+\s+)?restore\b(.*)$")
_SHASUM_RE = re.compile(r"\b(?:shasum\s+-a\s+256|sha256sum)[ \t]+(.+)$")
_CP_RE = re.compile(r"^cp[ \t]+(.+)$")
#: The `> DEST` of a step that writes its output somewhere.  Read for ONE
#: question: is DEST outside the repo?  A step that copies the removal
#: instructions out of the tree is the step every later step depends on, and it
#: is recognised by that shape -- source is the file the block is printed in,
#: destination is not a repo-relative path -- never by the name
#: `~/agentify-removal-steps.md`, which is one wording of it and not the fact.
_REDIRECT_RE = re.compile(r"(?:^|\s)\d?>>?[ \t]*(\S+)[ \t]*$")
#: A step whose own comment says when to run it is ordered by that sentence and
#: not by where it sits on the page.  report-template.md 3.1 now orders its
#: blocks so no step needs one (A saves and deletes the branch, B and C run the
#: scripts, D deletes files and directories last), and earlier revisions shipped
#: `# Run this AFTER the two scripts below` instead.  Both are honest; a block
#: that is out of order and says nothing is the one this check fails.
_DEFERRED_RE = re.compile(
    r"(run\s+(?:this|it|these|them)[^.]{0,60}?\bafter\b)|(\bafter\s+the\s+(?:two\s+)?scripts?\b)"
    r"|(\bafter\s+step\s+\d)",
    re.I,
)
#: Tokens report-template.md 3.1 tells the generator to substitute.  A rendered
#: report that still carries one was pasted, not generated.  The ALL-CAPS
#: fallback catches a token this list has not learned yet.
_REMOVAL_PLACEHOLDERS = frozenset(
    [
        "REMOVAL_COMMANDS", "REMOVAL_MODE_SENTENCE", "REMOVAL_EXTRA_BLOCKS_OR_DELETE",
        "REMOVAL_VERIFY_SENTENCE", "REMOVAL_PR_NOTE_OR_DELETE",
        "BASE_BRANCH", "BASE_COMMIT", "BRANCH_NAME", "REPO_ROOT", "PLAN_DIR",
        "CREATED_PATH", "CREATED_PATHS", "CREATED_DIR", "CREATED_DIRS",
        "CREATED_DIRS_DEEPEST_FIRST", "IGNORED_CREATED_PATHS", "IGNORED_BY_PATTERN",
        "IGNORED_CREATED_DIRS_DEEPEST_FIRST", "COMMITTED_CREATED_PATHS",
        "COMMITTED_MODIFIED_PATHS", "MODIFIED_PATH", "MODIFIED_ID", "MODIFIED_RESTORE_SENTENCE",
        "PRE_EXISTING_SHA256", "UNMERGE_JSON_PATHS", "UNMERGE_ENTRIES", "HOOK_FILE_NAME",
    ]
)
_ALLCAPS_TOKEN_RE = re.compile(r"^[A-Z][A-Z0-9_]{3,}$")
#: Any ATX heading, used to find where the removal section ends.
_HEADING_RE = re.compile(r"^(#{1,6})[ \t]+\S")

#: The ordering assertions `_order_problems` makes, most specific first.  Two
#: of them can see the same step -- an `rmdir` printed too early is both "this
#: removes something a later step needs" and "this runs on a directory that is
#: not empty yet" -- and the second sentence is the one that names the failure
#: the reader will actually see, so it wins.  One row per step, never two.
#: How many ordering rows to print before collapsing the rest into a count.
_ORDER_ROWS_MAX = 4
_ORDER_RULES = (
    "rmdir-early",
    "instructions",
    "script-below-delete",
    "last-delete",
    "confirm-early",
    "save-first",
    "ref",
    "needs",
)

#: -------------------------------------------------------------------------
#: TARGET PROFILES -- the one place a target name appears in this file.
#: -------------------------------------------------------------------------
#: Every check below is target-agnostic and asks this table instead.  Adding a
#: third target is a new row here; it is NOT an edit to a check, a constant or
#: a message.  That is the whole point: the previous shape of this file put
#: `.claude/...` in a fixed list and `if target == "codex"` in a check, and the
#: result was a correct Codex hook reported as a dead file.
#:
#: BOTH targets have a full, native hook system.  Codex has 12 events, regex
#: matchers over tool names, a JSON `hookSpecificOutput` / `permissionDecision`
#: protocol and a repo-scoped, committable `.codex/hooks.json` whose shape is
#: the same three levels as Claude Code's `settings.json` -- event -> matcher
#: group -> the group's own `hooks` array (adapters/codex.md 4.3, VERIFIED
#: against codex-cli 0.152.1).  Any statement that Codex substitutes prose or a
#: git hook for a real hook is stale and wrong.
DEFAULT_TARGET = "claude-code"

#: Spellings a manifest may carry for a target, normalized to a profile key.
_TARGET_ALIASES = {
    "claude": "claude-code",
    "claude-code": "claude-code",
    "claude_code": "claude-code",
    "claudecode": "claude-code",
    "cc": "claude-code",
    "codex": "codex",
    "codex-cli": "codex",
    "openai-codex": "codex",
}

TARGET_PROFILES = {
    "claude-code": {
        "label": "Claude Code",
        #: Repo-scoped files a `hooks` block can legitimately live in, searched
        #: in this order when the manifest names no `settings` or `plugin`
        #: artifact.  `plugin.json` uses the SAME hooks shape as
        #: `settings.json` (adapters/claude-code.md 4.7), so one reader covers
        #: both and a plugin-registered hook is not reported as dead.
        "hook_registries": (
            ".claude/settings.json",
            ".claude/settings.local.json",
            ".claude-plugin/plugin.json",
        ),
        #: User-scope registries, as (env var naming the home, its default, the
        #: file inside it).  agentify never WRITES one -- a global hook fires in
        #: every repo -- but a user may have wired this repo's hook there by
        #: hand, and a hook that really does run must not be reported dead.
        #: Resolved through the env var exactly as the adapter requires;
        #: `~/.claude` is never hardcoded (adapters/claude-code.md 1.2).
        "user_hook_registries": (("CLAUDE_CONFIG_DIR", "~/.claude", "settings.json"),),
        #: The registry agentify itself writes, and the one `settings_json`
        #: reads when the manifest names no `settings` artifact.
        "primary_registry": ".claude/settings.json",
        #: Top-level keys the registry file accepts, or None for "no such
        #: rule".  Codex's `hooks.json` rejects an unknown top-level key and
        #: then loads ZERO hooks, reported only as a warning nobody sees.
        "registry_allowed_keys": None,
        "registry_doc": "adapters/claude-code.md 4.3 merge rule",
        "hook_dir": ".claude/hooks",
        "rules_dir": ".claude/rules",
        "index_doc": "CLAUDE.md",
        #: Variables that mean "the repo root" in a hook command on this
        #: target, expanded by `expand_command` and set for real by the smoke
        #: sandbox.  Codex defines none -- the portable idiom there is
        #: `$(git rev-parse --show-toplevel)`, which every target understands.
        "project_dir_vars": ("CLAUDE_PROJECT_DIR",),
        #: Environment the smoke test gives a hook ON THIS TARGET, as
        #: (name, path relative to the throwaway fixture; "" is the fixture
        #: itself).  Nothing from the parent environment reaches a hook through
        #: this: the values are fixture paths, always.
        "hook_env_dirs": (("CLAUDE_PROJECT_DIR", ""),),
    },
    "codex": {
        "label": "Codex",
        #: `.codex/hooks.json` -- repo-scoped, committable, and the file Codex
        #: really reads (adapters/codex.md 4.3, VERIFIED: written, then
        #: reported back by the app-server's `hooks/list`).
        "hook_registries": (".codex/hooks.json",),
        #: `${CODEX_HOME:-~/.codex}/hooks.json` loads as `source: "user"`
        #: (VERIFIED).  agentify never writes it; it is searched for the same
        #: reason as Claude Code's user scope.
        "user_hook_registries": (("CODEX_HOME", "~/.codex", "hooks.json"),),
        "primary_registry": ".codex/hooks.json",
        #: MEASURED: a `_agentify` key beside `hooks` produced `unknown field
        #: `_agentify`, expected `description` or `hooks`` and the whole file
        #: then loaded zero hooks -- surfaced only in `hooks/list` warnings.
        "registry_allowed_keys": frozenset(["description", "hooks"]),
        "registry_doc": "adapters/codex.md 4.3 merge rule",
        "hook_dir": ".codex/hooks",
        "rules_dir": ".codex/rules",
        "index_doc": "AGENTS.md",
        #: No documented repo-root variable exists on Codex.  Inventing one
        #: (`$CODEX_PROJECT_DIR`) would let a broken command resolve here and
        #: fail silently in the user's session, so the list is empty on
        #: purpose and `$(git rev-parse --show-toplevel)` carries the weight.
        "project_dir_vars": (),
        #: `CODEX_HOME` is VERIFIED as exported into commands Codex spawns, and
        #: it is pointed at a scratch directory so a hook cannot read or write
        #: the real one.  `CODEX_SANDBOX` is deliberately NOT set: it is only
        #: present when Codex really is sandboxing the command, this sandbox is
        #: agentify's and not Codex's, and asserting it would tell the hook a
        #: lie about where it is running.
        "hook_env_dirs": (("CODEX_HOME", ".codex-home"),),
    },
}


def normalize_target(value: Any) -> str:
    """A manifest `target` string reduced to a profile key, or "" if unknown."""
    text = str(value or "").strip().lower().replace(" ", "-")
    if not text:
        return ""
    if text in TARGET_PROFILES:
        return text
    return _TARGET_ALIASES.get(text, "")


def target_profile(value: Any) -> Dict[str, Any]:
    """The profile for a manifest `target`, falling back to the default one."""
    return TARGET_PROFILES[normalize_target(value) or DEFAULT_TARGET]

