# ---------------------------------------------------------------------------
# Small helpers
# ---------------------------------------------------------------------------


def _short(text: Any, limit: int = DETAIL_MAX) -> str:
    """One-line, length-bounded detail string."""
    value = "" if text is None else str(text)
    value = value.replace("\r", " ").replace("\n", " ").replace("\t", " ")
    value = re.sub(r"\s{2,}", " ", value).strip()
    if len(value) > limit:
        value = value[: limit - 3].rstrip() + "..."
    return value


def _safe_detail(text: Any, limit: int = DETAIL_MAX) -> str:
    """Detail string that may have touched user content: scrub it first."""
    cleaned, _hits = scrub_lib.scrub(_short(text, limit * 2))
    return _short(cleaned, limit)


def _join_and(items: Sequence[Any], limit: int = 3) -> str:
    """
    A list of names joined so the reader can tell how many there were.

    `a` / `a and b` / `a, b and c` / `a, b, c and 2 more`.  `", ".join(x[:3])`
    is what this replaces: it silently drops the fourth name AND reads as one
    name when the list has one, which is how `hook_wired`'s failure came to say
    "no hook command in .claude/settings.json" about a search that had also
    looked in two other registries.
    """
    values = [str(item) for item in items if str(item).strip()]
    if not values:
        return ""
    if len(values) > limit:
        head, tail = values[:limit], "%d more" % (len(values) - limit)
    else:
        head, tail = values[:-1], values[-1]
    if not head:
        return tail
    return "%s and %s" % (", ".join(head), tail)


#: Wrapping quotes/backticks and trailing sentence punctuation, which a
#: template or a hand edit adds without changing the claim.
_EVIDENCE_EDGE = re.compile(r"^[\s\"'`‘’“”]+|[\s\"'`‘’“”.,;:]+$")
_EVIDENCE_SMART = {
    "‘": "'",
    "’": "'",
    "“": '"',
    "”": '"',
    "–": "-",
    "—": "-",
    "×": "x",
}


def _normalize_evidence(value: Any) -> str:
    """
    Compare-ready form of an evidence line.

    Whitespace, wrapping quotes, smart punctuation and letter case are noise --
    two evidence strings that differ only in those are the same claim.  Counts,
    field names and wording are content and survive untouched, so a rewritten
    evidence line still compares unequal.
    """
    text = str(value or "")
    for source, target in _EVIDENCE_SMART.items():
        text = text.replace(source, target)
    text = re.sub(r"\s+", " ", text).strip()
    text = _EVIDENCE_EDGE.sub("", text)
    return text.lower()


def _norm_type(value: Any) -> Tuple[str, bool]:
    """Return (canonical type, known)."""
    raw = str(value or "").strip().lower()
    if raw in _TYPE_SYNONYMS:
        return (_TYPE_SYNONYMS[raw], True)
    if raw in CANONICAL_TYPES:
        return (raw, True)
    return ("other", False)


def _is_json_path(path: str) -> bool:
    """
    Is this file really JSON?

    `JSON_TYPES` and `MERGED_JSON_TYPES` name TYPES, and one of them changes
    format between targets: Codex MCP configuration is TOML
    (`[mcp_servers.<name>]` tables), not a `mcpServers` JSON object.  Every
    JSON-shaped exemption is keyed on this rather than on the type name, so a
    TOML artifact is never handed a JSON reader or a JSON un-merge script.
    """
    return str(path or "").lower().endswith(".json")


def _is_markdown(path: str) -> bool:
    lowered = path.lower()
    return lowered.endswith(".md") or lowered.endswith(".markdown") or lowered.endswith(".mdx")


def _read_text(path: str) -> Tuple[str, Optional[str]]:
    """Read a file as text.  Returns (text, error)."""
    try:
        size = os.path.getsize(path)
    except OSError as exc:
        return ("", str(exc))
    if size > MAX_READ_BYTES:
        return ("", "file too large to inspect (%d bytes)" % size)
    try:
        handle = open(path, "r", encoding="utf-8", errors="replace")
    except OSError as exc:
        return ("", str(exc))
    try:
        return (handle.read(), None)
    except OSError as exc:  # pragma: no cover - defensive
        return ("", str(exc))
    finally:
        handle.close()


# ---------------------------------------------------------------------------
# Minimal frontmatter parser (no pyyaml -- it is not stdlib)
# ---------------------------------------------------------------------------

_FM_KEY = re.compile(r"^([A-Za-z0-9_.$-][A-Za-z0-9_.$ -]{0,80}?)\s*:\s*(.*)$")
_BLOCK_ITEM = re.compile(r"^[ \t]+-\s+(.*)$")
_BLOCK_SCALAR = re.compile(r"^[|>][+-]?$")


def _strip_inline_comment(value: str) -> str:
    """Drop a trailing ` # comment`, respecting quotes."""
    out = []
    quote = None
    index = 0
    while index < len(value):
        char = value[index]
        if quote:
            if char == "\\" and quote == '"' and index + 1 < len(value):
                out.append(char)
                out.append(value[index + 1])
                index += 2
                continue
            if char == quote:
                quote = None
            out.append(char)
        else:
            if char in "\"'":
                quote = char
                out.append(char)
            elif char == "#" and (not out or out[-1] in " \t"):
                break
            else:
                out.append(char)
        index += 1
    return "".join(out).strip()


def _unquote(value: str) -> str:
    text = value.strip()
    if len(text) >= 2 and text[0] == text[-1] and text[0] in "\"'":
        inner = text[1:-1]
        if text[0] == '"':
            inner = inner.replace('\\"', '"').replace("\\n", "\n").replace("\\\\", "\\")
        else:
            inner = inner.replace("''", "'")
        return inner
    return text


def _parse_inline_list(value: str) -> Optional[List[str]]:
    """`[a, b, "c, d"]` -> ["a", "b", "c, d"].  None when malformed."""
    text = value.strip()
    if not (text.startswith("[") and text.endswith("]")):
        return None
    body = text[1:-1]
    items = []  # type: List[str]
    current = []  # type: List[str]
    quote = None
    depth = 0
    for char in body:
        if quote:
            if char == quote:
                quote = None
            current.append(char)
            continue
        if char in "\"'":
            quote = char
            current.append(char)
        elif char in "[{":
            depth += 1
            current.append(char)
        elif char in "]}":
            depth -= 1
            if depth < 0:
                return None
            current.append(char)
        elif char == "," and depth == 0:
            items.append("".join(current))
            current = []
        else:
            current.append(char)
    if quote is not None or depth != 0:
        return None
    tail = "".join(current)
    if tail.strip() or items:
        items.append(tail)
    return [_unquote(item) for item in items if _unquote(item) != ""]


def parse_frontmatter(text: str) -> Dict[str, Any]:
    """
    Minimal, forgiving YAML-frontmatter reader.

    Supports: the `---` delimited block, flat `key: value` scalars, quoted
    strings, inline lists (`[a, b]`) and simple block sequences (`- item`
    lines).  Anything richer -- nested mappings, block scalars, anchors,
    multi-document streams -- is recorded in `notes` and skipped.  Notes are
    reported as a WARN by the caller; only a structurally broken block (no
    closing delimiter) sets `ok` to False.

    Returns:
        {"present": bool, "ok": bool, "data": {k: str|list},
         "notes": [str], "body": str}
    """
    result = {
        "present": False,
        "ok": True,
        "data": {},
        "notes": [],
        "body": text or "",
    }  # type: Dict[str, Any]
    if not text:
        return result

    stripped = text
    if stripped.startswith("\ufeff"):
        stripped = stripped[1:]

    lines = stripped.split("\n")
    if not lines or lines[0].strip() not in ("---", "---\r"):
        return result
    if lines[0].strip() != "---":
        return result

    result["present"] = True

    end = -1
    for index in range(1, len(lines)):
        candidate = lines[index].strip()
        if candidate in ("---", "..."):
            end = index
            break
    if end < 0:
        result["ok"] = False
        result["notes"].append("frontmatter block is never closed with ---")
        return result

    result["body"] = "\n".join(lines[end + 1 :])
    block = lines[1:end]

    data = result["data"]  # type: Dict[str, Any]
    notes = result["notes"]  # type: List[str]

    index = 0
    while index < len(block):
        raw = block[index]
        line = raw.rstrip()
        if not line.strip() or line.lstrip().startswith("#"):
            index += 1
            continue
        if line[0] in " \t":
            notes.append("indented line not attached to a key: %s" % _short(line, 60))
            index += 1
            continue
        if line.lstrip().startswith("- "):
            notes.append("top-level sequence is not supported")
            index += 1
            continue

        match = _FM_KEY.match(line)
        if not match:
            notes.append("unparseable line: %s" % _short(line, 60))
            index += 1
            continue

        key = match.group(1).strip()
        rest = _strip_inline_comment(match.group(2))

        if rest == "":
            items = []  # type: List[str]
            look = index + 1
            while look < len(block):
                item = _BLOCK_ITEM.match(block[look])
                if not item:
                    break
                items.append(_unquote(_strip_inline_comment(item.group(1))))
                look += 1
            if items:
                data[key] = items
                index = look
                continue
            look = index + 1
            nested = False
            while look < len(block) and block[look].strip() and block[look][0] in " \t":
                nested = True
                look += 1
            if nested:
                notes.append("nested mapping under '%s' not parsed" % key)
                data[key] = ""
                index = look
                continue
            data[key] = ""
            index += 1
            continue

        if _BLOCK_SCALAR.match(rest):
            look = index + 1
            chunk = []  # type: List[str]
            while look < len(block) and (not block[look].strip() or block[look][0] in " \t"):
                chunk.append(block[look].strip())
                look += 1
            notes.append("block scalar for '%s' read as plain text" % key)
            data[key] = " ".join(part for part in chunk if part)
            index = look
            continue

        if rest.startswith("["):
            items_or_none = _parse_inline_list(rest)
            if items_or_none is None:
                notes.append("malformed inline list for '%s'" % key)
                data[key] = rest
            else:
                data[key] = items_or_none
            index += 1
            continue

        if rest.startswith("{"):
            notes.append("inline mapping for '%s' not parsed" % key)
            data[key] = rest
            index += 1
            continue

        data[key] = _unquote(rest)
        index += 1

    return result


#: A top-level TOML assignment: bare key, `=`, value.  Codex subagents are TOML
#: (`.codex/agents/<name>.toml`), so the identity a markdown subagent carries in
#: YAML frontmatter lives here instead.
_TOML_ASSIGN = re.compile(r"^([A-Za-z0-9_-]+)\s*=\s*(.*)$")
_TOML_TABLE = re.compile(r"^\[")


def read_toml_scalars(text: str, max_lines: int = 800) -> Tuple[Dict[str, str], Optional[str]]:
    """
    `({top-level key: value as text}, error)` for a small TOML file.

    A bounded hand reader, not `tomllib`: that is 3.11+ and these scripts target
    3.9, and discover.py already reads Codex's `config.toml` the same way rather
    than take a dependency.  Only what the check needs is understood -- top-level
    scalars and `\"\"\"`/`'''` blocks -- and reading STOPS at the first `[table]`
    header, so a key nested under one is never mistaken for a top-level one.
    Multi-line string bodies are skipped as data, so `name = ...` written INSIDE
    `developer_instructions` cannot masquerade as the agent's name.
    """
    values = {}  # type: Dict[str, str]
    lines = str(text or "").split("\n")
    if len(lines) > max_lines:
        lines = lines[:max_lines]
    index = 0
    while index < len(lines):
        line = lines[index]
        stripped = line.strip()
        index += 1
        if not stripped or stripped.startswith("#"):
            continue
        if _TOML_TABLE.match(stripped):
            break
        match = _TOML_ASSIGN.match(stripped)
        if not match:
            continue
        key = match.group(1).strip().lower()
        rest = match.group(2).strip()
        for fence in ('"""', "'''"):
            if not rest.startswith(fence):
                continue
            body = [rest[len(fence) :]]
            if body[0].endswith(fence) and len(rest) > 2 * len(fence) - 1:
                values.setdefault(key, body[0][: -len(fence)].strip())
                rest = ""
                break
            closed = False
            while index < len(lines):
                current = lines[index]
                index += 1
                position = current.find(fence)
                if position >= 0:
                    body.append(current[:position])
                    closed = True
                    break
                body.append(current)
            values.setdefault(key, "\n".join(body).strip())
            if not closed:
                return (values, "unterminated %s string for `%s`" % (fence, key))
            rest = ""
            break
        if not rest:
            continue
        values.setdefault(key, _unquote(_strip_inline_comment(rest).strip()))
    return (values, None)


# ---------------------------------------------------------------------------
# agentify markers
# ---------------------------------------------------------------------------

_MARKER = re.compile(
    r"^[ \t]*(?:<!--|//|/\*|\#|--|;|%|\*)?[ \t]*"
    r"agentify[ :_-]{0,3}(begin|start|end)\b(?P<rest>[^\n]*)$",
    re.IGNORECASE | re.MULTILINE,
)
#: `begin` is the only spelling anything emits (see templates/index-doc-section.md.tmpl).
#: `start` is kept ONLY so a rerun can still find a block written by an older agentify;
#: removing it would orphan those blocks and a rerun would append a duplicate.
_MARKER_KIND_ALIASES = {"begin": "begin", "start": "begin", "end": "end"}
_MARKER_ID = re.compile(r"\bid[ \t]*[=:][ \t]*[\"']?([A-Za-z0-9._/-]{1,120})")
_MARKER_BARE = re.compile(r"([A-Za-z0-9][A-Za-z0-9._/-]{1,120})")


def find_markers(text: str) -> List[Dict[str, Any]]:
    """All agentify begin/end markers, in file order."""
    found = []  # type: List[Dict[str, Any]]
    if not text:
        return found
    for match in _MARKER.finditer(text):
        kind = _MARKER_KIND_ALIASES.get(match.group(1).lower(), match.group(1).lower())
        rest = match.group("rest") or ""
        rest = rest.replace("-->", " ").replace("*/", " ").strip(" \t:=-")
        marker_id = None
        id_match = _MARKER_ID.search(rest)
        if id_match:
            marker_id = id_match.group(1)
        else:
            bare = _MARKER_BARE.search(rest)
            if bare and bare.group(1).lower() not in ("id", "block", "section"):
                marker_id = bare.group(1)
        found.append({"kind": kind, "id": marker_id, "pos": match.start()})
    return found


def marker_block(text: str, artifact_id: str) -> str:
    """Text between the begin/end pair for `artifact_id` (or "")."""
    markers = find_markers(text)
    begin = None
    for marker in markers:
        if marker["kind"] == "begin" and (marker["id"] == artifact_id or marker["id"] is None):
            begin = marker
            break
    if begin is None:
        return ""
    for marker in markers:
        if marker["pos"] <= begin["pos"] or marker["kind"] != "end":
            continue
        if marker["id"] == artifact_id or marker["id"] is None:
            newline = text.find("\n", begin["pos"])
            start = newline + 1 if newline >= 0 else begin["pos"]
            return text[start : marker["pos"]]
    return ""


# ---------------------------------------------------------------------------
# agentify-* metadata
# ---------------------------------------------------------------------------

_META_LINE = re.compile(
    r"^[^\n]{0,20}?\b(agentify[-_](?:id|version|generated|evidence))\s*[:=]\s*(.+?)\s*$",
    re.IGNORECASE | re.MULTILINE,
)


def collect_metadata(text: str, frontmatter: Dict[str, Any]) -> Dict[str, str]:
    """
    Gather `agentify-*` metadata from wherever a given file type can carry it:
    markdown frontmatter keys, `# agentify-id: x` comment-header lines, or (for
    JSON) top-level object keys.  Underscored spellings are normalised.
    """
    meta = {}  # type: Dict[str, str]

    for key, value in (frontmatter.get("data") or {}).items():
        normalized = str(key).strip().lower().replace("_", "-")
        if normalized in REQUIRED_META:
            meta[normalized] = value if isinstance(value, str) else _short(value, 200)

    for match in _META_LINE.finditer(text or ""):
        normalized = match.group(1).lower().replace("_", "-")
        if normalized not in meta or not meta[normalized]:
            # `<!-- agentify-id: x -->` and `/* agentify-id: x */` must not keep
            # their closing delimiter as part of the value.
            value = re.sub(r"(?:-->|\*/|#\}|\}\})\s*$", "", match.group(2)).strip()
            meta[normalized] = _unquote(value.rstrip(",").strip())

    text_head = (text or "").lstrip()
    if text_head.startswith("{"):
        try:
            parsed = json.loads(text)
        except (ValueError, TypeError):
            parsed = None
        if isinstance(parsed, dict):
            containers = [parsed]
            for nested_key in ("_agentify", "agentify", "$agentify"):
                nested = parsed.get(nested_key)
                if isinstance(nested, dict):
                    containers.append(nested)
            for container in containers:
                for key, value in container.items():
                    normalized = str(key).strip().lower().replace("_", "-")
                    if not normalized.startswith("agentify-"):
                        normalized = "agentify-" + normalized
                    if normalized in REQUIRED_META and normalized not in meta:
                        meta[normalized] = value if isinstance(value, str) else _short(value, 200)

    return dict((key, str(value).strip()) for key, value in meta.items() if str(value).strip())


# ---------------------------------------------------------------------------
# Glob validation
# ---------------------------------------------------------------------------


def validate_glob(pattern: str) -> Optional[str]:
    """Return an error string when `pattern` is not a usable glob, else None."""
    if pattern is None:
        return "empty glob"
    text = str(pattern).strip()
    if not text:
        return "empty glob"
    if text.startswith("/") and not text.startswith("//"):
        # A leading slash is a legal "repo-root anchored" convention; only flag
        # a real filesystem escape.
        if text.startswith("/Users/") or text.startswith("/home/") or text.startswith("/etc"):
            return "absolute filesystem path, not a repo-relative glob"
    if ".." in text.replace("...", "").split("/"):
        return "glob escapes the repo with '..'"
    if text.count("[") != text.count("]"):
        return "unbalanced [ ] in glob"
    if text.count("{") != text.count("}"):
        return "unbalanced { } in glob"
    if "***" in text:
        return "'***' is not a valid glob wildcard"
    try:
        re.compile(fnmatch.translate(text))
    except re.error as exc:
        return "glob does not compile: %s" % exc
    return None


def extract_globs(value: Any) -> List[str]:
    """Coerce a scope field (string, comma list, or YAML list) to globs."""
    if value is None:
        return []
    if isinstance(value, list):
        out = []  # type: List[str]
        for item in value:
            out.extend(extract_globs(item))
        return out
    text = str(value).strip()
    if not text:
        return []
    inline = _parse_inline_list(text)
    if inline is not None:
        return [item.strip() for item in inline if item.strip()]
    parts = [part.strip() for part in re.split(r"[,\s]+", text) if part.strip()]
    return parts


# ---------------------------------------------------------------------------
# Command resolution + hook execution
# ---------------------------------------------------------------------------

_SHELL_META = re.compile(r"&&|\|\||[|;&<>]|\$\(|`")
_SCRIPT_SUFFIXES = (".sh", ".bash", ".zsh", ".py", ".js", ".mjs", ".cjs", ".ts", ".rb", ".pl")

#: Start-of-token in a shell line: line start, whitespace, or a shell operator.
_CMD_LEAD = r"(?:^|[\s;&|(){}`$=\"'])"

#: Anything here in a generated hook means the hook can reach the network, and
#: agentify must not execute it.  Two tiers: `_NETWORK_HARD` is a fail on sight;
#: `_NETWORK_SOFT` is inert text that merely LOOKS like one -- a bare remote URL
#: with no consumer on the line, or a hard pattern that falls inside something
#: the shell cannot execute (see `scan_network_calls`) -- and only warns.
_NETWORK_HARD = [
    ("curl", re.compile(_CMD_LEAD + r"curl\b")),
    ("wget", re.compile(_CMD_LEAD + r"wget\b")),
    ("nc/netcat", re.compile(_CMD_LEAD + r"(?:nc|ncat|netcat)\b")),
    ("ssh/scp/sftp", re.compile(_CMD_LEAD + r"(?:ssh|scp|sftp)\b")),
    ("telnet/ftp", re.compile(_CMD_LEAD + r"(?:telnet|ftp|tftp)\b")),
    ("rsync to a remote host", re.compile(_CMD_LEAD + r"rsync\b[^\n]*\s[\w.-]+@[\w.-]+:")),
    ("bash /dev/tcp socket", re.compile(r"/dev/(?:tcp|udp)/")),
    (
        "python http client",
        re.compile(
            r"\b(?:urllib2?|urllib3|requests|httpx|aiohttp|http\.client|httplib|"
            r"socket\.(?:socket|create_connection)|xmlrpc\.client)\b"
        ),
    ),
    (
        "node http client",
        re.compile(
            r"\bfetch\s*\(|\brequire\(\s*[\"'](?:node:)?(?:https?|net|dgram|axios|node-fetch|got|"
            r"undici)[\"']|\bfrom\s+[\"'](?:axios|node-fetch|got|undici)[\"']|\bXMLHttpRequest\b"
        ),
    ),
    (
        "package install",
        re.compile(
            _CMD_LEAD + r"(?:npm|pnpm|yarn|bun|bunx|npx|pip|pip3|gem|cargo|go|brew|apt|apt-get|"
            r"apk|composer)\s+(?:install|add|get|i|ci)\b"
        ),
    ),
    (
        "remote git operation",
        re.compile(_CMD_LEAD + r"git\s+(?:[^\n]{0,40}\s)?(?:push|pull|fetch|clone|ls-remote|submodule)\b"),
    ),
    ("gh api call", re.compile(_CMD_LEAD + r"gh\s+(?:api|repo|pr|issue|release)\b")),
]

_NETWORK_SOFT = [
    (
        "remote URL literal",
        re.compile(r"https?://(?!localhost\b|127\.0\.0\.1|0\.0\.0\.0|\[::1\])[A-Za-z0-9]"),
    ),
]

#: A line whose first non-blank character starts a comment carries no behavior.
_COMMENT_LINE = re.compile(r"^\s*(?:#|//|--|;)")

#: A heredoc whose delimiter is QUOTED (`<<'EOF'`, `<<-"EOF"`) expands nothing:
#: the body is data the shell hands to the reader verbatim.  Both hook
#: templates carry the block message that way -- `BLOCK_REASON="$(cat
#: <<'AGENTIFY_BLOCK_REASON' ... )"` -- and the message a package-manager hook
#: exists to print is, of course, "Fix: run bun install".  Scanned as code that
#: is a "package install" hit, which FAILED the hook, refused to smoke-test it,
#: and told the model to rewrite or remove a correct artifact.  MEASURED on the
#: canonical hook of both targets.
_HEREDOC_QUOTED = re.compile(r"<<-?\s*(['\"])([A-Za-z_][A-Za-z0-9_]*)\1")

#: A line that only prints.  `printf`/`echo` cannot execute their argument, so
#: a match inside a SINGLE-quoted argument of one is text -- single quotes
#: permit no substitution at all in POSIX sh.
_PRINT_ONLY_LINE = re.compile(r"^\s*(?:printf|echo)\b")


def _inside_single_quotes(raw: str, match: Any) -> bool:
    """
    Is the matched COMMAND inside a single-quoted span?

    Quote parity is the whole rule in POSIX sh: nothing, not even a backslash,
    escapes inside `'...'`.  The offset counted from is the first character of
    the command itself, not of the match: every hard pattern begins with
    `_CMD_LEAD`, and when that lead character is the opening quote (`echo
    'curl ...'`) counting from it would put the command outside its own span.
    """
    start = match.start()
    while start < match.end() and not (raw[start].isalnum() or raw[start] == "_"):
        start += 1
    return raw.count("'", 0, start) % 2 == 1


def _scan_line(
    raw: str,
    line: str,
    number: int,
    inert: str,
    hard: List[Dict[str, Any]],
    soft: List[Dict[str, Any]],
) -> None:
    """
    Judge one line of a hook and append at most one hit.

    `inert` is non-empty when the line is already known to be data (a quoted
    heredoc body).  A hard pattern that lands in inert text -- or inside a
    single-quoted argument of a `printf`/`echo` that pipes nowhere -- is
    downgraded to a soft hit: text a hook PRINTS is not a call a hook MAKES.
    It is downgraded rather than dropped, so the line is still reported and
    still visible to a human, but it no longer fails the build and no longer
    blocks the smoke test.
    """
    for kind, pattern in _NETWORK_HARD:
        found = pattern.search(raw)
        if not found:
            continue
        reason = inert
        if (
            not reason
            and _PRINT_ONLY_LINE.match(raw)
            and "|" not in raw
            and _inside_single_quotes(raw, found)
        ):
            reason = "text in a single-quoted argument of printf/echo"
        if reason:
            soft.append(
                {
                    "kind": "%s -- %s, not a call" % (kind, reason),
                    "line": number,
                    "text": _short(line, 160),
                }
            )
        else:
            hard.append({"kind": kind, "line": number, "text": _short(line, 160)})
        return

    for kind, pattern in _NETWORK_SOFT:
        if pattern.search(raw):
            soft.append({"kind": kind, "line": number, "text": _short(line, 160)})
            return


def scan_network_calls(text: str, max_lines: int = 4000) -> Tuple[List[Dict[str, Any]], List[Dict[str, Any]]]:
    """
    Static scan for anything that could take a hook to the network.

    Comment-only lines are skipped -- a `# see https://...` header is not a
    network call, and treating it as one would delete good hooks.  Returns
    (hard hits, soft hits); each hit is
    {"kind": str, "line": int, "text": str}.
    """
    hard = []  # type: List[Dict[str, Any]]
    soft = []  # type: List[Dict[str, Any]]
    if not text:
        return (hard, soft)

    #: The delimiter of the quoted heredoc currently open, or "".  Set only by
    #: a real code line: a heredoc whose delimiter is quoted expands nothing,
    #: so its body is data.  `cat <<'EOF' | sh` DOES execute its body, so a pipe
    #: on the opener keeps the body live and every hit inside it hard.
    heredoc_delim = ""

    for number, raw in enumerate((text or "").split("\n")[:max_lines], start=1):
        line = raw.strip()
        inert = ""
        if heredoc_delim:
            if line == heredoc_delim:
                heredoc_delim = ""
                continue
            inert = "text inside a quoted heredoc"
        if not line or _COMMENT_LINE.match(raw):
            continue

        _scan_line(raw, line, number, inert, hard, soft)

        # Judged AFTER this line, which is itself ordinary code, and never from
        # a comment: `# cat <<'EOF'` in a header must not put the rest of the
        # file inside a heredoc.
        if not heredoc_delim:
            opener = _HEREDOC_QUOTED.search(raw)
            if opener and "|" not in raw:
                heredoc_delim = opener.group(2)
    return (hard, soft)


# ---------------------------------------------------------------------------
# Hook execution sandbox
# ---------------------------------------------------------------------------

#: The ONLY parent-environment variables a smoke-tested hook inherits.  The env
#: is built from this allowlist rather than filtered down from `os.environ`, so
#: a variable can only reach a hook by being named here.
ENV_ALLOWLIST = ("PATH", "HOME")

#: Belt and braces over the allowlist: even a future edit that passes something
#: through cannot leak a credential-shaped variable.
_SECRET_ENV_NAME = re.compile(
    r"(?:^|_)(?:KEY|TOKEN|SECRET|PASSWORD|PASSWD|PWD|CREDENTIAL|CREDENTIALS|AUTH|"
    r"SESSION|COOKIE|DSN|CONNECTION|LICENSE|LICENCE|PAT)(?:$|_)"
    r"|^(?:AWS|GCP|GOOGLE|AZURE|ANTHROPIC|OPENAI|GITHUB|GH|GITLAB|NPM|DOCKER|STRIPE|"
    r"SLACK|TWILIO|SENDGRID|SUPABASE|VERCEL|CLOUDFLARE|DATABASE|POSTGRES|MYSQL|MONGO|"
    r"REDIS|SSH|GPG|OP|VAULT)_",
    re.IGNORECASE,
)

_SAFE_PATH = "/usr/local/bin:/usr/bin:/bin:/usr/sbin:/sbin"


def minimal_env(fixture_dir: str, target: Any = None) -> Dict[str, str]:
    """
    The environment a smoke-tested hook runs in, ON ITS OWN TARGET.

    Allowlist first (`PATH`, `HOME`), then agentify's own marker, then the
    variables the TARGET's own harness sets -- `CLAUDE_PROJECT_DIR` on Claude
    Code, `CODEX_HOME` on Codex -- then an explicit strip pass so the intent is
    visible in the source and not only in the shape of the dict.

    Every value agentify sets is a path inside the throwaway fixture: `HOME`,
    the target's variables and `cwd` all point there, never at the user's home,
    the user's repo, or the real `${CODEX_HOME}`.  Nothing else from the parent
    environment is passed through -- no `*_KEY`, `*_TOKEN`, `*_SECRET`, `AWS_*`
    -- and the strip pass below re-checks that.

    Before this was target-aware a Codex hook ran with `CLAUDE_PROJECT_DIR` set
    and no `CODEX_*` variable at all: a Claude-shaped environment, which is a
    test of something the user will never run.
    """
    profile = target_profile(target)

    env = {}  # type: Dict[str, str]
    for name in ENV_ALLOWLIST:
        value = os.environ.get(name)
        if isinstance(value, str) and value:
            env[name] = value
    env.setdefault("PATH", _SAFE_PATH)
    # A hook must not be able to read or write the real home directory by
    # accident, so HOME is the throwaway fixture for the duration of the test.
    env["HOME"] = fixture_dir
    env["TMPDIR"] = fixture_dir
    env["AGENTIFY_VERIFY"] = "1"

    ours = set(["PATH", "HOME", "TMPDIR", "AGENTIFY_VERIFY"])
    for name, relative in profile["hook_env_dirs"]:
        path = os.path.join(fixture_dir, relative) if relative else fixture_dir
        if relative:
            try:
                os.makedirs(path)
            except OSError:
                pass
        env[name] = path
        ours.add(name)

    for name in list(env.keys()):
        if name in ours:
            continue
        if _SECRET_ENV_NAME.search(name):  # pragma: no cover - unreachable by construction
            del env[name]
    return env


def absolutize_command(command: str, repo: str, target: Any = None) -> str:
    """
    Anchor repo-relative path tokens against the repo root.

    The smoke test runs with `cwd` in a throwaway fixture, not in the repo, so
    a manifest command written as `.claude/hooks/x.sh` would no longer resolve.
    Best-effort and deliberately narrow: only tokens that already name an
    existing file under the repo are rewritten, longest first so one token
    cannot clobber a prefix of another.
    """
    text = expand_command(command, repo, target)
    tokens = split_command(text)
    for token in sorted(set(tokens), key=len, reverse=True):
        if not token or "$" in token or os.path.isabs(token):
            continue
        if "/" not in token and not token.lower().endswith(_SCRIPT_SUFFIXES):
            continue
        candidate = os.path.normpath(os.path.join(repo, os.path.expanduser(token)))
        if os.path.isfile(candidate):
            text = text.replace(token, candidate)
    return text


def strip_command_comments(command: str) -> str:
    """
    Drop whole-line `#` comments from a registered hook command.

    The canonical Claude Code hook command carries its idempotency marker as
    its FIRST LINE -- `"# agentify:<id>\\n$CLAUDE_PROJECT_DIR/.claude/hooks/x.sh"`
    (adapters/claude-code.md 4.3, "Idempotency without frontmatter") -- because
    JSON has no comment syntax.  A shell reads that line as a comment; `shlex`
    does not, so the argv built from it began `["#", "agentify:x", ...]` and
    the smoke test died with `No such file or directory: '#'` on the one hook
    shape agentify itself emits.  Measured: `hook_smoke` could not pass on a
    canonically registered hook.
    """
    lines = [line for line in str(command or "").split("\n") if not line.strip().startswith("#")]
    return "\n".join(lines).strip()


def build_argv(command: str) -> Tuple[List[str], bool]:
    """
    Turn a hook command line into an argv list.  `shell=True` is never used.

    Returns (argv, used_shell).  A command that `shlex` parses cleanly and holds
    no shell metacharacters runs as its own argv.  Anything else runs under the
    literal, visible `["/bin/sh", "-c", cmd]` -- so what executes is readable
    here rather than hidden behind a subprocess flag.
    """
    text = strip_command_comments(command)
    if not text.strip():
        return ([], False)
    if _SHELL_META.search(text):
        return (["/bin/sh", "-c", text], True)
    try:
        argv = shlex.split(text, posix=True)
    except ValueError:
        return (["/bin/sh", "-c", text], True)
    if not argv:
        return ([], False)
    return (argv, False)


#: `$(git rev-parse --show-toplevel)` -- and its backtick spelling -- is the
#: PORTABLE repo-root idiom, and on Codex it is the ONLY one: Codex defines no
#: `CLAUDE_PROJECT_DIR` equivalent, so `adapters/codex.md` 4.3 has every
#: generated hook referenced as
#: `"$(git rev-parse --show-toplevel)/.codex/hooks/<name>.sh"` -- VERIFIED in
#: production use.  Until this was understood here, that command resolved to
#: nothing, `hook_script` failed it, and `hook_wired` could not match it.
_GIT_TOPLEVEL_RE = re.compile(
    r"\$\(\s*git\s+rev-parse\s+--show-toplevel\s*\)"
    r"|`\s*git\s+rev-parse\s+--show-toplevel\s*`"
)

#: Variables meaning "the repo root" on EVERY target.  The target's own are
#: added from its profile, so `CLAUDE_PROJECT_DIR` is expanded on Claude Code
#: and deliberately NOT on Codex: nothing sets it there, a hook command using
#: it would resolve to `/.codex/hooks/x.sh` in the user's real session, and
#: silently resolving it here would hide exactly that defect.
_SHARED_PROJECT_DIR_VARS = ("PROJECT_DIR", "REPO_ROOT", "PWD")

#: Names an unexpanded `$VAR` / `${VAR}` in a command, for the diagnostic.
_UNEXPANDED_VAR_RE = re.compile(r"\$\{?([A-Za-z_][A-Za-z0-9_]*)\}?")


def project_dir_vars(target: Any = None) -> Tuple[str, ...]:
    """Every variable that means "the repo root" on `target`, longest first."""
    names = set(_SHARED_PROJECT_DIR_VARS) | set(target_profile(target)["project_dir_vars"])
    return tuple(sorted(names, key=len, reverse=True))


def expand_command(command: str, repo: str, target: Any = None) -> str:
    """
    Expand what a hook command may legitimately contain on ITS OWN target: the
    portable `$(git rev-parse --show-toplevel)` substitution, and the repo-root
    variables that target actually sets.
    """
    text = _GIT_TOPLEVEL_RE.sub(lambda _m: repo, str(command or ""))
    for name in project_dir_vars(target):
        text = text.replace("${%s}" % name, repo).replace("$%s" % name, repo)
    return text


def split_command(command: str) -> List[str]:
    try:
        return shlex.split(command, posix=True)
    except Exception:
        return [part for part in str(command or "").split() if part]


def resolve_command_path(command: str, repo: str, target: Any = None) -> Tuple[Optional[str], str]:
    """
    Best-effort: which file does this hook command actually run?

    Returns (absolute path or None, note).  Shell-composed commands are
    searched for the first path-looking token; a bare executable name falls
    back to PATH.  Expansion is the target's (`expand_command`), so a command
    naming a variable the target does not set stays unresolved and is reported
    as such rather than being quietly repaired.
    """
    expanded = expand_command(command, repo, target)
    if not expanded.strip():
        return (None, "empty command")

    tokens = split_command(expanded)
    tokens = [token for token in tokens if token not in ("&&", "||", ";", "|", "&")]
    if not tokens:
        return (None, "no command tokens")

    candidates = [
        token
        for token in tokens
        if ("/" in token or token.lower().endswith(_SCRIPT_SUFFIXES)) and not token.startswith("-")
    ]
    if not candidates:
        candidates = [tokens[0]]

    note = ""
    for candidate in candidates:
        cleaned = candidate.strip("\"'")
        if "$" in cleaned:
            found = _UNEXPANDED_VAR_RE.search(cleaned)
            note = "command still contains an unresolved variable%s%s" % (
                (" ($%s)" % found.group(1)) if found else "",
                (
                    " -- %s does not set it; use $(git rev-parse --show-toplevel)"
                    % target_profile(target)["label"]
                )
                if found and found.group(1) not in project_dir_vars(target)
                else "",
            )
            continue
        path = os.path.expanduser(cleaned)
        if not os.path.isabs(path):
            path = os.path.join(repo, path)
        path = os.path.normpath(path)
        # isfile, not exists: `cd "$CLAUDE_PROJECT_DIR" && .claude/hooks/x.sh`
        # puts a directory in front of the script, and a directory carries the
        # execute bit, so `exists` would happily "resolve" the hook to the repo.
        if os.path.isfile(path):
            return (path, note)

    first = candidates[0].strip("\"'")
    if "/" not in first and "$" not in first:
        found = shutil.which(first)
        if found:
            return (found, "resolved via PATH")
    fallback = os.path.expanduser(first)
    if not os.path.isabs(fallback):
        fallback = os.path.normpath(os.path.join(repo, fallback))
    return (fallback if "$" not in fallback else None, note or "not found")


def run_hook(
    command: str, repo: str, timeout: float, fixture_dir: str, target: Any = None
) -> Dict[str, Any]:
    """
    Fail-open smoke test: feed the hook an empty JSON object and see whether it
    gets out of the way.  Returns {"code": int|None, "timeout": bool,
    "stderr": str, "error": str, "shell": bool}.

    The caller has already established that this hook is one THIS run generated
    inside the repo and that its static scan is clean -- see `_check_hook`.
    Here the job is only to contain it: allowlisted environment, cwd in the
    scratch `fixture_dir` rather than the repo, `shell=False`, hard timeout.
    """
    expanded = absolutize_command(command, repo, target)
    argv, used_shell = build_argv(expanded)
    if not argv:
        return {"code": None, "timeout": False, "stderr": "", "error": "empty command", "shell": False}

    kwargs = {
        # NOT the repo: a hook that writes a relative path must land in the
        # throwaway fixture, never in the user's working tree.
        "cwd": fixture_dir,
        "stdin": subprocess.PIPE,
        "stdout": subprocess.PIPE,
        "stderr": subprocess.PIPE,
        "env": minimal_env(fixture_dir, target),
        "shell": False,
    }  # type: Dict[str, Any]
    if os.name == "posix":
        kwargs["start_new_session"] = True

    try:
        proc = subprocess.Popen(argv, **kwargs)
    except OSError as exc:
        return {"code": None, "timeout": False, "stderr": "", "error": str(exc), "shell": used_shell}

    try:
        _out, err = proc.communicate(input=b"{}", timeout=timeout)
        code = proc.returncode
        timed_out = False
    except subprocess.TimeoutExpired:
        _terminate(proc)
        code = None
        err = b""
        timed_out = True
    except Exception as exc:  # pragma: no cover - defensive
        _terminate(proc)
        return {"code": None, "timeout": False, "stderr": "", "error": str(exc), "shell": used_shell}

    try:
        stderr_text = (err or b"").decode("utf-8", "replace")
    except Exception:  # pragma: no cover - defensive
        stderr_text = ""
    return {"code": code, "timeout": timed_out, "stderr": stderr_text, "error": "", "shell": used_shell}


def _terminate(proc: Any) -> None:
    try:
        if os.name == "posix":
            os.killpg(os.getpgid(proc.pid), 9)
        else:  # pragma: no cover - non-posix
            proc.kill()
    except Exception:
        try:
            proc.kill()
        except Exception:  # pragma: no cover - defensive
            pass
    try:
        proc.communicate(timeout=2)
    except Exception:  # pragma: no cover - defensive
        pass


# ---------------------------------------------------------------------------
# Secret detection for .mcp.json
# ---------------------------------------------------------------------------


def _mask_placeholders(text: str) -> str:
    return _PLACEHOLDER_SPAN.sub("PLACEHOLDER", text or "")


def _is_placeholder(value: str) -> bool:
    text = (value or "").strip()
    if not text:
        return True
    if "[REDACTED:" in text:
        return True
    return bool(_PLACEHOLDER_VALUE.match(text))


def scan_json_secrets(node: Any, pointer: str = "") -> List[Dict[str, str]]:
    """
    Walk parsed JSON and report literal-looking secrets, using lib.scrub as the
    detector.  Placeholders (`${VAR}`, `$VAR`, `<token>`, `changeme`, ...) are
    never reported.  Returns [{"kind": ..., "pointer": ...}].
    """
    hits = []  # type: List[Dict[str, str]]

    def _visit(value: Any, path: str, key: str) -> None:
        if isinstance(value, dict):
            for child_key, child in value.items():
                _visit(child, "%s/%s" % (path, child_key), str(child_key))
            return
        if isinstance(value, list):
            for index, child in enumerate(value):
                _visit(child, "%s/%d" % (path, index), key)
            return
        if not isinstance(value, str):
            return
        if _is_placeholder(value):
            return

        masked = _mask_placeholders(value)
        secretish = bool(_SECRETISH_KEY.search(key or "")) or bool(
            re.match(r"^[A-Z0-9_]{3,}$", key or "") and _SECRETISH_KEY.search("_" + (key or "") + "_")
        )

        probes = [masked]
        if secretish:
            probes.append("%s=%s" % (key, masked))

        seen = set()  # type: set
        for probe in probes:
            _clean, kinds = scrub_lib.scrub(probe)
            for kind in kinds:
                if kind in seen:
                    continue
                if kind in HARD_SECRET_KINDS or (secretish and kind in SOFT_SECRET_KINDS):
                    seen.add(kind)
                    hits.append({"kind": kind, "pointer": path or "/"})

    _visit(node, pointer, "")
    return hits


def scan_text_secrets(text: str) -> List[str]:
    """Backstop raw-text scan with placeholders masked out first."""
    masked = _mask_placeholders(text or "")
    _clean, kinds = scrub_lib.scrub(masked)
    return sorted(set(kind for kind in kinds if kind in HARD_SECRET_KINDS))


# ---------------------------------------------------------------------------
# Rule contradiction detection (best-effort, WARN only)
# ---------------------------------------------------------------------------
#
# Three kinds are detected, all of them WARN, all of them best-effort:
#
#   opposing-polarity      one rule asserts X while another (or the same rule)
#                          forbids X, and their scopes overlap.
#   exclusive-choice       two rules pick different members of one mutually
#                          exclusive category -- "use bun" vs "use npm" -- or
#                          one requires what the other forbids.
#   contradicts-convention a rule asserts something the repo demonstrably does
#                          not do.  Needs `--discovery discovery.json`; when it
#                          is absent the PASS row says so rather than implying
#                          the check ran.
#
# WHY THIS IS CLAUSE-LEVEL, NOT SENTENCE-LEVEL.  The 2026-09-04 dogfood run
# built two rules with an identical `scope: src/**`, one saying "Always use
# bun, never npm" and the other "Always use npm, never bun", and this check
# PASSED.  A sentence-level reader takes the FIRST polarity marker it finds --
# "never" in both -- records a single negative directive ("npm" / "bun"), and
# throws the "always use ..." half of each sentence away.  Two negatives on
# different subjects are not an opposing pair, so the textbook contradiction
# the docs use as their own example read as clean.  Every sentence is therefore
# split into clauses first, each clause carries its own polarity, and an
# elliptical clause ("never npm") inherits the verb of the clause before it so
# that it keys the same way as the spelled-out form ("never use npm").

_NEG_MARKERS = sorted(
    [
        "must never",
        "should never",
        "must not",
        "should not",
        "do not",
        "does not",
        "don't",
        "dont",
        "never",
        "no longer",
        "stop using",
        "not allowed",
        "forbidden",
        "prohibited",
        "avoid",
        "not",
    ],
    key=len,
    reverse=True,
)

#: Ordered on purpose: a modal/adverb marker wins over the bare verb, so
#: "always use bun" keys on "use bun" and not on "bun".
_POS_MARKERS = [
    "always",
    "must",
    "should",
    "required to",
    "require",
    "ensure",
    "prefer",
    "use",
]

#: Markers that ARE the verb.  The subject starts AT these, so "use bun" and
#: "never use bun" both reduce to the subject `use bun` instead of keying on
#: "bun" and "use bun" and missing each other.
_MARKER_KEEPS_VERB = frozenset(["use", "prefer", "ensure", "require"])

#: Negative markers that imply a verb the clause does not spell out.
#: "avoid npm" is "do not use npm".
_NEG_IMPLIED_VERB = {
    "avoid": "use",
    "stop using": "use",
    "not allowed": "use",
    "forbidden": "use",
    "prohibited": "use",
}

#: Polarity words that must never survive into a subject key -- otherwise
#: "always use bun" and "use bun" key differently.  The verb markers above are
#: deliberately absent: they are content.
_POLARITY_WORDS = frozenset(
    [
        "always",
        "must",
        "should",
        "never",
        "not",
        "dont",
        "no",
        "longer",
        "stop",
        "allowed",
        "forbidden",
        "prohibited",
        "avoid",
        "required",
        "ever",
    ]
)

_DIRECTIVE_STOPWORDS = frozenset(
    [
        "a",
        "an",
        "the",
        "we",
        "you",
        "i",
        "to",
        "be",
        "is",
        "are",
        "our",
        "this",
        "that",
        "it",
        "please",
        "just",
        "only",
        "ever",
        "any",
        "all",
        "and",
        "or",
        "of",
        "in",
        "on",
        "at",
        "by",
        "with",
    ]
)

_VERB_CANON = {
    "using": "use",
    "uses": "use",
    "used": "use",
    "prefer": "use",
    "prefers": "use",
    "preferred": "use",
    "preferring": "use",
    "running": "run",
    "runs": "run",
    "adding": "add",
    "adds": "add",
    "writing": "write",
    "writes": "write",
    "committing": "commit",
    "commits": "commit",
    "creating": "create",
    "creates": "create",
    "installing": "install",
    "installs": "install",
    "importing": "import",
    "imports": "import",
}

#: Heads of directive clauses.  Used only to decide whether an elliptical
#: clause ("never npm") needs the previous clause's verb prepended.
_DIRECTIVE_VERBS = frozenset(
    [
        "use",
        "run",
        "write",
        "add",
        "create",
        "commit",
        "install",
        "import",
        "export",
        "call",
        "keep",
        "put",
        "place",
        "store",
        "return",
        "name",
        "wrap",
        "handle",
        "format",
        "lint",
        "test",
        "build",
        "deploy",
        "push",
        "merge",
        "rebase",
        "read",
        "edit",
        "delete",
        "define",
        "declare",
        "throw",
        "log",
        "mock",
        "seed",
        "migrate",
        "query",
        "access",
        "validate",
        "ensure",
        "check",
        "generate",
        "touch",
        "expose",
        "commit",
    ]
)

#: Tools and values that are mutually exclusive within a category.  Two rules
#: naming different members of one category, with the same qualifier and
#: overlapping scopes, are reported as a probable contradiction -- and so is
#: one rule requiring a member another forbids.
_EXCLUSIVE_CATEGORIES = {
    "package manager": ["npm", "yarn", "pnpm", "bun"],
    "test runner": ["jest", "vitest", "mocha", "ava", "pytest", "unittest", "rspec"],
    "formatter": ["prettier", "biome", "black", "gofmt", "rustfmt"],
    "linter": ["eslint", "flake8", "pylint", "rubocop"],
    "orm": ["prisma", "drizzle", "typeorm", "sequelize", "sqlalchemy", "activerecord"],
    "bundler": ["webpack", "vite", "esbuild", "rollup", "parcel", "turbopack"],
    "styling": ["tailwind", "styled-components", "emotion", "sass", "css modules"],
    "language": ["typescript", "javascript", "flow"],
    "framework": ["express", "fastify", "koa", "hapi"],
    "indentation": ["tabs", "spaces"],
    "quote style": ["single quotes", "double quotes"],
    "import path style": ["absolute imports", "relative imports"],
    "export style": ["default exports", "named exports"],
    "module system": ["esm", "commonjs", "es modules"],
}

#: A narrower rule may legitimately differ from a broader one when it says in
#: as many words that it is the exception (verification.md section 6).
_EXCEPTION_MARKERS = (
    "exception",
    "except",
    "override",
    "overrides",
    "takes precedence",
    "narrower",
    "unlike the global",
)

#: A rule that contradicts the repo's current practice is allowed to, when it
#: is worded as intent rather than as description (verification.md section 6).
_ASPIRATION_MARKERS = (
    "we are moving",
    "we're moving",
    "moving to",
    "migrating to",
    "migration to",
    "going forward",
    "from now on",
    "new code",
    "aspirational",
    "transition to",
    "in the process of",
)

#: A rule long enough to state 300 directives is not a rule, and reading more
#: of it buys nothing: the check reports one row per pair of rules.
MAX_DIRECTIVES_PER_RULE = 300

_QUALIFIER = re.compile(r"\b(?:for|when|in|inside|under|during|on)\b(.*)$")

#: Precompiled once: a rule body is read clause by clause, and a long rule set
#: would otherwise recompile the same ~90 word-boundary patterns thousands of
#: times and lean on re's small internal cache.
_NEG_PATTERNS = [(marker, re.compile(r"\b%s\b" % re.escape(marker))) for marker in _NEG_MARKERS]
_POS_PATTERNS = [(marker, re.compile(r"\b%s\b" % re.escape(marker))) for marker in _POS_MARKERS]
_MEMBER_PATTERNS = [
    (category, member, re.compile(r"\b%s\b" % re.escape(member)))
    for category in sorted(_EXCLUSIVE_CATEGORIES)
    for member in _EXCLUSIVE_CATEGORIES[category]
]

#: Characters that keep a filename together.  `\b` alone splits on `-` and `.`,
#: so `\bpnpm\b` matches INSIDE `pnpm-lock.yaml` -- and a rule whose rationale
#: says "npm ignores pnpm-lock.yaml" then read as a directive FORBIDDING pnpm.
#: Measured on the 2026-09-05 Codex dogfood: the `contradicts-convention` FAIL
#: was "rule forbids pnpm, which is the package manager this repo uses", raised
#: against a rule that said to USE pnpm.  A member is a tool name only when the
#: whole `[A-Za-z0-9_.-]` run around it IS the member.
_TOKEN_CHAR = re.compile(r"[A-Za-z0-9_.\-]")


def _member_hits(text: str) -> List[Tuple[str, str]]:
    """
    `(category, member)` for every exclusive-category tool NAMED in `text`.

    A match inside a longer dotted/hyphenated token -- `pnpm-lock.yaml`,
    `bun.lockb`, `vitest.config.ts`, `eslint.config.js` -- is a FILE, not a
    directive about the tool, and is dropped.  Bare `pnpm`, `pnpm@9` and
    `pnpm,` still hit, because the run stops at the character that ends a
    filename too.
    """
    hits = []  # type: List[Tuple[str, str]]
    lowered = str(text or "").lower()
    if not lowered:
        return hits
    for category, member, pattern in _MEMBER_PATTERNS:
        for match in pattern.finditer(lowered):
            start, end = match.start(), match.end()
            while start > 0 and _TOKEN_CHAR.match(lowered[start - 1]):
                start -= 1
            while end < len(lowered) and _TOKEN_CHAR.match(lowered[end]):
                end += 1
            if lowered[start:end] != member:
                continue
            pair = (category, member)
            if pair not in hits:
                hits.append(pair)
            break
    return hits


#: Decoration around a heading's LABEL -- markdown emphasis, backticks, an
#: enumerator (`2.`), and the ❌ / ✗ / 🚫 marks a negative heading is usually
#: written with.  Stripped from both ends before the label is matched, so
#: "❌ Incorrect", "**Incorrect**" and "2. Incorrect:" all reduce to the one
#: label `incorrect`.  The trailing strip keeps `'` and `’` so `Don't` survives.
_HEADING_LEAD = re.compile(r"^(?:[^0-9A-Za-z]+|\d+[.)]\s*)")
_HEADING_TAIL = re.compile(r"[^0-9A-Za-z'’]+$")


def _heading_label(title: str) -> str:
    """A heading reduced to its bare label: decoration stripped, lowercased."""
    text = str(title or "").replace("’", "'").strip()
    for _ in range(3):
        stripped = _HEADING_LEAD.sub("", text, count=1)
        if stripped == text:
            break
        text = stripped
    return _HEADING_TAIL.sub("", text).strip().lower()


#: A heading that introduces a NEGATIVE example.  Everything under one, down to
#: the next heading at the same or a higher level, illustrates what NOT to do --
#: so it is not a directive, whatever its polarity reads as.  `rule.md.tmpl`
#: MANDATES a `## Correct` / `## Incorrect` pair and puts an unfenced
#: `{{INCORRECT_EXPLANATION}}` paragraph under the second one, which means every
#: rule the shipped template produces carries prose that states the OPPOSITE of
#: the rule.  Fence-skipping alone does not reach that paragraph.
#:
#: MATCHED AS A WHOLE LABEL, never as a prefix.  A prefix match was this fix's
#: own false NEGATIVE: `## Never-cached routes` and
#: `## Avoiding N+1 queries -- the rule` are ordinary headings that merely START
#: with a negative word, and skipping them swallowed every real directive
#: underneath, down to the next heading.  So the label has to BE the negative
#: marker, optionally followed by the nouns such a heading really takes
#: ("Incorrect example", "Bad practice", "Don't do this") -- and nothing else.
_NEG_LABEL_HEAD = (
    r"incorrect|wrong|bad|don'?ts?|do\s*not|never|avoid|nope|"
    r"anti[\s\-]?patterns?|counter[\s\-]?examples?|not\s+this|"
    r"what\s+not\s+to\s+do|what\s+to\s+avoid"
)
_NEG_LABEL_TAIL = (
    r"examples?|samples?|snippets?|code|usage|patterns?|practices?|"
    r"ways?|approach(?:es)?|versions?|styles?|do|this|that|these|those|it|"
    r"instead|below|above"
)
_NEGATIVE_HEADING = re.compile(
    r"^(?:the\s+|an?\s+)?(?:%s)(?:[\s\-]+(?:%s))*$" % (_NEG_LABEL_HEAD, _NEG_LABEL_TAIL),
    re.IGNORECASE,
)

#: A heading whose section is AGENTIFY'S OWN METADATA, not the user's rule.
#: `rule.md.tmpl` prints the evidence line twice -- once in frontmatter as
#: `agentify-evidence:` and once as the body of `## Evidence` -- and the second
#: copy is prose the clause reader happily read: measured, `correction: "use
#: uv" (3x, ...)` became a POSITIVE directive with the subject `use uv 3x`.
#: Harmless only until agentify's own provenance line collides with a real
#: rule in the contradiction graph, so it is excluded at the source.
_METADATA_HEADING = re.compile(
    r"^(?:agentify(?:\s+(?:metadata|provenance|header))?|provenance|"
    r"evidence(?:\s+(?:line|lines|counts?|notes?|sources?))?)$",
    re.IGNORECASE,
)

#: `## Heading` / `**Heading**` / `__Heading__` on a line of its own.  The bold
#: forms carry no level, so they are treated as the deepest heading (6): they
#: close at the next real heading of any level.
_ATX_HEADING = re.compile(r"^(#{1,6})\s+(.*?)\s*#*$")
_BOLD_HEADING = re.compile(r"^(?:\*\*|__)\s*(.+?)\s*(?:\*\*|__)[:.]?$")


def _heading_of(line: str) -> Optional[Tuple[int, str]]:
    """`(level, text)` when `line` is a markdown heading, else None."""
    match = _ATX_HEADING.match(line)
    if match:
        return (len(match.group(1)), match.group(2))
    match = _BOLD_HEADING.match(line)
    if match:
        return (6, match.group(1))
    return None


def _skipped_section(title: str) -> str:
    """
    `"negative"`, `"metadata"` or `""` for a heading whose section carries no
    directive.  Both are read as a WHOLE label (`_heading_label`), so a heading
    that merely begins with one of these words keeps its section.
    """
    label = _heading_label(title)
    if not label:
        return ""
    if _NEGATIVE_HEADING.match(label):
        return "negative"
    if _METADATA_HEADING.match(label):
        return "metadata"
    return ""


#: An `agentify-id:` / `-version:` / `-generated:` / `-evidence:` line, wherever
#: it survived into a body -- a Codex rule with no frontmatter to strip, a
#: `modified` file's marked block.  It is agentify's own metadata, so it is
#: never a directive (DEFECT D's other half).
_METADATA_BODY_LINE = re.compile(
    r"^[^\n]{0,20}?\bagentify[-_](?:id|version|generated|evidence)\s*[:=]",
    re.IGNORECASE,
)

#: "use bun instead of npm" carries two directives, not one.  Rewritten to an
#: explicit negative clause before splitting so the second half is not lost.
_PRE_TRANSFORMS = [
    (re.compile(r"\binstead of\b"), " ; never "),
    (re.compile(r"\brather than\b"), " ; never "),
    (re.compile(r"\bas opposed to\b"), " ; never "),
    (re.compile(r"\bnot\s+the\b"), " ; not the "),
]

_CLAUSE_SPLIT = re.compile(r"[;,]|\band\b|\bbut\b|\bwhile\b|\bwhereas\b|\bhowever\b")

_SENTENCE_SPLIT = re.compile(r"(?<=[.;!?])\s+")


def _clean_directive(line: str) -> str:
    text = str(line or "")
    text = re.sub(r"^[\s>*\-+]{0,8}", "", text)
    text = re.sub(r"^#{1,6}\s*", "", text)
    text = re.sub(r"^\d{1,3}[.)]\s*", "", text)
    text = text.replace("`", " ").replace("**", " ").replace("__", " ")
    text = re.sub(r"\[([^\]]{0,80})\]\([^)]{0,200}\)", r"\1", text)
    text = re.sub(r"\s+", " ", text)
    return text.strip().lower()


def _canon_token(word: str) -> str:
    """Canonical form of one subject token: verb forms and naive plurals."""
    canon = _VERB_CANON.get(word, word)
    if len(canon) > 3 and canon.endswith("s") and not canon.endswith("ss") and not canon.endswith("us"):
        stem = canon[:-1]
        canon = _VERB_CANON.get(stem, stem)
    return canon


def _subject_tokens(text: str, marker: str, keep_marker: bool) -> List[str]:
    """Content tokens of a clause, with the polarity marker removed."""
    body = text
    position = body.find(marker) if marker else -1
    if position >= 0:
        body = body[position:] if keep_marker else body[position + len(marker) :]
    body = _QUALIFIER.sub("", body)
    body = re.sub(r"[^a-z0-9_./+#-]+", " ", body)
    tokens = []  # type: List[str]
    for word in body.split():
        canon = _canon_token(word)
        if canon in _DIRECTIVE_STOPWORDS or canon in _POLARITY_WORDS:
            continue
        tokens.append(canon)
        if len(tokens) >= 4:
            break
    return tokens


def _qualifier_of(text: str) -> str:
    match = _QUALIFIER.search(text)
    if not match:
        return ""
    tail = re.sub(r"[^a-z0-9 ]+", " ", match.group(1))
    return " ".join(tail.split()[:3])


def _members_in(text: str) -> Dict[str, List[str]]:
    """Exclusive-category members named in a clause, by category."""
    found = {}  # type: Dict[str, List[str]]
    for category, member in _member_hits(text):
        found.setdefault(category, [])
        if member not in found[category]:
            found[category].append(member)
    return found


def _polarity_of(clause: str) -> Tuple[Optional[str], str]:
    """(`pos` | `neg` | None, the marker that decided it)."""
    for marker, pattern in _NEG_PATTERNS:
        if pattern.search(clause):
            return ("neg", marker)
    for marker, pattern in _POS_PATTERNS:
        if pattern.search(clause):
            return ("pos", marker)
    return (None, "")


def extract_directives(
    rule_id: str,
    body: str,
    scope: Optional[Sequence[str]] = None,
) -> List[Dict[str, Any]]:
    """
    Reduce a rule body to clause-level (polarity, subject, members) directives.

    One SENTENCE can carry several directives -- "always use bun, never npm" is
    two -- so sentences are split into clauses and each clause is read on its
    own.  A clause with no verb of its own inherits the previous clause's verb,
    which is what makes the elliptical half ("never npm") key identically to
    the spelled-out half of the opposing rule ("never use npm").

    THREE KINDS OF TEXT ARE NOT DIRECTIVES, and each had to be excluded before
    this could be trusted to FAIL a build:

      * a FENCED BLOCK, which is an illustration;
      * everything under a NEGATIVE-EXAMPLE HEADING (`## Incorrect`,
        `## Anti-pattern`, `## Avoid`, ...), fenced or not -- matched as a
        WHOLE LABEL, so `## Never-cached routes` keeps its section; and
      * AGENTIFY'S OWN METADATA -- the `## Evidence` section `rule.md.tmpl`
        prints and any surviving `agentify-*:` line.  Measured: the evidence
        line `correction: "use uv" (3x, ...)` became a positive directive with
        the subject `use uv 3x`, which put agentify's provenance into the
        contradiction graph where it can collide with a real rule.

    The second is the one that matters, because `rule.md.tmpl` mandates a
    `## Correct` / `## Incorrect` pair and ends with an UNFENCED
    `{{INCORRECT_EXPLANATION}}` paragraph under `## Incorrect`.  An Incorrect
    example is by construction the opposite of the rule, so before this, EVERY
    rule the shipped template produced was a candidate false positive -- and
    one measured on the 2026-09-05 Codex dogfood hard-FAILED a correct rule
    with "rule forbids pnpm, which is the package manager this repo uses".
    A false FAIL is the most damaging verdict this script can reach: SKILL.md
    phase 8 step 3 tells the model to fix or remove a failing artifact, so it
    destroys good work.  Skipping (rather than inverting the polarity of) a
    negative section is deliberate: reading an illustration's intent is a
    guess, and the cost of guessing wrong is a deleted rule.
    """
    directives = []  # type: List[Dict[str, Any]]
    if not body:
        return directives
    globs = [str(item) for item in (scope or [])] or ["**"]

    sentences = []  # type: List[str]
    # A fenced block is an ILLUSTRATION, never a directive.  `rule.md.tmpl`
    # mandates `## Correct` and `## Incorrect` fenced examples, and an
    # Incorrect example is by construction a command the repo does not want --
    # so `pnpm vitest run ...  # does not exist` inside a fence read as
    # "rule forbids pnpm" and FAILed `rule_contradiction` against the repo's
    # own package manager.  Measured on the 2026-09-05 Codex dogfood.  Track
    # the fence here rather than pre-stripping with `_FENCE_RE`, so an
    # unterminated fence still ends at the end of the body instead of
    # swallowing nothing.
    fence = ""
    #: Heading level of the negative-example or metadata section currently being
    #: skipped, 0 when not inside one.  It closes at the next heading of the
    #: same or a higher level -- so a `### Why not` nested under `## Incorrect`
    #: stays skipped, and the next `## ...` reopens directive reading.
    skip_level = 0
    #: A leading `---` frontmatter block is agentify's own metadata (id,
    #: version, generated, evidence) plus a `scope:`.  `rule_body` strips it
    #: before calling in, but this function is also called on a whole file --
    #: the selftest does exactly that -- so the guard lives here too.
    lines = body.split("\n")
    start = 0
    if lines and lines[0].strip() in ("---", "+++"):
        opener = lines[0].strip()
        for index in range(1, min(len(lines), 200)):
            if lines[index].strip() == opener:
                start = index + 1
                break
    for line in lines[start:start + 400]:
        stripped = line.strip()
        if fence:
            if stripped.startswith(fence) and stripped.strip(fence[0]) == "":
                fence = ""
            continue
        if stripped.startswith("```") or stripped.startswith("~~~"):
            fence = stripped[:3]
            continue
        # Heading state is read BEFORE `_clean_directive` strips the `#`, and
        # only outside a fence -- a `# comment` line in a bash example is not a
        # heading.
        heading = _heading_of(stripped)
        if heading is not None:
            level, title = heading
            if skip_level and level <= skip_level:
                skip_level = 0
            if not skip_level and _skipped_section(title):
                skip_level = level
                continue
        if skip_level:
            continue
        if _METADATA_BODY_LINE.match(stripped):
            continue
        cleaned = _clean_directive(line)
        if not cleaned:
            continue
        for piece in _SENTENCE_SPLIT.split(cleaned):
            piece = piece.strip(" .;:!?")
            if len(piece) > 3:
                sentences.append(piece)
        if len(sentences) >= 200:
            break

    for sentence in sentences[:200]:
        prepared = sentence
        for pattern, replacement in _PRE_TRANSFORMS:
            prepared = pattern.sub(replacement, prepared)
        carried_verb = ""
        for clause in _CLAUSE_SPLIT.split(prepared):
            clause = clause.strip(" .;:!?-")
            if len(clause) < 2:
                continue
            polarity, marker = _polarity_of(clause)
            if polarity is None:
                # No directive here, but its verb can still be inherited by a
                # following elliptical clause.
                tokens = _subject_tokens(clause, "", False)
                if tokens and tokens[0] in _DIRECTIVE_VERBS:
                    carried_verb = tokens[0]
                continue
            tokens = _subject_tokens(clause, marker, marker in _MARKER_KEEPS_VERB)
            if tokens and tokens[0] in _DIRECTIVE_VERBS:
                carried_verb = tokens[0]
            elif tokens:
                implied = carried_verb or _NEG_IMPLIED_VERB.get(marker, "")
                if implied:
                    tokens = [implied] + tokens[:3]
            if not tokens:
                continue
            directives.append(
                {
                    "rule": rule_id,
                    "polarity": polarity,
                    "subject": " ".join(tokens),
                    "qualifier": _qualifier_of(clause),
                    "text": clause,
                    "scope": globs,
                    "members": _members_in(clause),
                }
            )
            if len(directives) >= MAX_DIRECTIVES_PER_RULE:
                return directives
    return directives


# -- scope arithmetic -------------------------------------------------------


def _glob_prefix(pattern: str) -> Tuple[str, str]:
    """(directory prefix, extension) of a glob, for cheap overlap tests."""
    text = str(pattern or "").strip().strip('"').strip("'")
    while text.startswith("./"):
        text = text[2:]
    text = text.lstrip("/")
    if not text:
        return ("", "")
    extension = ""
    tail = text.rsplit("/", 1)[-1]
    if "." in tail and not tail.endswith("."):
        candidate = tail.rsplit(".", 1)[-1]
        if candidate and re.match(r"^[A-Za-z0-9]{1,8}$", candidate):
            extension = candidate.lower()
    cut = len(text)
    for character in "*?[{":
        found = text.find(character)
        if found >= 0:
            cut = min(cut, found)
    literal = text[:cut]
    if cut < len(text):
        literal = literal.rsplit("/", 1)[0] + "/" if "/" in literal else ""
    return (literal, extension)


def _glob_pair_overlap(left: str, right: str) -> bool:
    left_prefix, left_ext = _glob_prefix(left)
    right_prefix, right_ext = _glob_prefix(right)
    if left_ext and right_ext and left_ext != right_ext:
        return False
    if not left_prefix or not right_prefix:
        return True
    return left_prefix.startswith(right_prefix) or right_prefix.startswith(left_prefix)


def scopes_overlap(left: Sequence[str], right: Sequence[str]) -> bool:
    """True when two rule scopes can govern the same file."""
    left_list = [item for item in (left or []) if str(item).strip()] or ["**"]
    right_list = [item for item in (right or []) if str(item).strip()] or ["**"]
    for one in left_list:
        for other in right_list:
            if _glob_pair_overlap(one, other):
                return True
    return False


def _scope_is_narrower(inner: Sequence[str], outer: Sequence[str]) -> bool:
    """True when every glob in `inner` sits strictly under `outer`."""
    inner_list = [item for item in (inner or []) if str(item).strip()]
    outer_list = [item for item in (outer or []) if str(item).strip()]
    if not inner_list or not outer_list:
        return False
    for one in inner_list:
        inner_prefix, _ = _glob_prefix(one)
        if not inner_prefix:
            return False
        strictly_under = False
        for other in outer_list:
            outer_prefix, _ = _glob_prefix(other)
            if inner_prefix.startswith(outer_prefix) and len(inner_prefix) > len(outer_prefix):
                strictly_under = True
                break
        if not strictly_under:
            return False
    return True


def _is_declared_exception(text: str) -> bool:
    lowered = (text or "").lower()
    return any(marker in lowered for marker in _EXCEPTION_MARKERS)


def _is_aspirational(text: str) -> bool:
    lowered = (text or "").lower()
    return any(marker in lowered for marker in _ASPIRATION_MARKERS)


def _exempt_pair(left: Dict[str, Any], right: Dict[str, Any], bodies: Dict[str, str]) -> bool:
    """
    A narrower rule that says in as many words that it is the exception is
    allowed to differ from the broader one -- verification.md section 6.
    """
    if left["rule"] == right["rule"]:
        return False
    if _scope_is_narrower(left["scope"], right["scope"]):
        return _is_declared_exception(bodies.get(left["rule"], "") or left["text"])
    if _scope_is_narrower(right["scope"], left["scope"]):
        return _is_declared_exception(bodies.get(right["rule"], "") or right["text"])
    return False


def find_contradictions(
    directives: Sequence[Dict[str, Any]],
    bodies: Optional[Dict[str, str]] = None,
    max_results: int = 12,
) -> List[Dict[str, str]]:
    """Opposing directives on one subject, plus exclusive-category collisions."""
    bodies = bodies or {}
    results = []  # type: List[Dict[str, str]]
    reported_pairs = set()  # type: set
    extra = {}  # type: Dict[Any, int]

    def pair_key(left_rule: str, right_rule: str) -> Any:
        return tuple(sorted([left_rule, right_rule]))

    # -- 1. same subject, opposing polarity --------------------------------
    # One directive per (subject, rule, polarity) is enough: a row is reported
    # once per unordered RULE PAIR, so a rule that states the same directive
    # forty times contributes nothing extra.  Deduplicating here is not a
    # nicety -- without it the positives x negatives cross product below is
    # quadratic in the number of SENTENCES, and a 50-rule fixture of repeated
    # "always use bun. never use bun." took 107 seconds to produce 12 rows.
    # Deduplicated, the same input is bounded by rules^2 and finishes instantly.
    by_subject = {}  # type: Dict[str, List[Dict[str, Any]]]
    first_seen = set()  # type: set
    for directive in directives:
        signature = (directive["subject"], directive["rule"], directive["polarity"])
        if signature in first_seen:
            continue
        first_seen.add(signature)
        by_subject.setdefault(directive["subject"], []).append(directive)

    for subject in sorted(by_subject):
        group = by_subject[subject]
        positives = sorted([item for item in group if item["polarity"] == "pos"], key=lambda d: d["rule"])
        negatives = sorted([item for item in group if item["polarity"] == "neg"], key=lambda d: d["rule"])
        if not positives or not negatives:
            continue
        for left in positives:
            for right in negatives:
                if not scopes_overlap(left["scope"], right["scope"]):
                    continue
                if _exempt_pair(left, right, bodies):
                    continue
                key = pair_key(left["rule"], right["rule"])
                if key in reported_pairs:
                    extra[key] = extra.get(key, 0) + 1
                    continue
                reported_pairs.add(key)
                results.append(
                    {
                        "kind": "opposing-polarity",
                        "subject": subject,
                        "left_rule": left["rule"],
                        "right_rule": right["rule"],
                        "left": left["text"],
                        "right": right["text"],
                    }
                )

    # -- 2. exclusive-category collisions ----------------------------------
    # Per rule, per category: which members it asserts and which it forbids.
    asserted = {}  # type: Dict[Tuple[str, str], Dict[str, Dict[str, Any]]]
    forbidden = {}  # type: Dict[Tuple[str, str], Dict[str, Dict[str, Any]]]
    for directive in directives:
        table = asserted if directive["polarity"] == "pos" else forbidden
        for category, members in directive["members"].items():
            for member in members:
                slot = table.setdefault((directive["rule"], category), {})
                slot.setdefault(member, directive)

    rule_ids = sorted(set([directive["rule"] for directive in directives]))
    for category in sorted(_EXCLUSIVE_CATEGORIES):
        for index, left_rule in enumerate(rule_ids):
            for right_rule in rule_ids[index:]:
                left_pos = asserted.get((left_rule, category), {})
                left_neg = forbidden.get((left_rule, category), {})
                right_pos = asserted.get((right_rule, category), {})
                right_neg = forbidden.get((right_rule, category), {})

                collisions = []  # type: List[Tuple[str, Dict[str, Any], Dict[str, Any]]]
                for member in sorted(set(left_pos) & set(right_neg)):
                    collisions.append(("required here, forbidden there: %s" % member, left_pos[member], right_neg[member]))
                for member in sorted(set(right_pos) & set(left_neg)):
                    collisions.append(("required here, forbidden there: %s" % member, right_pos[member], left_neg[member]))
                if left_rule != right_rule and left_pos and right_pos and not (set(left_pos) & set(right_pos)):
                    left_member = sorted(left_pos)[0]
                    right_member = sorted(right_pos)[0]
                    collisions.append(
                        (
                            "two %ss chosen: %s vs %s" % (category, left_member, right_member),
                            left_pos[left_member],
                            right_pos[right_member],
                        )
                    )

                for label, left, right in collisions:
                    # Two spelled-out, DIFFERENT qualifiers mean the rules are
                    # talking about different situations ("bun for installs" /
                    # "npm for the release script") and do not collide.  An
                    # absent qualifier is unqualified, so it collides with
                    # anything -- requiring both to be absent was letting
                    # "always use pnpm for installs" sit next to "always run
                    # npm run lint" unreported.
                    if left["qualifier"] and right["qualifier"] and left["qualifier"] != right["qualifier"]:
                        continue
                    if not scopes_overlap(left["scope"], right["scope"]):
                        continue
                    if _exempt_pair(left, right, bodies):
                        continue
                    key = pair_key(left["rule"], right["rule"])
                    if key in reported_pairs:
                        extra[key] = extra.get(key, 0) + 1
                        continue
                    reported_pairs.add(key)
                    results.append(
                        {
                            "kind": "exclusive-choice",
                            "subject": "%s (%s)" % (category, label),
                            "left_rule": left["rule"],
                            "right_rule": right["rule"],
                            "left": left["text"],
                            "right": right["text"],
                        }
                    )
                    break

    for item in results:
        count = extra.get(pair_key(item["left_rule"], item["right_rule"]), 0)
        if count:
            item["more"] = str(count)
    return results[:max_results]


# -- rules against discovered conventions -----------------------------------


def conventions_from_discovery(discovery: Any) -> Dict[str, Dict[str, Any]]:
    """
    Reduce `discovery.json` to
    `{category: {"members": [...], "sources": [...], "hard": [...]}}`
    using the same exclusive-category lexicon the rules are read with, so a
    rule and a convention can be compared on one key.

    HARD VS SOFT SOURCES.  `hard` is the subset of `members` backed by at least
    one source that states what the repo *runs*: the declared
    `package_managers` list, or a resolved `commands.*` line.  Those are the
    facts verification.md section 6 calls "a hard discovered fact" and its Fail
    example rests on ("a rule saying 'use npm' in a repo with bun.lockb and
    packageManager: bun"), so a rule that contradicts one of them FAILS.

    `frameworks` and `languages` are name scans over file statistics, not
    statements about tooling.  A pure-JavaScript repo whose rule says "write
    new modules in TypeScript" is a repo with an intent, not a broken build, so
    a clash with a soft source stays a WARN and never deletes the rule.
    """
    facts = {}  # type: Dict[str, Dict[str, Any]]
    if not isinstance(discovery, dict):
        return facts

    def note(category: str, member: str, source: str, hard: bool) -> None:
        entry = facts.setdefault(category, {"members": [], "sources": [], "hard": []})
        if member not in entry["members"]:
            entry["members"].append(member)
        if source not in entry["sources"]:
            entry["sources"].append(source)
        if hard and member not in entry["hard"]:
            entry["hard"].append(member)

    def scan(text: Any, source: str, hard: bool) -> None:
        if not isinstance(text, str) or not text.strip():
            return
        # Same filename-aware matcher the rules are read with, so the two sides
        # of the comparison cannot disagree about what counts as naming a tool:
        # `pnpm install --frozen-lockfile` names pnpm, `bun.lockb` names a file.
        for category, member in _member_hits(text):
            note(category, member, source, hard)

    managers = discovery.get("package_managers")
    if isinstance(managers, list):
        for item in managers:
            name = str(item or "").strip().lower()
            if name in _EXCLUSIVE_CATEGORIES["package manager"]:
                note("package manager", name, "discovery.package_managers", True)

    commands = discovery.get("commands")
    if isinstance(commands, dict):
        for slot in sorted(commands):
            scan(commands.get(slot), "discovery.commands.%s" % slot, True)

    for framework in discovery.get("frameworks") or []:
        if isinstance(framework, dict):
            scan(framework.get("name"), "discovery.frameworks", False)

    for language in discovery.get("languages") or []:
        if isinstance(language, dict):
            scan(language.get("name"), "discovery.languages", False)

    return facts


def find_convention_conflicts(
    directives: Sequence[Dict[str, Any]],
    conventions: Dict[str, Dict[str, Any]],
    bodies: Optional[Dict[str, str]] = None,
    max_results: int = 8,
) -> List[Dict[str, str]]:
    """
    A rule that contradicts what the repo demonstrably does (PRD 7.9: "check
    for contradictions ... with discovered conventions").  A rule worded as
    intent -- "we are moving to X" -- is exempt: verification.md section 6
    calls that aspirational and correct.

    Each result carries `hard`: "1" when the convention it clashes with came
    from `discovery.package_managers` or a `discovery.commands.*` line -- what
    the repo actually runs, and what verification.md section 6 makes a Fail --
    and "" when it came from the softer `frameworks` / `languages` name scans.
    The caller turns that into FAIL or WARN.
    """
    bodies = bodies or {}
    results = []  # type: List[Dict[str, str]]
    seen = set()  # type: set
    if not conventions:
        return results

    for directive in sorted(directives, key=lambda d: (d["rule"], d["subject"])):
        body = bodies.get(directive["rule"], "")
        if _is_aspirational(body) or _is_aspirational(directive["text"]):
            continue
        for category in sorted(directive["members"]):
            known = conventions.get(category)
            if not known or not known.get("members"):
                continue
            discovered = list(known["members"])
            hard_members = list(known.get("hard") or [])
            source = ", ".join(known["sources"][:2])
            for member in sorted(directive["members"][category]):
                if directive["polarity"] == "pos" and member not in discovered:
                    reason = "rule requires %s; the repo uses %s" % (member, "/".join(discovered))
                    # The repo's own choice has to be the hard fact here -- the
                    # rule names something the repo does not have at all.
                    hard = bool(hard_members)
                elif directive["polarity"] == "neg" and member in discovered and len(discovered) == 1:
                    reason = "rule forbids %s, which is the %s this repo uses" % (member, category)
                    hard = member in hard_members
                else:
                    continue
                key = (directive["rule"], category, member, directive["polarity"])
                if key in seen:
                    continue
                seen.add(key)
                results.append(
                    {
                        "kind": "contradicts-convention",
                        "subject": category,
                        "left_rule": directive["rule"],
                        "right_rule": source or "discovery.json",
                        "left": directive["text"],
                        "right": reason,
                        "hard": "1" if hard else "",
                    }
                )
                if len(results) >= max_results:
                    return results
    return results


# ---------------------------------------------------------------------------
# Rule SUBTYPES: prose conventions vs a Codex command policy
# ---------------------------------------------------------------------------
#
# `type: "rule"` covers two artifacts that share nothing but a name.
#
#   prose           markdown with `scope:` frontmatter, wired from the index
#                   doc.  `.claude/rules/<name>.md`, or (Codex)
#                   `<plan-dir>/rules/<name>.md` plus an `AGENTS.md` pointer.
#                   "Handlers return Result, not exceptions."
#   command-policy  `.codex/rules/<name>.rules` -- a Starlark EXECUTION policy,
#                   Codex-native, with no Claude Code equivalent.  It is the
#                   analogue of Claude Code's permissions allowlist, not of a
#                   prose rule.  "Never run npm."
#
# Applying the prose checks to a command policy is how `rule_scope` and
# `rule_wired` came to hard-FAIL a CORRECT `.codex/rules/agentify.rules` on the
# 2026-09-05 Codex dogfood: a Starlark policy has no frontmatter, governs
# commands rather than paths, and lives in a directory Codex loads natively.
# `codex-rules.rules.tmpl` documented both FAILs as expected -- but SKILL.md
# phase 8 step 3's fix-or-remove loop then reads them as instructions to delete
# a correct artifact.  A check documented to fail on a correct artifact is not
# a check; it is a trap.  So the subtype is decided first, and each subtype
# gets the checks written for its own shape.

RULE_SUBTYPE_PROSE = "prose"
RULE_SUBTYPE_POLICY = "command-policy"

#: VERIFIED (adapters/codex.md 4.2.2, capabilities row "Rules -- command
#: policy"): exactly these three.  "ask" and "deny" are LOAD ERRORS -- measured:
#: `Error loading rules: ... invalid decision: ask`, and Codex then refuses to
#: start in that repo at all.  A bad value here bricks the user's sessions, so
#: it is the one thing in a policy file that must fail loudly.
POLICY_DECISIONS = frozenset(["allow", "prompt", "forbidden"])

#: The policy functions agentify emits and knows the shape of.  An unrecognised
#: call is a WARN, never a FAIL: the language is documented as experimental and
#: subject to change, and failing an unknown-but-valid construct would be the
#: same false-FAIL defect one level down.
POLICY_FUNCTIONS = frozenset(["prefix_rule"])

#: Where a policy's command prefix can be spelled.  `pattern` is what the
#: template emits and what was measured.
POLICY_PATTERN_KEYS = ("pattern", "prefix", "program")


def rule_subtype(path: str, text: str = "") -> str:
    """
    Which of the two rule shapes an artifact is.

    Path first -- `.rules` is the Codex-native extension and nothing else uses
    it -- then content, so a policy written to an unexpected path is still read
    as one and a markdown rule that merely MENTIONS `prefix_rule` is not.
    """
    lowered = str(path or "").lower()
    if lowered.endswith(".rules"):
        return RULE_SUBTYPE_POLICY
    if _is_markdown(lowered):
        return RULE_SUBTYPE_PROSE
    body = str(text or "")
    if re.search(r"^[ \t]*(?:%s)[ \t]*\(" % "|".join(sorted(POLICY_FUNCTIONS)), body, re.M):
        return RULE_SUBTYPE_POLICY
    return RULE_SUBTYPE_PROSE


def parse_policy_rules(text: str) -> Tuple[List[Dict[str, Any]], Optional[str]]:
    """
    `(blocks, syntax error)` for a `.codex/rules/*.rules` file.

    Starlark is a Python dialect and a rules file is a sequence of top-level
    calls with keyword arguments only, so `ast` parses it exactly -- no
    hand-rolled parser, no dependency, and the same verdict Codex's own loader
    reaches on the thing that matters: does it parse at all.  A value that is
    not a literal (a name, a call, an f-string) is reported as `None` for that
    key rather than guessed at.
    """
    blocks = []  # type: List[Dict[str, Any]]
    try:
        tree = ast.parse(str(text or ""), filename="<rules>")
    except (SyntaxError, ValueError) as exc:
        return ([], _short(str(exc), 160))

    for index, node in enumerate(tree.body):
        if not isinstance(node, ast.Expr) or not isinstance(node.value, ast.Call):
            blocks.append(
                {
                    "index": index,
                    "line": getattr(node, "lineno", 0),
                    "function": "",
                    "args": {},
                    "unreadable": [],
                    "statement": type(node).__name__,
                }
            )
            continue
        call = node.value
        function = call.func.id if isinstance(call.func, ast.Name) else ""
        args = {}  # type: Dict[str, Any]
        unreadable = []  # type: List[str]
        for keyword in call.keywords:
            if keyword.arg is None:
                unreadable.append("**kwargs")
                continue
            try:
                args[keyword.arg] = ast.literal_eval(keyword.value)
            except (ValueError, SyntaxError, TypeError, MemoryError, RecursionError):
                args[keyword.arg] = None
                unreadable.append(keyword.arg)
        blocks.append(
            {
                "index": index,
                "line": getattr(node, "lineno", 0),
                "function": function,
                "args": args,
                "unreadable": unreadable,
                "statement": "",
                "positional": len(call.args),
            }
        )
    return (blocks, None)


def _policy_pattern_of(block: Dict[str, Any]) -> Tuple[str, Any]:
    """`(key, value)` of the block's command prefix, or `("", None)`."""
    for key in POLICY_PATTERN_KEYS:
        if key in block["args"]:
            return (key, block["args"][key])
    return ("", None)


def _policy_pattern_readable(pattern: Any) -> bool:
    """
    True when a pattern is built only of literal tokens and alternation lists.

    Anything else -- a regex object, a nested dict, a number -- means the
    matcher below does not understand this rule, and a verdict derived from it
    would be a guess.  Guessing is what produced the defect this whole section
    exists to fix, so an unreadable pattern downgrades the verdict instead.
    """
    if not isinstance(pattern, (list, tuple)) or not pattern:
        return False
    for element in pattern:
        if isinstance(element, str):
            continue
        if isinstance(element, (list, tuple)) and element and all(
            isinstance(item, str) for item in element
        ):
            continue
        return False
    return True


def policy_matches(pattern: Sequence[Any], command: str) -> bool:
    """
    Does `prefix_rule(pattern=...)` match `command`?

    PREFIX MATCHING ONLY, no semantics (adapters/codex.md 4.2.2): the pattern's
    elements are compared positionally against the command's tokens, the
    command may carry more tokens, and a NESTED LIST IS AN ALTERNATION --
    `["git", "push", ["--force", "-f"]]` matched `git push --force`, measured.
    """
    try:
        tokens = shlex.split(str(command or ""))
    except ValueError:
        tokens = str(command or "").split()
    if not tokens or len(pattern) > len(tokens):
        return False
    for element, token in zip(pattern, tokens):
        if isinstance(element, str):
            if element != token:
                return False
        elif isinstance(element, (list, tuple)):
            if token not in [str(item) for item in element]:
                return False
        else:
            return False
    return True


def _resolve_codex(target: Any = None) -> str:
    """
    Absolute path of a `codex` binary, or "".

    Used only to decide whether `codex execpolicy check` can add anything; the
    static checks stand on their own and the row says so when it did not run.
    """
    if normalize_target(target) != "codex":
        return ""
    return shutil.which("codex") or ""


# ---------------------------------------------------------------------------
# Manifest loading
# ---------------------------------------------------------------------------


def load_manifest(source: str) -> Tuple[Dict[str, Any], str]:
    """
    Read the manifest from a path or from stdin (`-`).  Raises ValueError with
    a human-readable message on anything unusable -- the caller turns that into
    the one and only exit-1 path.
    """
    if source == "-":
        try:
            raw = sys.stdin.read()
        except Exception as exc:
            raise ValueError("could not read manifest from stdin: %s" % exc)
        label = "<stdin>"
    else:
        path = os.path.abspath(os.path.expanduser(source))
        label = path
        if not os.path.exists(path):
            raise ValueError("manifest not found: %s" % path)
        if os.path.isdir(path):
            raise ValueError("manifest path is a directory: %s" % path)
        try:
            handle = open(path, "r", encoding="utf-8", errors="replace")
        except OSError as exc:
            raise ValueError("could not open manifest: %s" % exc)
        try:
            raw = handle.read()
        except OSError as exc:
            raise ValueError("could not read manifest: %s" % exc)
        finally:
            handle.close()

    if not raw.strip():
        raise ValueError("manifest is empty: %s" % label)
    try:
        parsed = json.loads(raw)
    except ValueError as exc:
        raise ValueError("manifest is not valid JSON (%s): %s" % (label, exc))

    if isinstance(parsed, list):
        parsed = {"artifacts": parsed}
    if not isinstance(parsed, dict):
        raise ValueError("manifest must be a JSON object or list of artifacts: %s" % label)

    artifacts = None
    for key in ("artifacts", "files", "entries"):
        if isinstance(parsed.get(key), list):
            artifacts = parsed[key]
            break
    if artifacts is None:
        raise ValueError("manifest has no `artifacts` list: %s" % label)
    parsed["artifacts"] = artifacts
    return (parsed, label)


def load_discovery(source: Optional[str]) -> Tuple[Dict[str, Dict[str, Any]], str, str, Dict[str, Any]]:
    """
    Optional companion input: phase 1's `discovery.json`, reduced to the
    conventions a rule can contradict.  Returns `(conventions, label, warning,
    parsed)` -- the last is the raw document, for `core_set`, and `{}` when
    nothing usable was read.

    Unlike the manifest this is never fatal.  `--discovery` is an *addition* to
    the run, so a missing or malformed file degrades to "rules checked against
    each other only" with a warning -- exit 0, per the shared exit-code
    contract in `lib/emit.py`.
    """
    if not source:
        return ({}, "", "", {})
    path = os.path.abspath(os.path.expanduser(source))
    if not os.path.isfile(path):
        return ({}, "", "--discovery: file not found (%s); rules were compared with each other "
                        "only, not against discovered conventions" % _short(path, 100), {})
    try:
        handle = open(path, "r", encoding="utf-8", errors="replace")
        try:
            raw = handle.read()
        finally:
            handle.close()
        parsed = json.loads(raw)
    except (OSError, ValueError) as exc:
        return ({}, "", "--discovery: could not read %s (%s); rules were compared with each "
                        "other only" % (_short(path, 80), _short(exc, 80)), {})
    raw_doc = parsed if isinstance(parsed, dict) else {}
    conventions = conventions_from_discovery(parsed)
    if not conventions:
        return ({}, path, "--discovery: %s named no package manager, command, framework or "
                          "language this checker recognises; rules were compared with each "
                          "other only" % _short(path, 80), raw_doc)
    return (conventions, path, "", raw_doc)


# ---------------------------------------------------------------------------
# Verifier
# ---------------------------------------------------------------------------


def _repo_relative(value: Any) -> str:
    """
    A manifest path reduced to its repo-relative form.

    `lstrip("./")` is character-set stripping, not prefix stripping, so it eats
    the leading dot of every dotfile path -- `.claude/rules/r.md` became
    `claude/rules/r.md`, which matches nothing and made the check that used it
    silently pass.  Every artifact path in this project starts with a dot, so
    the wrong idiom fails on the common case rather than the rare one.
    """
    text = str(value or "").strip()
    while text.startswith("./"):
        text = text[2:]
    return text.lstrip("/")


class Verifier(object):
    def __init__(
        self,
        repo: str,
        manifest: Dict[str, Any],
        options: Any,
        manifest_label: str = "",
        conventions: Optional[Dict[str, Dict[str, Any]]] = None,
        conventions_label: str = "",
        discovery: Optional[Dict[str, Any]] = None,
    ):
        self.repo = repo
        self.repo_real = os.path.realpath(repo)
        self.manifest = manifest
        self.manifest_label = manifest_label
        self.options = options
        #: The agent this build targets, and the one table every target-shaped
        #: fact in this file comes from -- hook registries, the variables a
        #: hook command may use, the environment the smoke test gives it.  No
        #: check below branches on the name; they all read the profile, so a
        #: third target is a row in TARGET_PROFILES and nothing else.
        self.target = normalize_target(manifest.get("target"))
        self.profile = target_profile(self.target)
        #: Optional: `discovery.json` reduced to comparable conventions, so a
        #: rule can be checked against what the repo actually does (PRD 7.9).
        #: Empty when `--discovery` was not given -- and the PASS row says so.
        self.conventions = conventions or {}
        self.conventions_label = conventions_label
        #: The raw `discovery.json`, for `core_set` only -- which artifacts the
        #: repo's services and frameworks license.  `{}` without `--discovery`.
        self.discovery = discovery if isinstance(discovery, dict) else {}
        self.checks = []  # type: List[Dict[str, str]]
        self.warnings = []  # type: List[str]
        #: Counted for every check, emitted or not, so `summary` stays true
        #: even when the entry list is truncated.
        self.counts = {"pass": 0, "fail": 0, "warn": 0}
        self.dropped_checks = 0
        self.artifacts = []  # type: List[Dict[str, Any]]
        #: realpaths of the files THIS run's manifest claims, all inside the
        #: repo.  A hook may be executed only if it resolves into this set.
        self.generated_real = set()  # type: set
        #: Lazily created throwaway cwd/HOME for executed hooks.
        self.fixture_dir = None  # type: Optional[str]
        #: Cached results of the read-only git calls `uninstall` makes.  The
        #: note is set once when git turns out to be unusable, so a repo with
        #: no git does not pay for one subprocess per artifact.
        self._git_note = ""
        self._git_usable_cache = None  # type: Optional[Tuple[bool, str]]

    # -- plumbing ---------------------------------------------------------

    def add(self, name: str, target: str, status: str, detail: str) -> None:
        if status in self.counts:
            self.counts[status] += 1

        if len(self.checks) >= MAX_CHECKS:
            # A truncated run must never lose a failure.  Evict the oldest
            # passing entry to make room for a fail or a warn instead.
            if status == PASS:
                self.dropped_checks += 1
                return
            evicted = False
            for index, existing in enumerate(self.checks):
                if existing["status"] == PASS:
                    del self.checks[index]
                    evicted = True
                    break
            if not evicted:
                self.dropped_checks += 1
                return
            self.dropped_checks += 1

        self.checks.append(
            {
                "name": name,
                "target": _short(target, 200),
                "status": status,
                "detail": _short(detail, DETAIL_MAX),
            }
        )

    def warn(self, message: str) -> None:
        emit_lib.warn(self.warnings, _short(message, 240))

    def rel(self, path: str) -> str:
        try:
            return os.path.relpath(path, self.repo)
        except ValueError:  # pragma: no cover - different drive on Windows
            return path

    def display(self, path: str) -> str:
        """Repo-relative inside the repo, absolute outside it."""
        real = os.path.realpath(path)
        if real == self.repo_real or real.startswith(self.repo_real + os.sep):
            return self.rel(path)
        return path

    def inside_repo(self, path: str) -> bool:
        real = os.path.realpath(path)
        return real == self.repo_real or real.startswith(self.repo_real + os.sep)

    # -- hook execution fencing -------------------------------------------

    @property
    def exec_enabled(self) -> bool:
        """
        Execution is opt-in.  `--no-exec` is the default and also an accepted
        alias for it, so it wins if a caller passes both.
        """
        if getattr(self.options, "no_exec", False):
            return False
        return bool(getattr(self.options, "exec_hooks", False))

    def _index_generated_paths(self) -> None:
        """
        Record every in-repo file this run's manifest declares.  Built before
        the per-artifact loop, because a hook's *command* may point at a
        different manifest entry (a wrapper) than its own `path`.
        """
        for artifact in self.artifacts:
            raw = artifact.get("path") or ""
            if not raw or "\x00" in raw:
                continue
            expanded = os.path.expanduser(raw)
            joined = expanded if os.path.isabs(expanded) else os.path.join(self.repo, expanded)
            real = os.path.realpath(os.path.abspath(joined))
            if real == self.repo_real or real.startswith(self.repo_real + os.sep):
                self.generated_real.add(real)

    def is_generated_by_this_run(self, script: str) -> bool:
        """True only for a path inside the repo AND named by this manifest."""
        if not script:
            return False
        real = os.path.realpath(script)
        if not (real == self.repo_real or real.startswith(self.repo_real + os.sep)):
            return False
        return real in self.generated_real

    def _ensure_fixture(self) -> str:
        """A throwaway directory outside the repo: the hook's cwd and HOME."""
        if self.fixture_dir and os.path.isdir(self.fixture_dir):
            return self.fixture_dir
        self.fixture_dir = tempfile.mkdtemp(prefix="agentify-verify-")
        return self.fixture_dir

    def cleanup_fixture(self) -> None:
        if not self.fixture_dir:
            return
        # Refuse to remove anything that somehow landed inside the repo.
        if self.inside_repo(self.fixture_dir):  # pragma: no cover - defensive
            self.warn("fixture directory resolved inside the repo; left in place: %s" % self.fixture_dir)
            self.fixture_dir = None
            return
        try:
            shutil.rmtree(self.fixture_dir, ignore_errors=True)
        except Exception:  # pragma: no cover - defensive
            pass
        self.fixture_dir = None

    # -- main -------------------------------------------------------------

    def run(self) -> None:
        declared_root = self.manifest.get("repo_root")
        if isinstance(declared_root, str) and declared_root.strip():
            declared = os.path.realpath(os.path.abspath(os.path.expanduser(declared_root)))
            if declared != self.repo_real:
                self.warn(
                    "manifest repo_root (%s) differs from --repo (%s); using --repo"
                    % (_short(declared_root, 80), _short(self.repo, 80))
                )
        if not os.path.isdir(self.repo):
            self.warn("repo root does not exist or is not a directory: %s" % self.repo)
        declared_target = str(self.manifest.get("target") or "").strip()
        if declared_target and not self.target:
            # Silently falling back would judge a build against another agent's
            # paths -- the defect class this whole table exists to prevent.
            self.warn(
                "manifest target %r is not one of %s; every path- and hook-shaped check ran as %s"
                % (
                    _short(declared_target, 40),
                    "/".join(sorted(TARGET_PROFILES)),
                    self.profile["label"],
                )
            )
        elif not declared_target:
            self.warn(
                "manifest names no target; every path- and hook-shaped check ran as %s"
                % self.profile["label"]
            )
        if getattr(self.options, "no_exec", False) and getattr(self.options, "exec_hooks", False):
            self.warn("--no-exec and --exec-hooks were both given; --no-exec wins, no hook was executed")

        self._prepare_artifacts()
        self._index_generated_paths()
        # The manifest label and the artifact count ride in `checks` rather
        # than as extra top-level keys: the contract fixes the top-level shape.
        self.add(
            "manifest_loaded",
            self.manifest_label or "manifest",
            PASS if self.artifacts else WARN,
            "%d artifact(s) declared for repo %s"
            % (len(self.artifacts), _short(self.display(self.repo), 80)),
        )
        self._check_ids_unique()

        for artifact in self.artifacts:
            self._check_artifact(artifact)

        self._check_names_unique()
        self._check_core_set()
        self._check_settings_json()
        self._check_plugin_paths()
        self._check_mcp_json()
        self._check_rule_wired()
        self._check_hook_wired()
        self._check_rule_contradictions()
        self._check_undo_record()
        self._check_committed_clean()
        self._check_uninstall()

        if self.dropped_checks:
            self.warn(
                "check list truncated at %d entries; %d passing check(s) not listed "
                "(summary counts are still complete; failures are never dropped)"
                % (MAX_CHECKS, self.dropped_checks)
            )

    # -- manifest entries -------------------------------------------------

    def _prepare_artifacts(self) -> None:
        raw_list = self.manifest.get("artifacts") or []
        for index, raw in enumerate(raw_list):
            label = "artifacts[%d]" % index
            if not isinstance(raw, dict):
                self.add("manifest_entry", label, FAIL, "entry is not an object")
                continue

            artifact_id = str(raw.get("id") or "").strip()
            path_value = str(raw.get("path") or "").strip()
            action = str(raw.get("action") or "").strip().lower()
            evidence = raw.get("evidence")
            type_value, type_known = _norm_type(raw.get("type"))

            problems = []  # type: List[str]
            if not artifact_id:
                problems.append("missing `id`")
            if not path_value:
                problems.append("missing `path`")
            if action not in ("created", "modified"):
                problems.append("`action` must be created|modified, got %r" % (raw.get("action"),))
            # A FAIL, never a warn.  "A candidate with no evidence count maps
            # to nothing and must not be built" (CLAUDE.md, from PRD 8) is the
            # product's core claim: evidence-derived, not templated.  An
            # artifact that reached the build with an empty `evidence` field
            # either lost its evidence between phase 6 and phase 7, or was
            # never justified at all -- and a warn among forty other rows is
            # how that ships unnoticed.  It fails loudly instead.
            missing_evidence = not isinstance(evidence, str) or not evidence.strip()
            if missing_evidence:
                problems.append(
                    "missing or empty `evidence` -- an artifact with no evidence must not be "
                    "built (PRD 8); restore the counted signal it came from or remove the artifact"
                )
            if not type_known:
                problems.append("unknown `type` %r; checked as `other`" % (raw.get("type"),))

            target = artifact_id or path_value or label
            fatal = (
                not artifact_id
                or not path_value
                or action not in ("created", "modified")
                or missing_evidence
            )
            if problems and fatal:
                self.add("manifest_entry", target, FAIL, "; ".join(problems))
                if not path_value:
                    continue
            elif problems:
                self.add("manifest_entry", target, WARN, "; ".join(problems))
            else:
                self.add("manifest_entry", target, PASS, "id, type, path, action and evidence present")

            self.artifacts.append(
                {
                    "id": artifact_id or ("<unnamed:%d>" % index),
                    "declared_id": artifact_id,
                    "type": type_value,
                    "raw_type": raw.get("type"),
                    "path": path_value,
                    "action": action if action in ("created", "modified") else "created",
                    "evidence": evidence if isinstance(evidence, str) else "",
                    "command": raw.get("command"),
                    "name": raw.get("name"),
                    # The undo fields.  Carried through because `undo_partition`
                    # reads them: `ignored` decides which of the two removal
                    # mechanisms owns this file, and `restore` decides whether
                    # committing it would destroy the user's own content.  Any
                    # other key in the entry is still ignored.
                    "ignored": raw.get("ignored"),
                    "ignored_by": raw.get("ignored_by"),
                    "restore": raw.get("restore"),
                    "pre_existing_sha256": raw.get("pre_existing_sha256"),
                    "index": index,
                }
            )

    def _check_ids_unique(self) -> None:
        counts = {}  # type: Dict[str, int]
        for artifact in self.artifacts:
            key = artifact["declared_id"]
            if not key:
                continue
            counts[key] = counts.get(key, 0) + 1
        duplicates = sorted(key for key, count in counts.items() if count > 1)
        if duplicates:
            self.add(
                "id_unique",
                "manifest",
                FAIL,
                "duplicate agentify ids break idempotent rerun: %s" % ", ".join(duplicates[:8]),
            )
        else:
            self.add(
                "id_unique",
                "manifest",
                PASS,
                "%d artifact ids, all unique" % len(counts),
            )

    def _check_names_unique(self) -> None:
        """
        Two skills (or two subagents) with the same frontmatter `name` shadow
        each other: whichever loads second wins, silently.  Scoped to what this
        run built -- collisions with pre-existing artifacts are the audit-mode
        job of phase 1, not of the verifier.
        """
        for kind in ("skill", "subagent"):
            names = {}  # type: Dict[str, List[str]]
            for artifact in self.artifacts:
                if artifact["type"] != kind:
                    continue
                data = (artifact.get("frontmatter") or {}).get("data") or {}
                name = data.get("name")
                if isinstance(name, str) and name.strip():
                    names.setdefault(name.strip(), []).append(artifact["id"])
            if not names:
                continue
            duplicates = sorted(name for name, ids in names.items() if len(ids) > 1)
            if duplicates:
                detail = "; ".join(
                    "%s used by %s" % (name, ", ".join(names[name])) for name in duplicates[:4]
                )
                self.add("name_unique", "%ss" % kind, FAIL, "duplicate %s name(s): %s" % (kind, detail))
            else:
                self.add(
                    "name_unique",
                    "%ss" % kind,
                    PASS,
                    "%d %s name(s), all distinct" % (len(names), kind),
                )

    # -- per artifact -----------------------------------------------------

    def _check_artifact(self, artifact: Dict[str, Any]) -> None:
        target, contained = self._check_containment(artifact)
        if not contained:
            return
        artifact["abs"] = target

        text = self._check_exists(artifact, target)
        if text is None:
            return

        frontmatter = {"present": False, "ok": True, "data": {}, "notes": [], "body": text}
        if _is_markdown(artifact["path"]):
            frontmatter = parse_frontmatter(text)
            self._check_frontmatter(artifact, frontmatter)
        artifact["frontmatter"] = frontmatter
        artifact["text"] = text

        if artifact["action"] == "modified":
            self._check_markers(artifact, text)

        self._check_metadata(artifact, text, frontmatter)
        self._check_evidence_match(artifact)

        kind = artifact["type"]
        if kind == "skill":
            self._check_skill(artifact, frontmatter)
        elif kind == "subagent":
            self._check_subagent(artifact, frontmatter)
        elif kind == "rule":
            self._check_rule(artifact, frontmatter, text)
        elif kind == "hook":
            self._check_hook(artifact, target)

    def _check_containment(self, artifact: Dict[str, Any]) -> Tuple[str, bool]:
        raw_path = artifact["path"]
        label = self.rel(raw_path) if os.path.isabs(raw_path) else raw_path

        if "\x00" in raw_path:
            self.add("path_containment", label, FAIL, "path contains a null byte")
            return ("", False)

        expanded = os.path.expanduser(raw_path)
        joined = expanded if os.path.isabs(expanded) else os.path.join(self.repo, expanded)
        absolute = os.path.abspath(joined)
        real = os.path.realpath(absolute)

        traversal = ".." in raw_path.replace("\\", "/").split("/")
        inside = real == self.repo_real or real.startswith(self.repo_real + os.sep)

        if not inside:
            self.add(
                "path_containment",
                label,
                FAIL,
                "resolves outside the repo root (%s); refusing to inspect it" % _short(real, 120),
            )
            return ("", False)
        if traversal:
            self.add(
                "path_containment",
                label,
                WARN,
                "path contains a '..' segment; it stays inside the repo but should be written plainly",
            )
            return (absolute, True)

        self.add("path_containment", label, PASS, "inside the repo root, no traversal")
        return (absolute, True)

    def _check_exists(self, artifact: Dict[str, Any], target: str) -> Optional[str]:
        label = self.rel(target)
        if not os.path.exists(target):
            self.add("file_exists", label, FAIL, "file does not exist (id %s)" % artifact["id"])
            return None
        if os.path.isdir(target):
            self.add("file_exists", label, FAIL, "path is a directory, not a file")
            return None
        try:
            size = os.path.getsize(target)
        except OSError as exc:
            self.add("file_exists", label, FAIL, "cannot stat file: %s" % exc)
            return None
        if size == 0:
            self.add("file_exists", label, FAIL, "file is empty (0 bytes)")
            return None

        text, error = _read_text(target)
        if error:
            self.add("file_exists", label, WARN, "exists (%d bytes) but is not readable as text: %s" % (size, error))
            return None
        if not text.strip():
            self.add("file_exists", label, FAIL, "file contains only whitespace (%d bytes)" % size)
            return None

        self.add("file_exists", label, PASS, "%d bytes" % size)
        return text

    def _check_frontmatter(self, artifact: Dict[str, Any], frontmatter: Dict[str, Any]) -> None:
        label = self.rel(artifact["abs"])
        required = artifact["type"] in FRONTMATTER_REQUIRED and artifact["action"] == "created"

        if not frontmatter["present"]:
            if required:
                self.add(
                    "frontmatter",
                    label,
                    FAIL,
                    "no `---` frontmatter block; a %s must declare name and description" % artifact["type"],
                )
            else:
                self.add(
                    "frontmatter",
                    label,
                    PASS,
                    "no frontmatter, and none required for type %s (action %s)"
                    % (artifact["type"], artifact["action"]),
                )
            return

        if not frontmatter["ok"]:
            self.add("frontmatter", label, FAIL, "; ".join(frontmatter["notes"])[:DETAIL_MAX])
            return

        keys = sorted(frontmatter["data"].keys())
        if frontmatter["notes"]:
            self.add(
                "frontmatter",
                label,
                WARN,
                "parsed %d keys, with unsupported constructs skipped: %s"
                % (len(keys), "; ".join(frontmatter["notes"][:3])),
            )
            return
        self.add("frontmatter", label, PASS, "parsed %d keys: %s" % (len(keys), ", ".join(keys[:10])))

    def _check_markers(self, artifact: Dict[str, Any], text: str) -> None:
        label = self.rel(artifact["abs"])
        artifact_id = artifact["declared_id"] or artifact["id"]
        markers = find_markers(text)

        # JSON carries no comments, so a merged JSON file (settings.json,
        # .mcp.json, plugin.json) cannot hold begin/end markers -- and
        # templates/settings-hooks.json.tmpl explicitly forbids merging the
        # `_agentify` key into the user's settings.json.  Idempotency for these
        # is structural instead: settings hooks re-match on the hook command
        # path, .mcp.json on the server name.  Failing them here would fail
        # every run that followed the templates correctly.
        # The exemption is about the FORMAT, not the type name: JSON holds no
        # comment, so a `settings` / `mcp` / `plugin` artifact never carried a
        # marker and never can.  A Codex `mcp` artifact is TOML, which DOES take
        # `#` comments -- and its removal now routes through the marker script
        # (see `_is_merged_json`), so exempting it here would hand phase 8 a
        # marker script with nothing to find.
        if artifact["type"] in JSON_TYPES and _is_json_path(artifact["path"]) and not markers:
            self.add(
                "markers",
                label,
                PASS,
                "JSON file: no comment markers possible; rerun matches structurally "
                "(hook command path / server name), per settings-hooks.json.tmpl",
            )
            return

        matched_begin = [m for m in markers if m["kind"] == "begin" and m["id"] == artifact_id]
        matched_end = [m for m in markers if m["kind"] == "end" and m["id"] == artifact_id]
        unlabelled_begin = [m for m in markers if m["kind"] == "begin" and m["id"] is None]
        unlabelled_end = [m for m in markers if m["kind"] == "end" and m["id"] is None]

        if not markers:
            self.add(
                "markers",
                label,
                FAIL,
                "modified file carries no agentify begin/end markers; a rerun cannot update it in place",
            )
            return

        if not matched_begin and not matched_end:
            if len(unlabelled_begin) == 1 and len(unlabelled_end) == 1:
                self.add(
                    "markers",
                    label,
                    WARN,
                    "one begin/end pair found but it carries no id; expected id=%s" % artifact_id,
                )
            else:
                other = sorted(set(m["id"] for m in markers if m["id"]))
                self.add(
                    "markers",
                    label,
                    FAIL,
                    "no marker pair for id=%s (file carries: %s)" % (artifact_id, ", ".join(other) or "unlabelled"),
                )
            return

        if len(matched_begin) != 1 or len(matched_end) != 1:
            self.add(
                "markers",
                label,
                FAIL,
                "expected exactly one begin/end pair for id=%s, found %d begin and %d end"
                % (artifact_id, len(matched_begin), len(matched_end)),
            )
            return

        if matched_begin[0]["pos"] > matched_end[0]["pos"]:
            self.add("markers", label, FAIL, "end marker for id=%s appears before its begin marker" % artifact_id)
            return

        self.add("markers", label, PASS, "exactly one begin/end pair for id=%s" % artifact_id)

    def _check_metadata(self, artifact: Dict[str, Any], text: str, frontmatter: Dict[str, Any]) -> None:
        label = self.rel(artifact["abs"])
        scope_text = text
        if artifact["action"] == "modified":
            block = marker_block(text, artifact["declared_id"] or artifact["id"])
            if block.strip():
                scope_text = block

        meta = collect_metadata(scope_text, frontmatter)
        artifact["meta"] = meta
        missing = [key for key in REQUIRED_META if not meta.get(key)]

        soft = artifact["type"] in JSON_TYPES or artifact["action"] == "modified"
        if missing:
            reason = ""
            if artifact["type"] == "settings":
                # Expected, not a defect -- but say it about the TARGET's own
                # registry.  This used to hardcode "settings.json is the user's
                # file", which printed a Claude Code literal in the middle of a
                # Codex run, where the file is `.codex/hooks.json` and the
                # reason is a different one: measured, an `_agentify` key beside
                # `hooks` makes Codex reject the whole file and load ZERO hooks.
                allowed = self.profile.get("registry_allowed_keys")
                if allowed:
                    why = (
                        "it accepts only the top-level key(s) %s, so an `_agentify` object there"
                        " would make %s reject the whole file and load zero hooks"
                        % (
                            _join_and(sorted("`%s`" % key for key in allowed)),
                            self.profile["label"],
                        )
                    )
                else:
                    why = (
                        "it is the user's own file and carries no agentify metadata by design"
                        " (%s)" % self.profile["registry_doc"]
                    )
                reason = (
                    " (expected: %s is the %s hook registry, not an agentify file -- %s;"
                    " provenance lives in the hook command path)"
                    % (label, self.profile["label"], why)
                )
            elif artifact["type"] == "manifest":
                reason = (
                    " (build-manifest.json is agentify's own output and carries its identity"
                    " the way mcp.json.tmpl and plugin.json.tmpl do: an inert top-level"
                    ' `"_agentify": {"agentify-id": "build-manifest", "agentify-version": 1,'
                    ' "agentify-generated": "<yyyy-mm-dd>", "agentify-evidence": "<counts>",'
                    ' "note": "... Safe to delete or edit."}` object. Nothing reads it at'
                    " runtime; it is what lets a rerun recognise its own manifest)"
                )
            elif artifact["type"] in JSON_TYPES:
                reason = " (JSON cannot carry a comment header; use the `_agentify` object)"
            elif artifact["action"] == "modified":
                reason = " (the begin marker carries the id, but the block should still state version/date/evidence)"
            self.add(
                "metadata",
                label,
                WARN if soft else FAIL,
                "missing %s%s" % (", ".join(missing), reason),
            )
            return

        found_id = meta.get("agentify-id", "")
        declared = artifact["declared_id"]
        if declared and found_id and found_id != declared:
            self.add(
                "metadata",
                label,
                FAIL,
                "agentify-id in the file (%s) does not match the manifest id (%s)" % (found_id, declared),
            )
            return

        # The fifth part of the contract's ID scheme: every generated file tells
        # the reader it is disposable.  Missing it is untidy, never broken.
        if "safe to delete or edit" not in scope_text.lower():
            self.add(
                "metadata",
                label,
                WARN,
                "carries agentify-id=%s but not the line `Safe to delete or edit.`; "
                "every generated file states that it is disposable" % found_id,
            )
            return

        self.add(
            "metadata",
            label,
            PASS,
            "agentify-id=%s version=%s generated=%s, evidence present, marked safe to delete"
            % (found_id, meta.get("agentify-version", ""), meta.get("agentify-generated", "")),
        )

    # -- type specific ----------------------------------------------------

    def _check_skill(self, artifact: Dict[str, Any], frontmatter: Dict[str, Any]) -> None:
        label = self.rel(artifact["abs"])
        data = frontmatter.get("data") or {}
        name = data.get("name")
        description = data.get("description")

        problems = []  # type: List[str]
        if not isinstance(name, str) or not name.strip():
            problems.append("frontmatter has no `name`")
        if not isinstance(description, str) or not description.strip():
            problems.append("frontmatter has no non-empty `description`")
        elif len(description) >= 1024:
            problems.append("`description` is %d chars; the limit is 1024" % len(description))

        directory = os.path.basename(os.path.dirname(artifact["abs"]))
        expected = artifact.get("name") or directory
        if isinstance(name, str) and name.strip() and expected:
            if name.strip() != expected:
                problems.append("`name` is %r but the skill directory is %r; they must match" % (name.strip(), expected))

        if problems:
            self.add("skill_frontmatter", label, FAIL, "; ".join(problems))
            return
        self.add(
            "skill_frontmatter",
            label,
            PASS,
            "name=%s matches its directory; description %d chars" % (name.strip(), len(description)),
        )

    def _check_subagent(self, artifact: Dict[str, Any], frontmatter: Dict[str, Any]) -> None:
        label = self.rel(artifact["abs"])

        # A subagent has two file shapes, exactly as a rule does.  Claude Code:
        # `.claude/agents/<name>.md`, markdown with YAML frontmatter.  Codex:
        # `.codex/agents/<name>.toml`, TOML with `name`, `description` and
        # `developer_instructions` (adapters/capabilities.md, row "Subagents").
        # Asking a TOML file for YAML frontmatter FAILED every correct Codex
        # subagent -- the same false-FAIL defect as `rule_scope` on a command
        # policy, and `codex-agent.toml.tmpl` 9a documented it the same way.
        if not _is_markdown(artifact["path"]):
            self._check_subagent_toml(artifact, label)
            return

        data = frontmatter.get("data") or {}
        name = data.get("name")
        description = data.get("description")

        problems = []  # type: List[str]
        if not isinstance(name, str) or not name.strip():
            problems.append("frontmatter has no `name`")
        if not isinstance(description, str) or not description.strip():
            problems.append("frontmatter has no non-empty `description`")
        elif len(description) >= 1024:
            problems.append("`description` is %d chars; the limit is 1024" % len(description))

        if problems:
            self.add("subagent_frontmatter", label, FAIL, "; ".join(problems))
        else:
            self.add(
                "subagent_frontmatter",
                label,
                PASS,
                "name=%s, description %d chars" % (name.strip(), len(description)),
            )

        if "tools" not in data:
            return
        declared = extract_globs(data.get("tools"))
        if not declared:
            self.add("subagent_tools", label, WARN, "`tools` is declared but empty; the subagent inherits nothing")
            return
        unknown = []  # type: List[str]
        for tool in declared:
            cleaned = tool.strip().strip(",")
            if not cleaned:
                continue
            if cleaned.lower().startswith("mcp__"):
                continue
            if cleaned == "*":
                continue
            if cleaned.lower() in KNOWN_TOOLS:
                continue
            unknown.append(cleaned)
        if unknown:
            self.add(
                "subagent_tools",
                label,
                WARN,
                "unrecognised tool name(s): %s (roster changes between releases; verify by hand)"
                % ", ".join(unknown[:6]),
            )
            return
        self.add("subagent_tools", label, PASS, "%d declared tools all recognised" % len(declared))

    def _check_subagent_toml(self, artifact: Dict[str, Any], label: str) -> None:
        """
        A Codex subagent, checked as the TOML it is.

        `codex-agent.toml.tmpl` 10 states the static contract exactly -- "that
        it parses as TOML, that the three required keys are present, that the
        filename stem equals `name`" -- so that is what this asserts, and
        nothing beyond it: no read-only probe can prove a newly written agents
        file is loaded, which is why the report's manual checklist still asks
        the user to spawn the agent by name in a live session.
        """
        text = artifact.get("text") or ""
        values, error = read_toml_scalars(text)
        if error:
            self.add("subagent_frontmatter", label, FAIL, "TOML does not parse: %s" % error)
            return

        problems = []  # type: List[str]
        name = values.get("name", "")
        description = values.get("description", "")
        for key in ("name", "description", "developer_instructions"):
            if not values.get(key, "").strip():
                problems.append("no `%s`; Codex requires name, description and developer_instructions" % key)
        if description and len(description) >= 1024:
            problems.append("`description` is %d chars; the limit is 1024" % len(description))

        stem = os.path.splitext(os.path.basename(artifact["path"]))[0]
        if name.strip() and stem and name.strip() != stem:
            problems.append("`name` is %r but the file is %s.toml; the stem must equal the name" % (name.strip(), stem))

        if problems:
            self.add("subagent_frontmatter", label, FAIL, "; ".join(problems[:4]))
            return
        self.add(
            "subagent_frontmatter",
            label,
            PASS,
            "TOML: name=%s matches the filename stem; description %d chars; "
            "developer_instructions %d chars"
            % (name.strip(), len(description), len(values.get("developer_instructions", ""))),
        )

        # Codex has no per-agent tool allowlist and pins no model.  Both are
        # WARNs about a real loss or a real hazard, never a FAIL: the file is
        # loadable either way.
        notes = []  # type: List[str]
        sandbox = values.get("sandbox_mode", "").strip().lower()
        if sandbox == "danger-full-access":
            self.add(
                "subagent_tools",
                label,
                FAIL,
                "`sandbox_mode = \"danger-full-access\"` -- a generated agent must never be "
                "granted it; use \"read-only\" for review/analysis work",
            )
            return
        if "tools" in values:
            notes.append("`tools` is not a Codex key -- there is no per-agent tool allowlist; the restriction is lost")
        if values.get("model", "").strip():
            notes.append("`model` is pinned to %s -- a pinned model goes stale and silently changes the session" % _short(values["model"], 40))
        if notes:
            self.add("subagent_tools", label, WARN, "; ".join(notes))
            return
        self.add(
            "subagent_tools",
            label,
            PASS,
            "no tool allowlist expected: Codex has none per agent%s"
            % (" (sandbox_mode = %s)" % sandbox if sandbox else ""),
        )

    def _check_rule(self, artifact: Dict[str, Any], frontmatter: Dict[str, Any], text: str) -> None:
        label = self.rel(artifact["abs"])
        data = frontmatter.get("data") or {}

        # A Codex command policy is Starlark, not prose: no frontmatter, no
        # `scope:`, no index-doc pointer, and nothing for the prose directive
        # reader to read.  Sending it down the prose path FAILED three checks on
        # a correct artifact.  See the "Rule SUBTYPES" section above.
        artifact["rule_subtype"] = rule_subtype(artifact["path"], text)
        if artifact["rule_subtype"] == RULE_SUBTYPE_POLICY:
            self._check_rule_policy(artifact, text)
            return

        # `paths` FIRST: it is the only key Claude Code's rule loader reads
        # (adapters/claude-code.md §4.2, verified by probe and by the 2.1.260
        # bundle, which reads `frontmatter.paths`).  The rest are legacy or
        # foreign spellings that agentify no longer emits but may still meet on
        # a hand-written or older generated rule, so they are still validated —
        # ranked below `paths`, and reported as inert.
        scope_key = None
        for candidate in ("paths", "scope", "globs", "applies_to", "applies-to", "applyTo"):
            if candidate in data:
                scope_key = candidate
                break

        if scope_key is None:
            # NOT a defect.  A rule with no `paths:` loads at session start,
            # unconditionally, with no index-doc reference of any kind — that is
            # what the probe measured.  rule.md.tmpl tells the model to delete
            # the key outright for a genuinely repo-wide rule rather than write
            # `**`.  Failing this hard-failed a correct artifact, and phase 8
            # would then have removed it.  How many unscoped rules a setup
            # should carry is coverage.md's and the adapter's business, not the
            # verifier's; the note exists so the reader knows which of the two
            # load behaviours this rule got.
            self.add(
                "rule_scope",
                label,
                PASS,
                "no `paths:` — loads eagerly in every session (counts against the unscoped-rule cap)",
            )
        else:
            globs = extract_globs(data.get(scope_key))
            # Kept whatever the validity verdict: `rule_contradiction` needs to
            # know which paths a rule claims before it can decide whether two
            # rules can even collide.
            artifact["rule_globs"] = list(globs)
            if not globs:
                self.add("rule_scope", label, FAIL, "`%s` is present but empty" % scope_key)
            else:
                errors = []  # type: List[str]
                for pattern in globs:
                    problem = validate_glob(pattern)
                    if problem:
                        errors.append("%s: %s" % (pattern, problem))
                if errors:
                    self.add("rule_scope", label, FAIL, "; ".join(errors[:4]))
                elif scope_key != "paths":
                    # The globs parse, but Claude Code will never read them.
                    # This is worse than an unscoped rule, because the file
                    # advertises a scope that nothing enforces: the rule loads
                    # eagerly in every session while claiming to be narrow.
                    # WARN, not FAIL — the rule still works, it is just wider
                    # than it says, and the remedy is a one-word rename.
                    self.add(
                        "rule_scope",
                        label,
                        WARN,
                        "`%s` is not read by Claude Code — only `paths:` is; rename the key, or "
                        "delete it if the rule really is repo-wide (%d glob(s): %s)"
                        % (scope_key, len(globs), ", ".join(globs[:6])),
                    )
                else:
                    self.add(
                        "rule_scope",
                        label,
                        PASS,
                        "%d valid glob(s), loaded on demand when a match is read: %s"
                        % (len(globs), ", ".join(globs[:6])),
                    )

        # `or text` would be wrong here: a rule whose body really is empty has
        # `body == ""`, and falling back to the whole file would let its own
        # frontmatter count as content.
        body = frontmatter["body"] if frontmatter.get("present") else text
        if artifact["action"] == "modified":
            block = marker_block(text, artifact["declared_id"] or artifact["id"])
            if block.strip():
                body = block
        stripped = _MARKER.sub("", body)
        stripped = _META_LINE.sub("", stripped)
        stripped = re.sub(r"^\s*<!--[\s\S]{0,2000}?-->\s*$", "", stripped, flags=re.MULTILINE)
        content = stripped.strip()

        if len(content) < 10:
            self.add("rule_body", label, FAIL, "rule body is empty once frontmatter and markers are removed")
            return
        artifact["rule_body"] = content
        self.add("rule_body", label, PASS, "%d chars of rule text" % len(content))

    # -- rules, the other shape: a Codex Starlark command policy ------------

    def _check_rule_policy(self, artifact: Dict[str, Any], text: str) -> None:
        """
        Checks written for what a `.codex/rules/*.rules` file actually is.

        The hazard being guarded is specific and measured: a malformed policy
        is a FATAL Codex startup error, not a skipped file -- `Error loading
        rules: ... invalid decision: ask`, after which `codex exec` refuses to
        start in that repo at all.  So the checks are, in order of what they
        cost the user when they are wrong:

          rule_policy_syntax     it parses (Starlark is a Python dialect, so
                                 `ast` gives the same verdict on this).
          rule_policy_decision   every block's `decision` is one of the three
                                 legal values.
          rule_policy_pattern    every block's command prefix is non-empty.
          rule_policy_examples   `match` is present and every example is caught
                                 by some rule in the file -- Codex enforces
                                 exactly this at load time ("expected every
                                 example to match at least one rule"), so a
                                 miss here is the fatal error, found early.
          rule_policy_execpolicy `codex execpolicy check` agreed, when a Codex
                                 binary resolved AND execution was opted into.

        Nothing here reads a `scope:` or looks for an index-doc pointer: a
        command policy governs commands rather than paths, and `.codex/rules/`
        is a native load path (trust-gated), so both would be false FAILs.
        """
        label = self.rel(artifact["abs"])
        blocks, syntax_error = parse_policy_rules(text)

        if syntax_error:
            self.add(
                "rule_policy_syntax",
                label,
                FAIL,
                "does not parse as Starlark (%s). A malformed .rules file is a FATAL Codex "
                "startup error, not a skipped file: every session in this repo refuses to "
                "start until it is fixed or deleted" % syntax_error,
            )
            return

        rules = [block for block in blocks if block["function"]]
        strays = [block for block in blocks if not block["function"]]
        if not rules:
            self.add(
                "rule_policy_syntax",
                label,
                FAIL,
                "parses, but declares no policy rule: no `prefix_rule(...)` call. "
                "The file is inert -- remove it, or state the rule it was meant to carry",
            )
            return

        unknown = sorted(set(block["function"] for block in rules if block["function"] not in POLICY_FUNCTIONS))
        notes = []  # type: List[str]
        if unknown:
            # WARN, never FAIL: the rules language is documented as experimental
            # and subject to change, and failing a valid-but-newer construct
            # would repeat the defect this whole path exists to fix.
            notes.append("unrecognised policy function(s) %s -- verify with `codex execpolicy check`" % ", ".join(unknown))
        if strays:
            notes.append(
                "%d top-level statement(s) that are not policy calls (%s)"
                % (len(strays), ", ".join(sorted(set(block["statement"] for block in strays))[:3]))
            )
        positional = [block for block in rules if block.get("positional")]
        if positional:
            notes.append("%d call(s) pass positional arguments; the documented form is keyword-only" % len(positional))
        unreadable = sorted(set(key for block in rules for key in block["unreadable"]))
        if unreadable:
            notes.append("non-literal value(s) for %s, read as unset" % ", ".join(unreadable[:4]))

        self.add(
            "rule_policy_syntax",
            label,
            WARN if notes else PASS,
            ("%d policy rule(s) parse; " % len(rules)) + ("; ".join(notes) if notes else "keyword-only calls, all recognised"),
        )

        # -- decision ------------------------------------------------------
        bad_decision = []  # type: List[str]
        missing_decision = []  # type: List[str]
        decisions = []  # type: List[str]
        for block in rules:
            value = block["args"].get("decision")
            where = "line %d" % block["line"]
            if not isinstance(value, str) or not value.strip():
                missing_decision.append(where)
            elif value.strip().lower() not in POLICY_DECISIONS:
                bad_decision.append("%s: %r" % (where, value))
            else:
                decisions.append(value.strip().lower())
        if bad_decision or missing_decision:
            problems = []
            if bad_decision:
                problems.append("invalid `decision` at %s" % "; ".join(bad_decision[:4]))
            if missing_decision:
                problems.append("no `decision` at %s" % ", ".join(missing_decision[:4]))
            self.add(
                "rule_policy_decision",
                label,
                FAIL,
                "%s -- legal values are %s. MEASURED: any other value is `Error loading rules: "
                "invalid decision`, and Codex then will not start in this repo at all"
                % ("; ".join(problems), "/".join(sorted(POLICY_DECISIONS))),
            )
        else:
            self.add(
                "rule_policy_decision",
                label,
                PASS,
                "%d decision(s), all legal: %s" % (len(decisions), ", ".join(sorted(set(decisions)))),
            )

        # -- pattern -------------------------------------------------------
        empty_pattern = []  # type: List[str]
        patterns = []  # type: List[Tuple[Dict[str, Any], Any]]
        for block in rules:
            key, value = _policy_pattern_of(block)
            if not key:
                empty_pattern.append("line %d: no `pattern`" % block["line"])
            elif not isinstance(value, (list, tuple, str)) or not value:
                empty_pattern.append("line %d: `%s` is empty" % (block["line"], key))
            else:
                patterns.append((block, value))
        if empty_pattern:
            self.add(
                "rule_policy_pattern",
                label,
                FAIL,
                "%s -- a rule with no command prefix matches nothing (or, worse, everything); "
                "give it the shortest prefix the evidence justifies"
                % "; ".join(empty_pattern[:4]),
            )
        else:
            shown = []  # type: List[str]
            for _block, value in patterns[:3]:
                if isinstance(value, (list, tuple)):
                    # A nested list is an alternation; render it as one so the
                    # row reads as the command it matches, not as a repr.
                    shown.append(
                        " ".join(
                            "|".join(str(option) for option in item)
                            if isinstance(item, (list, tuple))
                            else str(item)
                            for item in value
                        )
                    )
                else:
                    shown.append(str(value))
            self.add(
                "rule_policy_pattern",
                label,
                PASS,
                "%d non-empty command prefix(es): %s" % (len(patterns), "; ".join(shown)),
            )

        self._check_policy_examples(label, rules)
        self._check_policy_execpolicy(label, artifact, rules)

    def _check_policy_examples(self, label: str, rules: List[Dict[str, Any]]) -> None:
        """
        `match` / `not_match` are ENFORCED SELF-TESTS, run here rather than at
        the user's next Codex start.

        A `match` example that no rule in the file catches is a load-time hard
        error ("expected every example to match at least one rule"), so it is a
        FAIL -- but only when every pattern in the file is one this script's
        matcher fully understands.  If any pattern uses a construct it cannot
        read, the verdict drops to WARN: a matcher that is stricter than Codex's
        would fail a correct file, which is the exact defect being fixed here.
        `not_match` violations stay a WARN for the same reason.
        """
        readable = all(_policy_pattern_readable(_policy_pattern_of(block)[1]) for block in rules)
        missing = [block for block in rules if not block["args"].get("match")]
        if missing:
            self.add(
                "rule_policy_examples",
                label,
                FAIL,
                "%d rule(s) declare no `match` example (line(s) %s); Codex requires at least "
                "one per rule and refuses to load the file without it"
                % (len(missing), ", ".join(str(block["line"]) for block in missing[:4])),
            )
            return

        uncaught = []  # type: List[str]
        leaked = []  # type: List[str]
        checked = 0
        for block in rules:
            for example in block["args"].get("match") or []:
                if not isinstance(example, str):
                    continue
                checked += 1
                if not any(
                    policy_matches(_policy_pattern_of(other)[1] or [], example)
                    for other in rules
                    if _policy_pattern_readable(_policy_pattern_of(other)[1])
                ):
                    uncaught.append(example)
            for example in block["args"].get("not_match") or []:
                if not isinstance(example, str):
                    continue
                checked += 1
                if _policy_pattern_readable(_policy_pattern_of(block)[1]) and policy_matches(
                    _policy_pattern_of(block)[1], example
                ):
                    leaked.append(example)

        if uncaught:
            self.add(
                "rule_policy_examples",
                label,
                FAIL if readable else WARN,
                "`match` example(s) no rule in this file catches: %s. Codex checks this at "
                "load time and refuses to start (\"expected every example to match at least "
                "one rule\")%s"
                % (
                    ", ".join(_short(item, 40) for item in uncaught[:4]),
                    "" if readable else " -- WARN, not FAIL: a pattern here uses a construct this checker cannot read",
                ),
            )
            return
        if leaked:
            self.add(
                "rule_policy_examples",
                label,
                WARN,
                "`not_match` example(s) its own rule DOES match: %s -- the near-miss the user "
                "is supposed to run instead would be caught too; confirm with `codex execpolicy check`"
                % ", ".join(_short(item, 40) for item in leaked[:4]),
            )
            return

        without_negative = [block for block in rules if not block["args"].get("not_match")]
        if without_negative:
            self.add(
                "rule_policy_examples",
                label,
                WARN,
                "%d example(s) all behave as declared, but %d rule(s) carry no `not_match` "
                "(line(s) %s): nothing pins down what stays allowed, and prefix matching has "
                "no semantics -- `npm` does not catch `npx`, `pnpm`, or npm inside `bash -c`"
                % (
                    checked,
                    len(without_negative),
                    ", ".join(str(block["line"]) for block in without_negative[:4]),
                ),
            )
            return
        self.add(
            "rule_policy_examples",
            label,
            PASS,
            "%d declared example(s) behave as written: every `match` is caught by a rule in "
            "this file, no `not_match` is" % checked,
        )

    def _check_policy_execpolicy(
        self, label: str, artifact: Dict[str, Any], rules: List[Dict[str, Any]]
    ) -> None:
        """
        Codex's own loader, asked for a second opinion -- when that is cheap.

        Run only when a `codex` binary resolves AND the run opted into
        execution (`--exec-hooks`).  This script's default posture is to
        execute nothing, and that posture is not weakened for a convenience:
        the static checks above already cover the fatal cases, and the row says
        plainly when the binary was not consulted rather than implying it was.
        """
        binary = _resolve_codex(self.target)
        if not binary:
            self.add(
                "rule_policy_execpolicy",
                label,
                PASS,
                "checked statically; `codex execpolicy check` not run (no `codex` binary on PATH). "
                "Confirm by hand: codex execpolicy check --pretty --rules %s -- <a command the rule should catch>"
                % label,
            )
            return
        if not self.exec_enabled:
            self.add(
                "rule_policy_execpolicy",
                label,
                PASS,
                "checked statically; `codex execpolicy check` not run (this run executes nothing -- "
                "pass --exec-hooks to consult the %s binary)" % _short(binary, 60),
            )
            return

        example = ""
        for block in rules:
            for candidate in block["args"].get("match") or []:
                if isinstance(candidate, str) and candidate.strip():
                    example = candidate.strip()
                    break
            if example:
                break
        if not example:
            self.add(
                "rule_policy_execpolicy",
                label,
                WARN,
                "no `match` example to check the file with; `codex execpolicy check` needs a command",
            )
            return

        timeout = max(5.0, float(getattr(self.options, "hook_timeout_s", DEFAULT_HOOK_TIMEOUT) or DEFAULT_HOOK_TIMEOUT))
        argv = [binary, "execpolicy", "check", "--rules", artifact["abs"], "--"]
        try:
            argv.extend(shlex.split(example))
        except ValueError:
            argv.extend(example.split())
        try:
            proc = subprocess.Popen(
                argv,
                stdout=subprocess.PIPE,
                stderr=subprocess.STDOUT,
                cwd=self.repo,
                env=minimal_env(self.repo, self.target),
                shell=False,
            )
            output, _ = proc.communicate(timeout=timeout)
            code = proc.returncode
        except OSError as exc:
            self.add("rule_policy_execpolicy", label, WARN, "could not run `codex execpolicy check`: %s" % _short(str(exc), 100))
            return
        except subprocess.TimeoutExpired:
            _terminate(proc)
            self.add("rule_policy_execpolicy", label, WARN, "`codex execpolicy check` did not finish in %.0fs" % timeout)
            return

        detail = _short((output or b"").decode("utf-8", "replace"), 160)
        if code == 0:
            self.add(
                "rule_policy_execpolicy",
                label,
                PASS,
                "`codex execpolicy check -- %s` exited 0: %s" % (_short(example, 40), detail or "accepted"),
            )
        else:
            self.add(
                "rule_policy_execpolicy",
                label,
                FAIL,
                "`codex execpolicy check -- %s` exited %s: %s. Codex will not load this file, "
                "and a file it cannot load stops every session in this repo"
                % (_short(example, 40), code, detail),
            )

    def _check_hook(self, artifact: Dict[str, Any], target: str) -> None:
        label = self.rel(target)
        command = artifact.get("command") or artifact["path"]
        resolved, note = resolve_command_path(str(command), self.repo, self.target)

        problems = []  # type: List[str]
        runnable = False
        script = resolved or target
        if not resolved or not os.path.isfile(script):
            problems.append("command does not resolve to an existing file (%s)" % _short(command, 100))
        else:
            if not os.access(script, os.X_OK):
                problems.append("script is not executable (chmod +x %s)" % self.display(script))
            else:
                runnable = True
            # A hook that shells out to a system binary (`jq`, `prettier`) has
            # no shebang of its own and needs none.
            in_repo = os.path.realpath(script).startswith(self.repo_real + os.sep)
            if in_repo:
                head, error = _read_text(script)
                if error:
                    problems.append("cannot read script: %s" % error)
                elif not head.startswith("#!"):
                    problems.append("script does not start with a shebang line")
            else:
                note = (note + "; " if note else "") + "resolves to an executable outside the repo, shebang not required"

        if note and "unresolved variable" in note:
            problems.append(note)

        if problems:
            self.add("hook_script", label, FAIL, "; ".join(problems))
            if not runnable:
                self.add(
                    "hook_smoke",
                    label,
                    WARN,
                    "smoke test not attempted: the command is missing or not executable",
                )
                return
        else:
            self.add(
                "hook_script", label, PASS, "exists, executable, shebang present%s" % (" (%s)" % note if note else "")
            )

        # --- static scan -------------------------------------------------
        # Always runs, flag or no flag.  This is the check that stands in for
        # execution on the default path, so it must be honest about what it
        # could and could not read.
        scan_clean = self._check_hook_network(artifact, label, script, str(command))
        if not scan_clean:
            self.add(
                "hook_smoke",
                label,
                WARN,
                "not executed: the static scan found a network call (see hook_static_scan)",
            )
            return

        # --- provenance ---------------------------------------------------
        # agentify smoke-tests what agentify built.  A pre-existing hook, or a
        # wrapper that lands on a binary outside the repo, is never executed.
        if not self.is_generated_by_this_run(script):
            self.add("hook_smoke", label, WARN, "not executed: hook not generated by this run")
            return

        if not self.exec_enabled:
            self.add(
                "hook_smoke",
                label,
                WARN,
                "not executed: hook execution is opt-in; static checks only. Ask the user, then "
                "rerun with --exec-hooks to smoke-test it",
            )
            return

        timeout = float(getattr(self.options, "hook_timeout_s", DEFAULT_HOOK_TIMEOUT) or DEFAULT_HOOK_TIMEOUT)
        fixture = self._ensure_fixture()
        result = run_hook(str(command), self.repo, timeout, fixture, self.target)

        if result["error"]:
            self.add("hook_smoke", label, FAIL, "could not run the hook: %s" % _safe_detail(result["error"]))
            return
        if result["timeout"]:
            self.add(
                "hook_smoke",
                label,
                FAIL,
                "hook did not exit within %.1fs on empty input; it would hang the session" % timeout,
            )
            return
        if result["code"] != 0:
            # WARN, not FAIL, and the reason matters: the hook ran in an EMPTY
            # scratch fixture with no repo around it, so a non-zero exit may be
            # the sandbox rather than the hook ("no package.json", "nothing to
            # check").  The authoritative behavioural test is verification.md
            # section 5, which runs the hook against a populated fixture.
            stderr = _safe_detail(result["stderr"], 140)
            self.add(
                "hook_smoke",
                label,
                WARN,
                "exit %s on empty JSON input in an empty scratch fixture; a hook must fail open, but "
                "confirm with the section 5 fixture test before removing it%s"
                % (result["code"], (" -- stderr: %s" % stderr) if stderr else ""),
            )
            return
        self.add(
            "hook_smoke",
            label,
            PASS,
            "exit 0 on empty JSON input within %.1fs (minimal env, cwd in a scratch fixture%s)"
            % (timeout, ", via /bin/sh -c" if result.get("shell") else ""),
        )

    def _check_hook_network(
        self, artifact: Dict[str, Any], label: str, script: str, command: str
    ) -> bool:
        """
        Static network scan over the hook script AND its registered command
        line.  Returns True when the hook is clear to execute.

        A hit is a FAIL naming the offending line: a hook that phones home
        breaks the tool's only unconditional promise (PRD 13, local only), and
        agentify must never run it to find out what it does.
        """
        sources = []  # type: List[Tuple[str, str]]
        unread = ""

        if command and command.strip() and os.path.basename(str(command).strip()) != os.path.basename(script or ""):
            sources.append(("command line", str(command)))

        if script and os.path.isfile(script):
            if self.inside_repo(script):
                text, error = _read_text(script)
                if error:
                    unread = "script could not be read (%s)" % _short(error, 80)
                else:
                    sources.append(("script", text))
            else:
                unread = "script lives outside the repo and was not scanned"
        elif not sources:
            unread = "nothing to scan: the command did not resolve to a file"

        hard = []  # type: List[Dict[str, Any]]
        soft = []  # type: List[Dict[str, Any]]
        for origin, text in sources:
            found_hard, found_soft = scan_network_calls(text)
            for hit in found_hard:
                hit["origin"] = origin
                hard.append(hit)
            for hit in found_soft:
                hit["origin"] = origin
                soft.append(hit)

        if hard:
            detail = "; ".join(
                "%s line %d: %s -- %s" % (hit["origin"], hit["line"], hit["kind"], _safe_detail(hit["text"], 90))
                for hit in hard[:3]
            )
            self.add(
                "hook_static_scan",
                label,
                FAIL,
                "network call in a generated hook (%s): %s. agentify is local-only; rewrite the "
                "hook without it or remove the hook" % (artifact["id"], detail),
            )
            return False

        if unread:
            self.add("hook_static_scan", label, WARN, "%s; treat it as unproven" % unread)
            return True

        if soft:
            hit = soft[0]
            self.add(
                "hook_static_scan",
                label,
                WARN,
                "no network call, but %s at %s line %d: %s"
                % (hit["kind"], hit["origin"], hit["line"], _safe_detail(hit["text"], 90)),
            )
            return True

        self.add(
            "hook_static_scan",
            label,
            PASS,
            "no curl/wget/nc/ssh, no http client, no package install or remote git call",
        )
        return True

    # -- repo level -------------------------------------------------------

    def _locate(self, relative: str, types: Sequence[str]) -> Optional[str]:
        for artifact in self.artifacts:
            if artifact.get("abs") and artifact["type"] in types:
                return artifact["abs"]
        for artifact in self.artifacts:
            if artifact.get("abs") and artifact["path"].replace("\\", "/").endswith(relative):
                return artifact["abs"]
        candidate = os.path.join(self.repo, relative)
        if os.path.isfile(candidate):
            return candidate
        return None

    # -- the core set -----------------------------------------------------

    _CORE_DB_SERVICES = frozenset([
        "postgres", "neon", "supabase", "planetscale", "mongodb", "redis", "drizzle",
        "prisma", "mysql", "sqlite",
    ])
    _CORE_DB_FRAMEWORKS = frozenset(["Drizzle ORM", "Prisma", "SQLAlchemy", "TypeORM", "Sequelize", "Kysely", "Mongoose"])
    _CORE_WEB_FRAMEWORKS = frozenset([
        "Next.js", "Nuxt", "Remix", "Astro", "Svelte", "SvelteKit", "Angular", "Vite",
        "Django", "Laravel", "Ruby on Rails", "Expo", "React Native", "Vue", "React",
    ])
    _CORE_ANALYTICS = frozenset(["posthog", "mixpanel", "amplitude", "segment"])

    def _existing_skill_dir(self, name: str) -> bool:
        """True when the repo already carries a skill of this name under either
        skills root -- the user's own, which blueprint.md 2.1 lets cover the
        candidate, so its absence from the manifest is not a gap."""
        for root in (".claude/skills", ".agents/skills"):
            if os.path.isfile(os.path.join(self.repo, root, name, "SKILL.md")):
                return True
        return False

    def _check_core_set(self) -> None:
        """
        blueprint.md 1.3: the artifacts every setup has when their licence
        holds.  Measured 2026-09-07 on a 268k-line repo with eight services:
        the run built two skills and no reviewer, designer or analyst, and
        nothing in phase 8 noticed, because every row was about a file that
        existed and none was about a file that should have.  WARN only -- the
        user may have dropped an item at the gate, and that is their call --
        but a warn the report has to carry is what makes the gap visible.
        """
        def labels(kind: str) -> List[str]:
            out = []
            for artifact in self.artifacts:
                if artifact.get("type") != kind:
                    continue
                out.append(" ".join(
                    str(artifact.get(key) or "") for key in ("id", "name", "path")
                ).lower())
            return out

        skills = labels("skill")
        agents = labels("subagent")
        hooks = labels("hook")
        gaps = []  # type: List[str]
        found = []  # type: List[str]

        if not skills:
            gaps.append("zero skills -- a run that builds none has almost certainly failed the "
                        "catalogue walk (blueprint.md 6)")  # kept long: it is the whole finding
        else:
            found.append("%d skill(s)" % len(skills))
        if any("setup-manager" in label for label in skills):
            found.append("setup-manager")
        else:
            gaps.append("no `setup-manager` skill -- it is unconditional (blueprint.md 6.3)")
        if any("review" in label for label in agents):
            found.append("a reviewer subagent")
        elif any(
            os.path.isfile(os.path.join(self.repo, ".claude", "agents", candidate))
            for candidate in ("pr-reviewer.md", "code-reviewer.md", "diff-reviewer.md")
        ):
            found.append("a reviewer subagent the repo already had")
        else:
            gaps.append("no reviewer subagent (`pr-reviewer`) -- licensed by any git repo "
                        "(blueprint.md 1.3)")

        discovery = self.discovery
        if discovery:
            services = set(
                str(row.get("name") or "").lower()
                for row in (discovery.get("external_services") or [])
                if isinstance(row, dict)
            )
            frameworks = set(
                str(row.get("name") or "")
                for row in (discovery.get("frameworks") or [])
                if isinstance(row, dict)
            )
            env_names = [str(n) for n in (discovery.get("env_var_names") or []) if n]
            if (services & self._CORE_DB_SERVICES) or (frameworks & self._CORE_DB_FRAMEWORKS):
                if any("db-" in label or "database" in label for label in agents):
                    found.append("a db subagent")
                else:
                    gaps.append(
                        "no `db-inspector` subagent, though discovery has %s"
                        % ", ".join(sorted((services & self._CORE_DB_SERVICES)
                                           | (frameworks & self._CORE_DB_FRAMEWORKS))[:3])
                    )
            if frameworks & self._CORE_WEB_FRAMEWORKS:
                if any(re.search(r"(^|[^a-z])qa([^a-z]|$)", label) for label in skills):
                    found.append("a qa skill")
                elif self._existing_skill_dir("qa"):
                    found.append("a qa skill the repo already had")
                else:
                    gaps.append("no `qa` skill, though discovery has %s"
                                % ", ".join(sorted(frameworks & self._CORE_WEB_FRAMEWORKS)[:2]))
            if services & self._CORE_ANALYTICS:
                if any("analytics" in label or "product" in label for label in skills + agents):
                    found.append("an analytics artifact")
                else:
                    gaps.append("no `product-analyst` / `add-product-analytics` / `ask-product`, "
                                "though discovery has %s"
                                % ", ".join(sorted(services & self._CORE_ANALYTICS)))
            if env_names:
                if any("env" in label or "secret" in label for label in hooks):
                    found.append("an env-leak hook")
                else:
                    gaps.append("no env-leak hook, though env_var_names holds %d name(s)"
                                % len(env_names))

        if gaps:
            self.add(
                "core_set", "manifest", WARN,
                "; ".join(gaps[:5]) + " -- blueprint.md 1.3: dropped at the gate is fine, never "
                "proposed is not",
            )
            return
        self.add(
            "core_set", "manifest", PASS,
            "the core set is present: %s%s"
            % (", ".join(found), "" if discovery else
               " (no --discovery, so the licence-gated items were not checked)"),
        )

    def _check_settings_json(self) -> None:
        """
        The target's own hook registry: `.claude/settings.json` on Claude Code,
        `.codex/hooks.json` on Codex.  The path comes from the profile, so this
        reads whichever file the build actually wrote.
        """
        path = self._locate(self.profile["primary_registry"], ["settings"])
        if not path:
            return
        label = self.rel(path)

        text, error = _read_text(path)
        if error:
            self.add("settings_json", label, FAIL, "cannot read: %s" % error)
            return
        try:
            parsed = json.loads(text)
        except ValueError as exc:
            self.add("settings_json", label, FAIL, "invalid JSON: %s" % exc)
            return
        if not isinstance(parsed, dict):
            self.add("settings_json", label, FAIL, "top level is not a JSON object")
            return

        # Codex's `hooks.json` accepts exactly `description` and `hooks`.  An
        # unknown top-level key is not ignored: the file is rejected and loads
        # ZERO hooks, reported only as a `hooks/list` warning the user never
        # sees (MEASURED -- adapters/codex.md 4.3, "Idempotency without
        # markers").  It is the single easiest way to silently disable every
        # hook in a repo, so it is a FAIL here rather than a surprise later.
        allowed = self.profile["registry_allowed_keys"]
        if allowed is not None:
            unknown = [key for key in parsed.keys() if key not in allowed]
            if unknown:
                self.add(
                    "settings_json",
                    label,
                    FAIL,
                    "unknown top-level key(s) %s: %s accepts only %s, and one unknown key makes it "
                    "reject the WHOLE file and load zero hooks -- silently. Remove them (agentify "
                    "writes no metadata key here; provenance lives in the hook script header and "
                    "the build manifest)"
                    % (
                        ", ".join(repr(_short(key, 40)) for key in sorted(unknown)[:4]),
                        os.path.basename(label),
                        " and ".join(repr(key) for key in sorted(allowed)),
                    ),
                )
                return

        commands = _settings_hook_commands(parsed)
        self.add(
            "settings_json",
            label,
            PASS,
            "valid JSON; %d hook command(s) registered" % len(commands),
        )

        for event, command in commands:
            resolved, note = resolve_command_path(command, self.repo, self.target)
            display = "%s: %s" % (event, _short(command, 90))
            if resolved and note == "resolved via PATH":
                self.add("settings_hook_command", label, PASS, "%s -> %s (on PATH)" % (display, resolved))
            elif resolved and os.path.isfile(resolved):
                if not os.access(resolved, os.X_OK):
                    self.add(
                        "settings_hook_command",
                        label,
                        FAIL,
                        "%s -> %s exists but is not executable (chmod +x)" % (display, self.display(resolved)),
                    )
                else:
                    self.add("settings_hook_command", label, PASS, "%s -> %s" % (display, self.display(resolved)))
            elif "unresolved variable" in note:
                self.add(
                    "settings_hook_command",
                    label,
                    WARN,
                    "%s -- contains a variable this checker cannot expand" % display,
                )
            else:
                self.add(
                    "settings_hook_command",
                    label,
                    FAIL,
                    "%s -- does not resolve to an existing file" % display,
                )

    def _check_committed_clean(self) -> None:
        """
        A path the manifest calls committed really is committed, byte for byte.

        `undo_partition` proves every artifact is in one of the two lists;
        nothing proved the CONTENT of a `committed_paths` entry matches what the
        branch holds.  The gap is the undo bug class again, in its quietest
        form: the branch delete restores the committed bytes, so an edit made
        after the commit is discarded by the very step the report calls a clean
        removal, and the tree diff a user takes afterwards comes back empty
        because the file is back to a version that once existed.

        agentify's own late output is exempt by design, not by accident:
        `verification.md` §9 has phase 8 write `report.md` and re-write the
        manifest AFTER this check runs, so those two are legitimately dirty
        here and are reported at WARN.  Everything else is a FAIL.
        """
        committed = self.manifest.get("committed_paths")
        if not isinstance(committed, list) or not committed:
            return
        usable, why = self._git_usable()
        if not usable:
            self.add("undo_committed_clean", "the run", WARN, "not checked: %s" % why)
            return

        # Written after this check by design -- see the docstring.
        late = set()
        for artifact in self.artifacts:
            if artifact["type"] in ("report", "manifest") and artifact.get("path"):
                late.add(_repo_relative(artifact["path"]))

        dirty = []  # type: List[str]
        dirty_late = []  # type: List[str]
        for entry in committed:
            path = _repo_relative(entry)
            if not path:
                continue
            worktree_ok, worktree, _ = self._git_read(["diff", "--name-only", "--", path])
            index_ok, index, _ = self._git_read(["diff", "--cached", "--name-only", "--", path])
            if not (worktree_ok and index_ok):
                continue
            if str(worktree).strip() or str(index).strip():
                (dirty_late if path in late else dirty).append(path)

        if dirty:
            self.add(
                "undo_committed_clean",
                "the run",
                FAIL,
                "%d path(s) listed in `committed_paths` differ from what the branch holds, so the "
                "branch delete would silently discard the difference -- commit them or move them "
                "to `uncommitted_paths`: %s" % (len(dirty), ", ".join(dirty[:4])),
            )
        elif dirty_late:
            self.add(
                "undo_committed_clean",
                "the run",
                WARN,
                "%d of agentify's own file(s) not committed yet, which is the documented order "
                "(verification.md §9 commits them after this check): %s"
                % (len(dirty_late), ", ".join(sorted(dirty_late)[:4])),
            )
        else:
            self.add(
                "undo_committed_clean",
                "the run",
                PASS,
                "all %d committed path(s) match the branch" % len(committed),
            )

    def _check_plugin_paths(self) -> None:
        """
        Every path-valued key in a plugin manifest resolves on disk.

        Both plugin templates carry path keys -- Codex's `skills` (and `apps`,
        seen in a real bundled manifest) and the Claude manifest's component
        directories -- and both resolve against the PLUGIN ROOT, which is the
        manifest's grandparent: `<plugin>/.codex-plugin/plugin.json` describes
        `<plugin>/skills/`, not `<plugin>/.codex-plugin/skills/`.

        The manifest is written by a step AFTER the copy that populates those
        directories, so skipping the copy leaves a manifest that parses cleanly
        and points at nothing.  `codex-plugin.json.tmpl` already tells the model
        this check exists and fails such a manifest -- it did not, which made the
        guidance false and let a dangling plugin ship silently.  FAIL, because a
        manifest whose paths do not resolve is a plugin that does not install.
        """
        manifests = [a for a in self.artifacts if a["type"] == "plugin" and a.get("abs")]
        if not manifests:
            return

        for artifact in manifests:
            label = artifact.get("path") or self.rel(artifact["abs"])
            text, error = _read_text(artifact["abs"])
            if error:
                self.add("plugin_paths", label, FAIL, "unreadable: %s" % error)
                continue
            try:
                data = json.loads(text)
            except ValueError as exc:
                # `markers`/`metadata` already report a malformed manifest; this
                # check has nothing to say about one it cannot parse.
                self.add("plugin_paths", label, WARN, "not valid JSON, paths not checked: %s" % exc)
                continue
            if not isinstance(data, dict):
                self.add("plugin_paths", label, WARN, "top level is not an object; paths not checked")
                continue

            # The plugin root is the manifest's grandparent when it sits in a
            # `.*-plugin/` directory, and its own directory otherwise.
            manifest_dir = os.path.dirname(artifact["abs"])
            root = manifest_dir
            if os.path.basename(manifest_dir).endswith("-plugin"):
                root = os.path.dirname(manifest_dir)

            checked = []  # type: List[str]
            dangling = []  # type: List[str]
            for key, value in sorted(data.items()):
                if key.startswith("_") or not isinstance(value, str):
                    continue
                if not (value.startswith("./") or value.startswith("../")):
                    continue
                checked.append("%s=%s" % (key, value))
                if not os.path.exists(os.path.join(root, value)):
                    dangling.append("`%s`: %s" % (key, value))

            if dangling:
                self.add(
                    "plugin_paths",
                    label,
                    FAIL,
                    "%d path key(s) resolve to nothing under %s -- the packaging copy did not run, "
                    "or the key should have been deleted: %s"
                    % (len(dangling), self.rel(root) or ".", "; ".join(dangling[:4])),
                )
            elif checked:
                self.add(
                    "plugin_paths",
                    label,
                    PASS,
                    "%d path key(s) resolve under %s: %s"
                    % (len(checked), self.rel(root) or ".", ", ".join(checked[:4])),
                )
            else:
                self.add("plugin_paths", label, PASS, "no path-valued keys to resolve")

    def _check_mcp_json(self) -> None:
        """
        The MCP config, read in the FORMAT the target actually uses.

        Claude Code: `.mcp.json`, JSON, `mcpServers`.  Codex: TOML
        `[mcp_servers.<name>]` tables -- drafted to `<plan-dir>/codex-mcp.toml`
        by default, appended into `<repo>/.codex/config.toml` only on an
        explicit opt-in (adapters/codex.md 4.6).  They are not interchangeable
        and never were, so `json.loads` on the Codex artifact FAILED a correct
        draft with "invalid JSON: Expecting value: line 1 column 1" -- MEASURED,
        the same false-FAIL defect as `rule_scope` on a command policy.  The
        secret scan runs either way: it reads raw text, and that half was never
        format-dependent.
        """
        path = self._locate(".mcp.json", ["mcp"])
        if not path:
            return
        label = self.rel(path)

        text, error = _read_text(path)
        if error:
            self.add("mcp_json", label, FAIL, "cannot read: %s" % error)
            return

        if not _is_json_path(path):
            self._check_mcp_toml(label, text)
            return

        try:
            parsed = json.loads(text)
        except ValueError as exc:
            self.add("mcp_json", label, FAIL, "invalid JSON: %s" % exc)
            self._check_mcp_secrets(label, None, text)
            return

        servers = parsed.get("mcpServers") if isinstance(parsed, dict) else None
        count = len(servers) if isinstance(servers, dict) else 0
        self.add("mcp_json", label, PASS, "valid JSON; %d server(s) declared" % count)
        self._check_mcp_secrets(label, parsed, text)

    def _check_mcp_toml(self, label: str, text: str) -> None:
        """
        A Codex MCP config: complete `[mcp_servers.<name>]` table blocks.

        Checked for the two things that are checkable without a TOML writer and
        that decide whether the block works when the user pastes it:
        at least one server table is declared, and every top-level key sits
        UNDER a table header.  The second is the silent trap adapters/codex.md
        4.6 measured -- a bare key/value pair binds to whatever table precedes
        it, the file loads without complaint, and the setting has no effect.
        """
        servers = re.findall(r"(?m)^[ \t]*\[[ \t]*mcp_servers\.([A-Za-z0-9_.:@/-]+)[ \t]*\]", text or "")
        names = []  # type: List[str]
        for name in servers:
            head = name.split(".")[0]
            if head not in names:
                names.append(head)

        stray = []  # type: List[str]
        seen_table = False
        for line in (text or "").split("\n")[:400]:
            stripped = line.strip()
            if not stripped or stripped.startswith("#"):
                continue
            if stripped.startswith("["):
                seen_table = True
                continue
            if not seen_table and _TOML_ASSIGN.match(stripped):
                stray.append(stripped.split("=")[0].strip())

        if not names:
            self.add(
                "mcp_json",
                label,
                FAIL,
                "no `[mcp_servers.<name>]` table: this is the Codex MCP format and the file "
                "declares no server. A `mcpServers` JSON object configures nothing on Codex "
                "(adapters/codex.md 4.6)",
            )
        elif stray:
            self.add(
                "mcp_json",
                label,
                WARN,
                "%d server table(s) (%s), but %s sit(s) above the first `[table]` header. "
                "MEASURED: a bare key/value pair binds to whatever table precedes it once "
                "pasted into config.toml -- the file loads and the setting has no effect"
                % (len(names), ", ".join(names[:4]), ", ".join(stray[:3])),
            )
        else:
            self.add(
                "mcp_json",
                label,
                PASS,
                "Codex TOML: %d complete `[mcp_servers.*]` table block(s): %s"
                % (len(names), ", ".join(names[:6])),
            )
        self._check_mcp_secrets(label, None, text)

    def _check_mcp_secrets(self, label: str, parsed: Any, text: str) -> None:
        hits = scan_json_secrets(parsed) if parsed is not None else []
        raw_kinds = scan_text_secrets(text)

        kinds = sorted(set([hit["kind"] for hit in hits] + raw_kinds))
        if not kinds:
            self.add(
                "mcp_secrets",
                label,
                PASS,
                "no literal credentials; values are placeholders or references the user fills in",
            )
            return

        pointers = sorted(set(hit["pointer"] for hit in hits))[:4]
        self.add(
            "mcp_secrets",
            label,
            FAIL,
            "literal secret material in a committed config: %s%s -- replace with ${ENV_VAR} and rotate the key"
            % (", ".join(kinds), (" at %s" % ", ".join(pointers)) if pointers else ""),
        )

    def _check_rule_contradictions(self) -> None:
        # `rule_body` is only ever set on the PROSE path, so a Codex command
        # policy is already outside this list -- named here so it stays that
        # way.  Starlark is not prose: `decision = "forbidden"` read as English
        # would produce directives out of a syntax the clause reader has never
        # seen.  A policy's own consistency is `rule_policy_*`'s job.
        rules = [
            a
            for a in self.artifacts
            if a["type"] == "rule"
            and a.get("rule_body")
            and a.get("rule_subtype", RULE_SUBTYPE_PROSE) == RULE_SUBTYPE_PROSE
        ]
        policies = [
            a for a in self.artifacts if a.get("rule_subtype") == RULE_SUBTYPE_POLICY
        ]
        if not rules:
            if policies:
                self.add(
                    "rule_contradiction",
                    "rules",
                    PASS,
                    "no prose rule to read; %d Codex command policy artifact(s) are Starlark "
                    "and are checked by `rule_policy_*` instead" % len(policies),
                )
            return
        directives = []  # type: List[Dict[str, Any]]
        bodies = {}  # type: Dict[str, str]
        for rule in rules:
            bodies[rule["id"]] = rule["rule_body"]
            directives.extend(
                extract_directives(rule["id"], rule["rule_body"], rule.get("rule_globs"))
            )

        contradictions = find_contradictions(directives, bodies)
        contradictions.extend(find_convention_conflicts(directives, self.conventions, bodies))

        if not contradictions:
            if self.conventions:
                against = "and none conflicts with the %d discovered convention(s) in %s" % (
                    len(self.conventions),
                    _short(self.conventions_label or "discovery.json", 60),
                )
            else:
                # Never claim coverage the run did not have: PRD 7.9 asks for
                # rules to be checked against discovered conventions too, and
                # without --discovery that half simply did not happen.
                against = (
                    "conventions NOT checked -- pass --discovery <discovery.json> to compare "
                    "rules against what the repo actually does"
                )
            self.add(
                "rule_contradiction",
                "rules",
                PASS,
                "%d directive(s) across %d prose rule(s)%s; no opposing pair, no "
                "exclusive-choice collision, %s"
                % (
                    len(directives),
                    len(rules),
                    (" (%d Starlark command polic%s read by `rule_policy_*` instead)"
                     % (len(policies), "y" if len(policies) == 1 else "ies")) if policies else "",
                    against,
                ),
            )
            return
        for item in contradictions:
            more = item.get("more")
            # A rule against a HARD discovered fact is a FAIL, not a warn.
            # verification.md section 6's own Fail example is exactly this --
            # "a rule saying 'use npm' in a repo with bun.lockb and
            # packageManager: bun" -- and the remedy it prescribes ("the repo
            # wins; rewrite the rule to match, or delete it") is the fix-or-
            # remove loop that only a fail triggers.  The other two kinds stay
            # WARN: they are one piece of generated prose read against another,
            # where the checker is guessing at meaning.  This one is generated
            # prose against a machine-extracted fact about the repo, and a
            # clash with a soft source (a `frameworks` / `languages` name scan)
            # still only warns -- see conventions_from_discovery.
            if item["kind"] == "contradicts-convention" and item.get("hard"):
                status = FAIL
                tail = (
                    ". The repo wins: reword the rule to match, word it as intent "
                    '("we are moving to X"), or delete it (verification.md section 6)'
                )
            else:
                status = WARN
                tail = " (best-effort; confirm by hand)"
            self.add(
                "rule_contradiction",
                "%s vs %s" % (item["left_rule"], item["right_rule"]),
                status,
                "%s on '%s': \"%s\" vs \"%s\"%s%s"
                % (
                    item["kind"],
                    item["subject"],
                    _short(item["left"], 70),
                    _short(item["right"], 70),
                    (" (+%s more between the same rules)" % more) if more else "",
                    tail,
                ),
            )

    # -- rule wiring ------------------------------------------------------

    def _index_doc_texts(self) -> Tuple[List[Tuple[str, str]], List[str]]:
        """
        Every index doc this run can be judged against, as `(label, text)`,
        plus the labels of any that exist but could not be read.

        Prefers the `index-doc` artifacts the manifest names.  Falls back to
        `CLAUDE.md` / `AGENTS.md` at the repo root, which is the rerun case: a
        run that only adds a rule to an index doc that was already wired does
        not list the index doc as an artifact, and its rules are still loaded.
        """
        docs = []  # type: List[Tuple[str, str]]
        unreadable = []  # type: List[str]
        seen = set()  # type: set

        for artifact in self.artifacts:
            if artifact["type"] != "index-doc" or not artifact.get("abs"):
                continue
            real = os.path.realpath(artifact["abs"])
            if real in seen:
                continue
            seen.add(real)
            text = artifact.get("text")
            if text is None:
                text, error = _read_text(artifact["abs"])
                if error:
                    if os.path.isfile(artifact["abs"]):
                        unreadable.append(self.rel(artifact["abs"]))
                    continue
            docs.append((self.rel(artifact["abs"]), text))

        if docs:
            return (docs, unreadable)

        for name in ("CLAUDE.md", "AGENTS.md"):
            candidate = os.path.join(self.repo, name)
            if not os.path.isfile(candidate):
                continue
            real = os.path.realpath(candidate)
            if real in seen:
                continue
            seen.add(real)
            text, error = _read_text(candidate)
            if error:
                unreadable.append(name)
                continue
            docs.append((name, text))
        return (docs, unreadable)

    def _check_rule_wired(self) -> None:
        """
        A generated PROSE rule must be referenced from the index doc, or
        nothing loads it.

        NOT a Codex command policy.  `.codex/rules/*.rules` IS a native load
        path -- Codex reads the directory itself, gated only on the project
        being trusted -- so demanding an `AGENTS.md` pointer for one FAILED a
        correct artifact on the 2026-09-05 dogfood and told phase 8 to delete
        it.  Subtype first, then the prose check.

        A PROSE rules directory is a repo convention, not a load path: Claude Code
        reads `CLAUDE.md` and does not walk `.claude/rules/`, and Codex reads
        `AGENTS.md` and does not walk its rules directory either.  Same shape,
        different paths -- which is why the directory named in the message is
        the rule's OWN directory, taken from the artifact, and never a
        hardcoded `.claude/rules/`.  Both adapters say so in as many words and
        both make an unreferenced rule a FAIL --
        `adapters/claude-code.md` section 4.2 calls it "a dead file that cost
        the user context budget and bought nothing", and both spell the check
        as `grep -F "<name>.md" "$REPO/CLAUDE.md"`.  This is that grep, run for
        real: the file's basename must appear somewhere in an index doc.

        Deliberately a plain whole-file search rather than a search inside the
        agentify marker block.  A rule the user wired by hand, in their own
        prose, is wired -- failing it would be a false positive, and a false
        positive here gets a good rule deleted.
        """
        for policy in self.artifacts:
            if policy.get("rule_subtype") != RULE_SUBTYPE_POLICY or not policy.get("abs"):
                continue
            self.add(
                "rule_wired",
                self.rel(policy["abs"]),
                PASS,
                "wiring not required: %s is a NATIVE Codex load path -- Codex reads the "
                "directory itself and nothing needs to point at it. Inert until the project "
                "is trusted (`[projects.\"<abs path>\"] trust_level = \"trusted\"`), which "
                "belongs in the plan's capability notes, not in this check"
                % (os.path.dirname(self.rel(policy["abs"]).replace(os.sep, "/")) or ".codex/rules"),
            )

        rules = [
            a
            for a in self.artifacts
            if a["type"] == "rule"
            and a.get("abs")
            and a.get("rule_subtype", RULE_SUBTYPE_PROSE) == RULE_SUBTYPE_PROSE
        ]
        if not rules:
            return

        docs, unreadable = self._index_doc_texts()

        for rule in rules:
            label = self.rel(rule["abs"])
            relative = self.rel(rule["abs"]).replace(os.sep, "/")
            needle = os.path.basename(relative)
            holder = os.path.dirname(relative) or self.profile["rules_dir"]

            if not docs:
                # An index doc that is on disk but unreadable (too large, bad
                # permissions) is not evidence that the rule is unwired, and
                # deleting a good rule on that basis would be worse than the
                # gap.  Say what could not be read instead.
                if unreadable:
                    self.add(
                        "rule_wired",
                        label,
                        WARN,
                        "could not read %s, so the wiring could not be checked; confirm by "
                        "hand that the index doc points at this rule"
                        % ", ".join(unreadable[:3]),
                    )
                    continue
                self.add(
                    "rule_wired",
                    label,
                    FAIL,
                    "no index doc (CLAUDE.md / AGENTS.md) was built or found, so nothing "
                    "points at this rule; `%s/` is a repo convention, not a load "
                    "path, and an unreferenced rule is a dead file (adapters section 4.2)"
                    % holder,
                )
                continue

            found = ""
            eager = False
            for doc_label, text in docs:
                if not needle or (needle not in text and relative not in text):
                    continue
                found = doc_label
                for line in text.split("\n"):
                    stripped = line.strip()
                    if stripped.startswith("@") and (needle in stripped or relative in stripped):
                        eager = True
                        break
                break

            if not found:
                self.add(
                    "rule_wired",
                    label,
                    FAIL,
                    "not referenced from %s; `%s/` is a repo convention, not a "
                    "%s load path, so an unreferenced rule is a dead file that costs "
                    "nothing to read and does nothing (adapters section 4.2). Add a row for it "
                    "to the index doc's Rules table, or remove the rule"
                    % (
                        " or ".join(doc_label for doc_label, _ in docs[:3]),
                        holder,
                        self.profile["label"],
                    ),
                )
                continue

            self.add(
                "rule_wired",
                label,
                PASS,
                "referenced from %s (%s)"
                % (found, "eager @import" if eager else "index table / link"),
            )

    # -- hooks, the other direction ---------------------------------------

    def _git_hook_dirs(self) -> Tuple[str, List[str], str]:
        """
        `(directory git actually runs hooks from, directories it ignores, note)`.

        `core.hooksPath` wins wherever it is set -- husky, lefthook and friends
        set it -- and a hook written into `.git/hooks/` while it points
        somewhere else silently never runs (`adapters/codex.md` 4.3 rule 5).
        Read out of `.git/config` as text, section by section: this lookup runs
        no git subprocess (`_git_read`, which `uninstall` uses, is the only
        place that does), and a one-line INI read cannot fail in a way that
        matters.  **Only `[core] hooksPath` is taken from that file.**  A
        `.git/config` can carry a remote URL with a token embedded in it, so no
        other line is retained, matched on, or emitted anywhere.
        """
        gitdir = os.path.join(self.repo, ".git")
        if os.path.isfile(gitdir):  # a worktree or submodule: `.git` is a pointer file
            text, error = _read_text(gitdir)
            if not error:
                for line in text.splitlines():
                    if line.strip().lower().startswith("gitdir:"):
                        pointed = line.split(":", 1)[1].strip()
                        if not os.path.isabs(pointed):
                            pointed = os.path.join(self.repo, pointed)
                        gitdir = os.path.normpath(pointed)
                        break
        if not os.path.isdir(gitdir):
            return ("", [], "")

        default_dir = os.path.join(gitdir, "hooks")
        configured = ""
        config_path = os.path.join(gitdir, "config")
        if os.path.isfile(config_path):
            text, error = _read_text(config_path)
            if not error:
                section = ""
                for line in text.splitlines():
                    stripped = line.strip()
                    if stripped.startswith("[") and stripped.endswith("]"):
                        section = stripped[1:-1].strip().split(None, 1)[0].lower()
                        continue
                    if section != "core":
                        continue
                    match = _HOOKS_PATH_RE.match(line)
                    if match:
                        configured = match.group(1).strip().strip("\"'")
                        break

        if not configured:
            return (default_dir, [], "")

        path = os.path.expanduser(configured)
        if not os.path.isabs(path):
            path = os.path.join(self.repo, path)
        return (os.path.normpath(path), [default_dir], "core.hooksPath = %s" % _short(configured, 60))

    def _hook_registration_sources(
        self,
    ) -> Tuple[List[Tuple[str, str, str]], List[str], List[str], List[str]]:
        """
        Every hook command registered anywhere this run can see, as
        `(source label, command, scope)`, plus the files searched, the files
        that exist but could not be read or parsed, and the candidate
        registries that are simply not on disk -- the last one so a failure can
        say what it looked at as well as what it read.

        The registry files come from the TARGET PROFILE, never from a constant
        in this method: `.claude/settings.json`, `settings.local.json` and a
        plugin manifest on Claude Code; `.codex/hooks.json` on Codex.  All of
        them carry the same three-level `hooks` shape, so one reader covers
        every one of them.

        Prefers the `settings` and `plugin` artifacts the manifest names, then
        the target's project-scoped files on disk -- the rerun case, where a run
        adds a hook to a registry it did not itself create -- and last the
        target's USER-scoped registry
        (`${CLAUDE_CONFIG_DIR:-~/.claude}/settings.json`,
        `${CODEX_HOME:-~/.codex}/hooks.json`), resolved through the env var and
        never a hardcoded `~/.claude` or `~/.codex`.  agentify never writes a
        user-scoped registry -- a global hook fires in every repo the user opens
        -- but a hook the user wired there by hand really does run, and a
        registration that exists must not be reported as a dead file.
        """
        commands = []  # type: List[Tuple[str, str, str]]
        searched = []  # type: List[str]
        unreadable = []  # type: List[str]
        absent = []  # type: List[str]
        seen = set()  # type: set

        candidates = []  # type: List[Tuple[str, str, str]]
        for artifact in self.artifacts:
            if artifact["type"] in ("settings", "plugin") and artifact.get("abs"):
                candidates.append((self.rel(artifact["abs"]), artifact["abs"], "project"))
        for relative in self.profile["hook_registries"]:
            candidates.append((relative, os.path.join(self.repo, relative), "project"))
        for path in self._user_registry_paths():
            candidates.append((self.display(path), path, "user"))

        for label, path, scope in candidates:
            if not path or not os.path.isfile(path):
                if label not in absent:
                    absent.append(label)
                continue
            real = os.path.realpath(path)
            if real in seen:
                continue
            seen.add(real)
            searched.append(label)
            text, error = _read_text(path)
            if error:
                unreadable.append(label)
                continue
            try:
                parsed = json.loads(text)
            except ValueError:
                unreadable.append(label)
                continue
            if not isinstance(parsed, dict):
                unreadable.append(label)
                continue
            for _event, command in _settings_hook_commands(parsed):
                commands.append((label, command, scope))
        return (commands, searched, unreadable, absent)

    def _user_registry_paths(self) -> List[str]:
        """
        The target's user-scoped hook registries, resolved through their own
        environment variable (`CLAUDE_CONFIG_DIR`, `CODEX_HOME`) with the
        documented default as the fallback.  Both adapters say in as many words
        never to hardcode the home directory.
        """
        paths = []  # type: List[str]
        for name, default, relative in self.profile["user_hook_registries"]:
            home = os.environ.get(name) or default
            home = os.path.expanduser(str(home).strip() or default)
            if not home:
                continue
            paths.append(os.path.join(home, relative))
        return paths

    def _check_hook_wired(self) -> None:
        """
        The reverse of `settings_hook_command`, and the reason both exist.

        `settings_hook_command` walks the commands IN `settings.json` and
        proves each one lands on a file.  Nothing proved the other direction:
        a generated hook script that was never registered is a dead file that
        does nothing, and the run reports success -- the same defect class as
        an unwired rule, arriving from the opposite side.

        TWO registrations exist, and each is checked as what it actually is:

          * a CONFIG-registered hook is named by a command in the target's own
            hook registry -- `.claude/settings.json`, `settings.local.json` or a
            plugin manifest on Claude Code, `.codex/hooks.json` on Codex, plus
            either target's user-scoped file.  Every one of them carries the
            same three-level `hooks` shape, and the profile says which apply;
          * a native git hook is registered by its NAME and its LOCATION, with
            no config file involved at all.  It is a secondary, opt-in artifact
            on either target, not a stand-in for a hook.

        There is no third case, and there is no target on which a hook artifact
        is a fail by construction.  Codex has a full hook system -- 12 events,
        regex matchers, a JSON permission-decision protocol (adapters/codex.md
        4.3, VERIFIED against codex-cli 0.152.1).  This check used to hard-FAIL
        every hook when `target: codex`, telling the model to delete a hook that
        was correctly written AND correctly registered; that branch is gone, and
        the profile table is what keeps it from coming back in another shape.

        Matching is deliberately permissive, exactly as `rule_wired` is: a
        resolved path wins, then the repo-relative path in the command text,
        then the file name.  A hook the user wired by hand still counts, and a
        false positive here deletes a working hook.  The one narrowing is a
        USER-scoped registry, where the file name alone proves nothing -- it is
        shared by every repo on the machine -- so there a path must match.
        """
        hooks = [a for a in self.artifacts if a["type"] == "hook" and a.get("abs")]
        if not hooks:
            return

        active_dir, stale_dirs, hooks_note = self._git_hook_dirs()
        commands, searched, unreadable, absent = self._hook_registration_sources()

        for hook in hooks:
            label = self.rel(hook["abs"])
            if self._check_git_hook_wired(hook, label, active_dir, stale_dirs, hooks_note):
                continue
            self._check_settings_hook_wired(hook, label, commands, searched, unreadable, absent)

    def _check_git_hook_wired(
        self, hook: Dict[str, Any], label: str, active_dir: str, stale_dirs: Sequence[str], hooks_note: str
    ) -> bool:
        """
        Judge a hook that lives in a git hooks directory, and say whether it
        was judged.  Returns False -- nothing emitted -- for a hook that is not
        in one, which is then a config-registered hook.
        """
        parent = os.path.realpath(os.path.dirname(hook["abs"]))
        active_real = os.path.realpath(active_dir) if active_dir else ""
        stale_reals = [os.path.realpath(path) for path in stale_dirs if path]
        if parent != active_real and parent not in stale_reals:
            return False

        name = os.path.basename(hook["abs"])
        base = name[: -len(SIDECAR_SUFFIX)] if name.endswith(SIDECAR_SUFFIX) else name

        if parent != active_real:
            self.add(
                "hook_wired",
                label,
                FAIL,
                "git runs hooks from %s (%s), not from %s, so this hook silently never runs. "
                "Write it into the configured directory instead (adapters/codex.md 4.3 rule 5)"
                % (self.display(active_real), hooks_note or "core.hooksPath", self.display(parent)),
            )
            return True

        if base not in GIT_HOOK_NAMES:
            self.add(
                "hook_wired",
                label,
                FAIL,
                "%r is not a git hook name, so git never runs it: a native git hook is registered "
                "by its file name alone. Rename it to one of pre-commit / commit-msg / pre-push / "
                "prepare-commit-msg (etc.), or drop the artifact" % name,
            )
            return True

        if name.endswith(SIDECAR_SUFFIX):
            self.add(
                "hook_wired",
                label,
                WARN,
                "written as a `%s` side-file because %s already existed, so git does NOT run it "
                "yet (adapters/codex.md 4.3 rule 2). Correct -- but only if the report's needs-you "
                "section carries the snippet the user merges in" % (SIDECAR_SUFFIX, base),
            )
            return True

        if not os.access(hook["abs"], os.X_OK):
            self.add(
                "hook_wired",
                label,
                WARN,
                "in %s under a name git knows, but not executable, and git skips a hook without "
                "the execute bit -- `hook_script` already failed it; `chmod +x` fixes both"
                % self.display(active_real),
            )
            return True

        self.add(
            "hook_wired",
            label,
            PASS,
            "native git hook: git runs %s from %s%s"
            % (name, self.display(active_real), " (%s)" % hooks_note if hooks_note else ""),
        )
        return True

    def _check_settings_hook_wired(
        self,
        hook: Dict[str, Any],
        label: str,
        commands: Sequence[Tuple[str, str, str]],
        searched: Sequence[str],
        unreadable: Sequence[str],
        absent: Sequence[str] = (),
    ) -> None:
        """
        Judge a config-registered hook against the target's own registries.

        `commands` carries the scope each registration came from.  A PROJECT
        registry may match on the file name, exactly as `rule_wired`'s grep
        does.  A USER registry may not: `${CODEX_HOME}/hooks.json` and
        `${CLAUDE_CONFIG_DIR}/settings.json` are shared by every repo on the
        machine, so a same-named hook in some other repo would otherwise
        "register" this one.  There a path has to match -- either the command
        resolves to this exact file, or the repo-relative path appears in it,
        which is what the portable `$(git rev-parse --show-toplevel)/...`
        spelling expands to.
        """
        needle = os.path.realpath(hook["abs"])
        relative = self.rel(hook["abs"]).replace(os.sep, "/")
        basename = os.path.basename(relative)

        for source, command, scope in commands:
            resolved, _note = resolve_command_path(command, self.repo, self.target)
            if resolved and os.path.realpath(resolved) == needle:
                self.add("hook_wired", label, PASS, "registered in %s; the command resolves to it" % source)
                return
            expanded = expand_command(command, self.repo, self.target).replace("\\", "/")
            if relative and relative in expanded:
                self.add("hook_wired", label, PASS, "registered in %s by repo-relative path" % source)
                return
            if basename and basename in expanded and scope != "user":
                self.add("hook_wired", label, PASS, "registered in %s by file name" % source)
                return

        if unreadable and not commands:
            self.add(
                "hook_wired",
                label,
                WARN,
                "could not read or parse %s, so the registration could not be checked; confirm by "
                "hand that a hook command points at this script" % _join_and(unreadable),
            )
            return

        # The whole search has to be visible in the failure.  `", ".join(x[:3])`
        # over the files that EXIST printed "no hook command in
        # .claude/settings.json" and read as if that were the only registry
        # consulted, which sent the reader looking for a bug in the one file
        # that was fine.  Name what was read, then what was looked for and not
        # found, and count anything past the first three.
        registry = self.profile["primary_registry"]
        if searched:
            where = "any of the %d registr%s read (%s)" % (
                len(searched), "y" if len(searched) == 1 else "ies", _join_and(searched)
            )
        else:
            where = "any hook registry (none of %s is on disk)" % _join_and(absent or [registry])
        also = ""
        if searched and absent:
            also = "; %s %s not on disk" % (
                _join_and(absent), "is" if len(absent) == 1 else "are"
            )
        self.add(
            "hook_wired",
            label,
            FAIL,
            "no hook command in %s points at it%s, so nothing ever runs it: %s runs the hooks it is "
            "told about in %s, never a script it finds in `%s/`. Register it (%s) or remove the "
            "script"
            % (
                where,
                also,
                self.profile["label"],
                registry,
                self.profile["hook_dir"],
                self.profile["registry_doc"],
            ),
        )

    # -- evidence ---------------------------------------------------------

    def _check_evidence_match(self, artifact: Dict[str, Any]) -> None:
        """
        The `agentify-evidence` line in the file must be the string the
        manifest carries for that artifact.

        SKILL.md phase 7: "The evidence line is the *same string* the candidate
        carried in phase 4 and the plan carried in phase 6 -- all three must
        match."  The evidence line is the whole product claim (CLAUDE.md:
        evidence-derived, not templated), so a file whose evidence has drifted
        from its manifest entry is either mis-generated or hand-edited, and
        neither is something to hand off quietly.

        Not reported when either side is missing: an empty manifest `evidence`
        is already a `manifest_entry` FAIL and a missing `agentify-evidence` is
        already a `metadata` row, and one defect should produce one row.
        """
        declared = artifact.get("evidence")
        found = (artifact.get("meta") or {}).get("agentify-evidence", "")
        if not isinstance(declared, str) or not declared.strip():
            return
        if not str(found or "").strip():
            return

        label = self.rel(artifact["abs"])
        left = _normalize_evidence(declared)
        right = _normalize_evidence(found)

        if left == right:
            self.add(
                "evidence_match",
                label,
                PASS,
                "evidence line matches the manifest entry: %s" % _safe_detail(declared, 120),
            )
            return

        # Truncation is the one benign mismatch: a long evidence string cut off
        # by a template width or a hand edit is still the same evidence.
        if len(left) >= 20 and len(right) >= 20 and (left.startswith(right) or right.startswith(left)):
            self.add(
                "evidence_match",
                label,
                WARN,
                "the file's evidence line looks like a truncation of the manifest's, not a "
                "different claim: file %r vs manifest %r"
                % (_safe_detail(found, 90), _safe_detail(declared, 90)),
            )
            return

        self.add(
            "evidence_match",
            label,
            FAIL,
            "evidence drift: the file says %r but the manifest entry says %r. The evidence "
            "line is the artifact's whole justification and phase 4, the plan and the file "
            "must all carry the same string -- restore it, or the artifact is no longer the "
            "one that was approved"
            % (_safe_detail(found, 90), _safe_detail(declared, 90)),
        )

    # -- the undo record --------------------------------------------------

    def _undo_key(self, value: Any) -> str:
        """A path in the manifest, normalized to the repo-relative form both undo lists use."""
        text = str(value or "").strip()
        if not text:
            return ""
        expanded = os.path.expanduser(text)
        joined = expanded if os.path.isabs(expanded) else os.path.join(self.repo, expanded)
        try:
            relative = os.path.relpath(os.path.abspath(joined), self.repo)
        except ValueError:  # pragma: no cover - different drive on Windows
            return text.replace("\\", "/")
        return os.path.normpath(relative).replace(os.sep, "/")

    def _check_undo_record(self) -> None:
        """
        `committed_paths` and `uncommitted_paths` must partition every artifact,
        and a gitignored artifact may only be in the second.

        Phase 8 generates the report's removal steps out of these two lists, so
        a path in neither is a file no undo removes -- the turborepo failure
        `verification.md` 10.2 exists to catch, where the branch delete printed
        `Deleted branch` and left five generated files on disk.  This is that
        enumeration, done mechanically over the manifest: `mode` alone cannot
        choose the undo, because a run is routinely half committed and half not.

        A path in `committed_paths` that `git add` would have refused is the
        same bug seen from the other end, so `ignored: true` is checked against
        the partition rather than trusted, and `action: modified` with
        `restore: span` is checked with it -- committing one of those makes
        `git checkout <base_branch>` DELETE the user's own file instead of
        restoring it (DECISIONS 2.15, measured).
        """
        committed_raw = self.manifest.get("committed_paths")
        uncommitted_raw = self.manifest.get("uncommitted_paths")
        has_record = isinstance(committed_raw, list) or isinstance(uncommitted_raw, list)
        artifacts = [a for a in self.artifacts if a.get("abs")]

        if not has_record:
            if artifacts:
                self.add(
                    "undo_partition",
                    "manifest",
                    WARN,
                    "no `committed_paths` / `uncommitted_paths` in the manifest, so which mechanism "
                    "removes each of the %d artifact(s) could not be checked -- and phase 8 cannot "
                    "generate the removal section from this manifest either (SKILL.md phase 7 step 6)"
                    % len(artifacts),
                )
            self._check_created_dirs()
            return

        committed = {}  # type: Dict[str, str]
        uncommitted = {}  # type: Dict[str, str]
        for raw_list, bucket in ((committed_raw, committed), (uncommitted_raw, uncommitted)):
            for value in raw_list if isinstance(raw_list, list) else []:
                key = self._undo_key(value)
                if key:
                    bucket[key] = str(value)

        claimed = set()  # type: set
        for artifact in artifacts:
            label = self.rel(artifact["abs"])
            key = self._undo_key(artifact["path"])
            claimed.add(key)
            in_committed = key in committed
            in_uncommitted = key in uncommitted
            ignored = artifact.get("ignored") is True
            restore = str(artifact.get("restore") or "").strip().lower()

            if in_committed and in_uncommitted:
                self.add(
                    "undo_partition",
                    label,
                    FAIL,
                    "listed in BOTH committed_paths and uncommitted_paths, so the undo tries to "
                    "remove by hand what the branch delete already took. Harmless to run, but the "
                    "commit and `ignored` disagree -- find out which is wrong",
                )
                continue
            if not in_committed and not in_uncommitted:
                self.add(
                    "undo_partition",
                    label,
                    FAIL,
                    "in neither committed_paths nor uncommitted_paths, so no removal mechanism "
                    "names it and this file survives the undo (verification.md 10.2). Put it in "
                    "the list that matches what phase 7's `git show --name-only` actually proved",
                )
                continue
            if ignored and in_committed:
                self.add(
                    "undo_partition",
                    label,
                    FAIL,
                    "`ignored: true` (%s) but listed in committed_paths -- `git add` refuses an "
                    "ignored path, so the branch never held it and the branch delete does not "
                    "remove it. Move it to uncommitted_paths and give it an explicit removal step"
                    % _short(artifact.get("ignored_by") or "no ignored_by recorded", 80),
                )
                continue
            if in_committed and artifact["action"] == "modified" and restore == "span":
                self.add(
                    "undo_partition",
                    label,
                    FAIL,
                    "`restore: span` but listed in committed_paths: git has no pre-run copy on "
                    "base_commit, so `git checkout <base_branch>` DELETES this file and the user's "
                    "own content with it instead of restoring it. Move it to uncommitted_paths and "
                    "undo it with the marker-removal script (DECISIONS 2.15)",
                )
                continue

            self.add(
                "undo_partition",
                label,
                PASS,
                "removed by %s"
                % (
                    "the branch delete / unstage (committed_paths)"
                    if in_committed
                    else "an explicit per-file step (uncommitted_paths%s)"
                    % (", %s" % _short(artifact.get("ignored_by"), 60) if ignored and artifact.get("ignored_by") else "")
                ),
            )

        orphans = sorted(set(list(committed.keys()) + list(uncommitted.keys())) - claimed)
        if orphans:
            self.add(
                "undo_partition",
                "manifest",
                WARN,
                "%d path(s) in the undo lists match no artifact, so the removal steps would touch "
                "files this manifest does not claim: %s"
                % (len(orphans), ", ".join(orphans[:4])),
            )

        self._check_created_dirs()

    def _dir_empties_on_undo(
        self, key: str, created: set, memo: Dict[str, bool], depth: int = 0
    ) -> bool:
        """
        Would `key` be an EMPTY directory once the undo removed `created`?

        True only when every entry under it, recursively, is a file this run
        created or a directory that itself empties out.  One stray file the run
        did not create -- the user's own, a `.DS_Store`, anything -- and the
        answer is no, which is what keeps this from ever demanding an `rmdir`
        of a directory that would still hold something.
        """
        if key in memo:
            return memo[key]
        memo[key] = False  # cycle guard for a symlinked loop
        if depth > 8:
            return False
        path = os.path.join(self.repo, key.replace("/", os.sep))
        try:
            names = os.listdir(path)
        except OSError:
            return False
        if len(names) > 500:
            return False
        empty = True
        for name in names:
            child_path = os.path.join(path, name)
            child = "%s/%s" % (key, name)
            if os.path.isdir(child_path) and not os.path.islink(child_path):
                if not self._dir_empties_on_undo(child, created, memo, depth + 1):
                    empty = False
                    break
            elif child not in created:
                empty = False
                break
        memo[key] = empty
        return empty

    def _expected_created_dirs(self) -> List[str]:
        """
        The directories this run's own artifact paths prove it created.

        Derived, never trusted: an ancestor directory of a file the run created
        that would be EMPTY once the undo removed that run's files is a
        directory the run made and nothing else uses.  If `created_dirs` does
        not name it, no `rmdir` is generated for it and the undo leaves an empty
        directory behind -- "additive and reversible" with a `.claude/agents/`
        still sitting in the tree.  Measured by dropping `.claude/agents` from a
        manifest whose run genuinely created it: every other check passed.
        Deepest-first, the order `created_dirs` itself has to be in.
        """
        created = set()  # type: set
        for artifact in self.artifacts:
            if artifact.get("action") != "created":
                continue
            key = self._undo_key(artifact.get("path"))
            if key and key != "." and key.split("/")[0] != "..":
                created.add(key)
        if not created:
            return []

        candidates = set()  # type: set
        for key in created:
            parts = key.split("/")[:-1]
            for index in range(len(parts)):
                candidate = "/".join(parts[: index + 1])
                if candidate and candidate != "." and not candidate.startswith(".."):
                    candidates.add(candidate)

        memo = {}  # type: Dict[str, bool]
        expected = [key for key in candidates if self._dir_empties_on_undo(key, created, memo)]
        expected.sort(key=lambda key: (-key.count("/"), key))
        return expected

    def _check_created_dirs(self) -> None:
        """
        `created_dirs` is what the undo's `rmdir` steps are generated from, so
        it has to be repo-relative, real, deepest-first -- a parent listed
        before its own child is a `rmdir` that fails on a non-empty directory
        and leaves the tree dirty (verification.md 10.3) -- and COMPLETE.

        Complete is the half that was missing.  Every check here read the list
        the manifest wrote and none of them asked what the run actually made,
        so an UNDER-recorded list passed: drop `.claude/agents` from a manifest
        whose run created it and the undo leaves an empty directory behind with
        every row still green.  `_expected_created_dirs` derives the answer from
        the created artifact paths instead of trusting the list.
        """
        value = self.manifest.get("created_dirs")
        if value is None:
            return
        if not isinstance(value, list):
            self.add("undo_created_dirs", "manifest", FAIL, "`created_dirs` is not a list")
            return

        expected = self._expected_created_dirs()
        if not value:
            if not expected:
                self.add(
                    "undo_created_dirs", "manifest", PASS,
                    "no directory recorded as created by this run, and none of the artifact paths "
                    "shows one: nothing for the undo to rmdir",
                )
            else:
                self.add(
                    "undo_created_dirs",
                    "manifest",
                    FAIL,
                    "`created_dirs` is empty, but %d director(y/ies) hold nothing except files this "
                    "run created and so would be left behind empty by the undo: %s. Record them "
                    "deepest-first so the removal block gets an `rmdir` for each"
                    % (len(expected), ", ".join(expected[:4])),
                )
            return

        entries = []  # type: List[str]
        problems = []  # type: List[str]
        notes = []  # type: List[str]
        for raw in value:
            text = str(raw or "").strip()
            if not text:
                problems.append("an empty entry")
                continue
            if os.path.isabs(text) or text.startswith("~"):
                problems.append("%s is absolute; created_dirs is repo-relative" % _short(text, 60))
                continue
            key = self._undo_key(text)
            if not key or key == "." or key.split("/")[0] == "..":
                problems.append("%s resolves outside the repo root" % _short(text, 60))
                continue
            if key in entries:
                notes.append("%s is listed twice" % key)
                continue
            if not os.path.isdir(os.path.join(self.repo, key)):
                notes.append("%s is not a directory on disk" % key)
            entries.append(key)

        for outer in range(len(entries)):
            for inner in range(outer + 1, len(entries)):
                if entries[inner].startswith(entries[outer] + "/"):
                    problems.append(
                        "%s is listed before %s it contains; created_dirs must be deepest-first or "
                        "the undo's rmdir hits a non-empty directory" % (entries[outer], entries[inner])
                    )

        # UNDER-recorded is the failure nothing above can see: every entry
        # present can be perfect while the list is short one directory.
        missing = [key for key in expected if key not in entries]
        if missing:
            problems.append(
                "%d director(y/ies) the run created are NOT in `created_dirs`: %s -- each holds "
                "nothing but files this run created, so the undo removes the files, generates no "
                "`rmdir` for the directory and leaves it behind empty"
                % (len(missing), ", ".join(missing[:4]))
            )

        if problems:
            self.add("undo_created_dirs", "manifest", FAIL, "; ".join(problems[:4]))
            return
        if notes:
            self.add("undo_created_dirs", "manifest", WARN, "; ".join(notes[:4]))
            return
        self.add(
            "undo_created_dirs",
            "manifest",
            PASS,
            "%d created directory path(s), all repo-relative, on disk and deepest-first, and every "
            "one the artifact paths imply (%d) is listed: %s"
            % (len(entries), len(expected), ", ".join(entries[:4])),
        )

    # -- the uninstall proof ----------------------------------------------
    #
    # PRD 3 promises `reversible`; PRD 13 promises an uninstall path in every
    # report.  Four undo defects have shipped and every one of them was caught
    # by a dogfood run or a human reading the block, never here: a branch that
    # held nothing, a branch that held only what `.gitignore` allowed, the
    # marker script handed a JSON config (`SKIP ...`, exit 0, nothing removed),
    # and a removal block whose steps were printed out of sequence.
    # `undo_partition`
    # proves the manifest is self-consistent with itself and can prove nothing
    # else.  This check asks the three questions it cannot:
    #
    #   1. FORMAT -- can the mechanism that would remove each file act on that
    #      file at all?  A JSON config carries no marker and never can; a file
    #      the user wrote must never meet `rm`.
    #   2. THE BRANCH -- in branch mode, does the branch actually hold every
    #      path `committed_paths` claims, across ALL of its commits (a
    #      branch-mode run commits twice), not just the tip?
    #   3. THE RENDERED BLOCK -- do report.md's removal steps survive being run
    #      in the SEQUENCE they are printed?  `_order_problems` owns this one,
    #      and it is the question this check answered worst: it used to compare
    #      only the operands a step NAMES, so moving the closing block (the
    #      `rm -f` that deletes report.md, the `rmdir`s, the digests) above the
    #      two scripts changed nothing it could see -- every artifact was still
    #      reachable by exactly one mechanism, every enumeration still added
    #      up, and the row said `order consistent` about a block that destroys
    #      itself.  Measured: A,C,D reordered to A,D,C, not detected.  What it
    #      was missing is that a step also reads the FILE IT IS PRINTED IN, and
    #      that `rmdir` and `shasum` consume a state rather than a file.
    #
    # Coverage is necessary and not sufficient, in two ways.  A step that names
    # a path and then no-ops reads as covered by every enumeration ever
    # written, which is why 1 exists and why it is a FAIL.  And a SET of steps
    # that covers every path can still be a SEQUENCE that cannot run, which is
    # why 3 is a separate question and not a footnote to 1.

    def _git_read(
        self, args: Sequence[str], binary: bool = False, timeout: float = 20.0
    ) -> Tuple[bool, Any, str]:
        """
        One read-only git command in the repo, or `(False, empty, why)`.

        Read-only by construction: the only subcommands any caller below passes
        are `rev-parse`, `diff --name-only`, `log --name-only` and `show`.  None
        of the four writes a ref, an object or the working tree, and none of
        them talks to a remote, so "local only, no network" still holds --
        `--no-optional-locks` keeps even the incidental index refresh out of it.
        `shell=False`, argv built here, a hard timeout, and the two environment
        variables that could redirect git elsewhere removed.

        A missing git, a directory that is not a repository, a timeout and a
        non-zero exit all come back the same way, and every caller degrades to a
        WARN naming the reason.  Nothing here invents an answer: the whole point
        of this check is that "could not tell" and "fine" are different.
        """
        empty = b"" if binary else ""
        if self._git_note:
            return (False, empty, self._git_note)
        argv = ["git", "--no-optional-locks", "-C", self.repo] + [str(a) for a in args]
        env = dict(os.environ)
        env["GIT_TERMINAL_PROMPT"] = "0"
        env["GIT_OPTIONAL_LOCKS"] = "0"
        env["GIT_PAGER"] = "cat"
        env.pop("GIT_DIR", None)
        env.pop("GIT_WORK_TREE", None)
        proc = None
        try:
            proc = subprocess.Popen(
                argv, stdout=subprocess.PIPE, stderr=subprocess.PIPE, cwd=self.repo, env=env
            )
            out, err = proc.communicate(timeout=timeout)
        except OSError as exc:
            self._git_note = "git could not be run (%s)" % exc
            return (False, empty, self._git_note)
        except subprocess.TimeoutExpired:
            _terminate(proc)
            return (False, empty, "git timed out after %.0fs" % timeout)
        except Exception as exc:  # pragma: no cover - defensive
            return (False, empty, "git failed: %s: %s" % (type(exc).__name__, exc))
        if proc.returncode != 0:
            lines = (err or b"").decode("utf-8", "replace").strip().splitlines()
            return (False, empty, lines[0] if lines else "git exited %d" % proc.returncode)
        if binary:
            return (True, out or b"", "")
        return (True, (out or b"").decode("utf-8", "replace"), "")

    def _git_usable(self) -> Tuple[bool, str]:
        """True only when `--repo` is itself the top level of a git work tree."""
        if self._git_usable_cache is None:
            ok, out, note = self._git_read(["rev-parse", "--show-toplevel"])
            top = str(out).strip().splitlines()
            top = top[0].strip() if top else ""
            if not ok:
                self._git_usable_cache = (False, note or "not a git repository")
            elif not top or os.path.realpath(top) != self.repo_real:
                self._git_usable_cache = (
                    False,
                    "--repo is not the top level of the work tree (git says %s)" % _short(top, 60),
                )
            else:
                self._git_usable_cache = (True, "")
        return self._git_usable_cache

    def _branch_contents(self, branch: str, base_commit: str) -> Tuple[Optional[set], str]:
        """
        Every path the branch holds against its base, across ALL of its commits.

        `git show --name-only <branch>` is the trap this avoids twice over: it
        prints the TIP commit alone, and a branch-mode run commits twice (phase
        7 the artifacts, phase 8 report.md and the manifest), so it silently
        drops the first commit's files; and on a branch with no commit at all it
        prints the BASE commit's file list and exits 0, which makes the branch
        that held nothing read as fully covered.  Both measured -- see
        verification.md 10.2 and build-and-verify.md 4.4.
        """
        if base_commit:
            ok, out, note = self._git_read(["diff", "--name-only", "%s..%s" % (base_commit, branch)])
            label = "git diff --name-only %s..%s" % (_short(base_commit, 12), _short(branch, 40))
        else:
            # No commit existed before the run, so the branch IS the history.
            ok, out, note = self._git_read(["log", "--name-only", "--pretty=format:", branch])
            label = "git log --name-only %s" % _short(branch, 40)
        if not ok:
            return (None, note or "git could not enumerate the branch")
        found = set()
        for line in str(out).splitlines():
            key = self._undo_key(line.strip()) if line.strip() else ""
            if key:
                found.add(key)
        return (found, label)

    def _worktree_matches(self, ref: str, key: str) -> Tuple[Optional[bool], str]:
        """
        Do the bytes ON DISK equal the ones `ref` holds for `key`?

        `(True, "")`, `(False, "")`, or `(None, why)` when either side could not
        be read -- "could not tell" is never reported as "fine".  `ref` is a
        branch or commit; the empty string means the INDEX (`git show :path`),
        which is what stage-only mode's "committed" copy really is.
        """
        spec = "%s:%s" % (ref, key) if ref else ":%s" % key
        ok, blob, note = self._git_read(["show", spec], binary=True)
        if not ok:
            return (None, note or "git could not read %s" % _short(spec, 60))
        path = os.path.join(self.repo, key.replace("/", os.sep))
        try:
            with open(path, "rb") as handle:
                disk = handle.read()
        except OSError as exc:
            return (None, "the file on disk could not be read (%s)" % exc)
        return (hashlib.sha256(disk).hexdigest() == hashlib.sha256(blob).hexdigest(), "")

    def _check_committed_worktree(
        self, emit: Any, committed: Sequence[str], ref: str, ref_label: str, restores: str
    ) -> str:
        """
        Every `committed_paths` entry's WORKING TREE must match what git holds.

        The undo bug class again, from the one side nothing looked at.  The
        removal block's first step is `git branch -D <branch>` (or, stage-only,
        `git checkout <base_commit> -- <path>`), and BOTH restore the COMMITTED
        bytes.  An artifact edited after it was committed -- by a later phase,
        by the model's own fix-or-remove loop in phase 8 step 3, by the user
        between the build and the verify -- still reads as fully covered by
        every enumeration above: it is in `committed_paths`, it is on the
        branch, `undo_partition` balances.  The undo then silently discards the
        edit the manifest claims is safely on the branch.  So compare the
        bytes, not the path list.  Returns a note for the summary row.
        """
        drifted = []  # type: List[str]
        unreadable = []  # type: List[str]
        for key in sorted(committed):
            same, why = self._worktree_matches(ref, key)
            if same is None:
                unreadable.append("%s (%s)" % (key, _short(why, 40)))
            elif not same:
                drifted.append(key)
        if drifted:
            emit(
                "the run",
                FAIL,
                "%d committed_paths entry(s) have UNCOMMITTED working-tree changes: %s. %s "
                "restores what %s holds, so the undo silently discards every edit made after the "
                "commit -- commit them onto the branch, or move them to uncommitted_paths and give "
                "them a per-file step"
                % (len(drifted), ", ".join(drifted[:3]), restores, ref_label),
            )
        if unreadable:
            emit(
                "the run",
                WARN,
                "%d committed_paths entry(s) could not be compared against %s, so whether the undo "
                "would discard a later edit is unknown: %s"
                % (len(unreadable), ref_label, ", ".join(unreadable[:3])),
            )
        if drifted or unreadable:
            return "%d/%d committed_paths match the working tree" % (
                len(committed) - len(drifted) - len(unreadable), len(committed)
            )
        return "working tree matches %s for all %d committed_paths" % (ref_label, len(committed))

    def _uninstall_mechanism(
        self, artifact: Dict[str, Any], mode: str, in_committed: bool
    ) -> str:
        """
        The one mechanism that removes this artifact.  Two questions, in this
        order (report-template.md 3.1):

          1. Can git put this file back?  That is the partition phase 7 already
             computed -- `committed_paths` versus `uncommitted_paths`.
          2. When git cannot: HOW was the file changed?  Created -> `rm`.  A
             marked text file appended to -> the marker script.  A JSON config
             structurally merged into -> the un-merge script.  `restore: span`
             answers question 1 only, and reading it as a mechanism is the
             axios defect.
        """
        kind = artifact["type"]
        action = artifact["action"]
        restore = str(artifact.get("restore") or "").strip().lower()

        if self._is_merged_json(artifact):
            # settings.json and .mcp.json are changed by merging into a data
            # structure.  git can drop or restore a committed one; nothing else
            # can, and the marker script provably cannot -- JSON holds no
            # comment, so the file never carried a marker and never can.
            if in_committed and mode == "branch":
                return "git"
            if in_committed and mode == "stage-only" and action == "modified" and restore == "head":
                return "git"
            return "unmerge"
        if action == "modified":
            if in_committed and mode == "branch":
                return "git"
            if in_committed and mode == "stage-only" and restore == "head":
                return "git"
            return "marker"
        if in_committed and mode == "branch":
            return "git"
        return "rm"

    def _is_merged_json(self, artifact: Dict[str, Any]) -> bool:
        """
        Is this artifact one the UN-MERGE SCRIPT can actually take back out?

        `MERGED_JSON_TYPES` names the two TYPES agentify merges into rather
        than owns -- but on Codex the `mcp` type is TOML, not JSON, and the
        un-merge script parses JSON.  Two consequences, both measured against
        adapters/codex.md 4.6:

          * `<plan-dir>/codex-mcp.toml` is a DRAFT agentify created whole.
            `rm` removes it exactly, and routing it to the un-merge script made
            a correct removal block FAIL with "the removal block `rm`s this
            JSON config".
          * An opt-in append into `<repo>/.codex/config.toml` is a marked block
            in a file that DOES take `#` comments, so the marker script can
            take it out.  The un-merge script cannot: there is no TOML writer
            in the standard library at any version, which is why agentify never
            programmatically rewrites that file in the first place.

        So the routing turns on the file's FORMAT, not on its type name.
        """
        if artifact["type"] not in MERGED_JSON_TYPES:
            return False
        return _is_json_path(artifact.get("path"))

    def _op_path(self, token: Any) -> str:
        """A command operand as a repo-relative key, or `""` when it is not one."""
        text = str(token or "").strip()
        if not text or text in ("--", ">", ">>", "|", "||", "&&", ";"):
            return ""
        if text[0] in "-~$" or os.path.isabs(text):
            return ""
        key = self._undo_key(text)
        if not key or key == "." or key.split("/")[0] == "..":
            return ""
        return key

    @staticmethod
    def _operands(text: str) -> List[str]:
        """
        One command's path operands.  Stops at the first shell operator, so the
        `true` in report-template.md 3.1's guarded
        `[ -d D ] && rmdir D || true` is not read as a second directory, and
        drops a redirection target for the same reason.
        """
        try:
            tokens = shlex.split(text, comments=True)
        except ValueError:
            tokens = text.split("#", 1)[0].split()
        out = []  # type: List[str]
        skip_next = False
        for token in tokens:
            if token in ("||", "&&", ";", "|", "&"):
                break
            if skip_next:
                skip_next = False
                continue
            if token in (">", ">>", "1>", "2>"):
                skip_next = True
                continue
            out.append(token)
        return out

    def _removal_section(self) -> Tuple[str, str, str]:
        """`(section text, repo-relative report path, note)`; text is "" when absent."""
        report_path = ""
        for artifact in self.artifacts:
            if artifact["type"] == "report" and artifact.get("path"):
                report_path = str(artifact["path"])
                break
        if not report_path:
            plan_dir = str(self.manifest.get("plan_dir") or "docs/agentic-setup").strip()
            report_path = "%s/report.md" % plan_dir.rstrip("/")
        absolute = os.path.join(self.repo, report_path)
        if not os.path.isfile(absolute):
            return ("", report_path, "not written yet, so the rendered removal block was not read")
        text, error = _read_text(absolute)
        if error:
            return ("", report_path, "could not be read as text: %s" % _short(error, 60))
        match = _REMOVAL_HEADING_RE.search(text)
        if not match:
            return ("", report_path, "carries no `How to remove everything` heading")
        level = len(match.group(1))
        # Walk to the next heading FENCE-AWARE.  Every shell comment inside the
        # removal block starts a line with `# `, so a plain regex for the next
        # `#` heading stops at `# Step 2 of 2 ...` and silently truncates the
        # section to its first code block -- which is precisely the half of the
        # undo this check exists to look at.
        kept = []  # type: List[str]
        fence = ""
        for line in text[match.end():].splitlines(True):
            stripped = line.strip()
            if fence:
                if stripped.startswith(fence) and stripped.strip(fence[0]) == "":
                    fence = ""
            elif stripped.startswith("```") or stripped.startswith("~~~"):
                fence = stripped[:3]
            elif _HEADING_RE.match(line) and len(_HEADING_RE.match(line).group(1)) <= level:
                break
            kept.append(line)
        return ("".join(kept), report_path, "")

    def _parse_removal_ops(self, section: str) -> Tuple[List[Dict[str, Any]], List[str]]:
        """
        The rendered removal block as an ordered list of operations.

        Each op records what it REMOVES, what it still NEEDS to be there, what
        it WRITES BACK, what final state it CONFIRMS, and whether it PRESERVES
        the instructions by copying them out of the repo.  Those five facts are
        the whole vocabulary the ordering check reasons in, so an assertion is
        written against what a step does and not against how today's template
        happens to word it.  A `python3 - <<'PY'` fence is read as one op keyed by the list it defines
        -- `BLOCKS` is the marker script, `UNMERGE` is the JSON un-merge script
        -- because those two lists, not the shell around them, are what answers
        the format question.  Only the list literal is scanned, never the script
        body: a `print("SKIP %s: not present")` inside it is not an operand.
        """
        ops = []  # type: List[Dict[str, Any]]
        placeholders = set()  # type: set

        def note_placeholder(token: Any) -> None:
            text = str(token or "").strip()
            if text in _REMOVAL_PLACEHOLDERS or _ALLCAPS_TOKEN_RE.match(text):
                placeholders.add(text)

        def new_op(kind: str, line: str, deferred: bool) -> Dict[str, Any]:
            op = {
                "kind": kind,
                "line": _short(line.strip(), 80),
                "removes": set(),
                "removes_dirs": set(),
                "needs": set(),
                "writes": set(),
                "confirms": set(),
                "preserves": set(),
                "mentions": set(),
                "refs_removed": set(),
                "refs_needed": set(),
                "deferred": deferred,
            }
            ops.append(op)
            return op

        def take(op: Dict[str, Any], text: str, *buckets: str) -> None:
            for token in self._operands(text):
                note_placeholder(token)
                key = self._op_path(token)
                if not key:
                    continue
                op["mentions"].add(key)
                for bucket in buckets:
                    op[bucket].add(key)

        for fence in _FENCE_RE.finditer(section):
            body = fence.group(2)
            script = _SCRIPT_LIST_RE.search(body)
            if script:
                op = new_op(
                    "marker-script" if script.group(1) == "BLOCKS" else "unmerge-script",
                    "%s = [...]" % script.group(1),
                    False,
                )
                for entry in _SCRIPT_TUPLE_RE.finditer(script.group(2)):
                    value = entry.group(1)
                    # Merge-entry KIND names, not paths.  `permission_entry` is
                    # the third kind (report-template.md 3.1): one string added
                    # to `.claude/settings.json`'s permissions.allow/ask/deny.
                    if value in ("hook_command", "mcp_server", "permission_entry",
                                 "toml_table"):
                        continue
                    note_placeholder(value)
                    key = self._op_path(value)
                    if key:
                        # Both scripts REWRITE the file they name, so the file
                        # is an input and an output at once.  Recording only the
                        # input half is why a `shasum` confirmation printed
                        # ahead of the script that restores the bytes it checks
                        # read as consistent.
                        op["needs"].add(key)
                        op["writes"].add(key)
                        op["mentions"].add(key)
                continue

            comment_run = []  # type: List[str]
            for raw in body.splitlines():
                line = raw.strip()
                if not line:
                    comment_run = []
                    continue
                if line.startswith("#"):
                    comment_run.append(line)
                    continue
                deferred = bool(_DEFERRED_RE.search(" ".join(comment_run + [line])))
                comment_run = []
                code = re.split(r"\s+#", line, maxsplit=1)[0].strip()

                match = _RMDIR_RE.search(code)
                if match:
                    take(new_op("rmdir", code, deferred), match.group(1), "removes_dirs")
                    continue
                match = _RM_RE.search(code)
                if match:
                    take(new_op("rm", code, deferred), match.group(1), "removes")
                    continue
                match = _BRANCH_DELETE_RE.search(code)
                if match:
                    op = new_op("branch-delete", code, deferred)
                    note_placeholder(match.group(1))
                    op["refs_removed"].add(match.group(1))
                    continue
                match = _GIT_SHOW_RE.search(code)
                if match:
                    op = new_op("git-show", code, deferred)
                    note_placeholder(match.group(1))
                    note_placeholder(match.group(2))
                    op["refs_needed"].add(match.group(1))
                    take(op, match.group(2))
                    outside = _REDIRECT_RE.search(code)
                    if outside and not self._op_path(outside.group(1)):
                        # `git show REF:PATH > <somewhere outside the repo>` is
                        # branch mode's save step: the operand is read out of
                        # git, so the checkout two lines down cannot take it.
                        op["preserves"] |= set(self._op_path(t) for t in [match.group(2)]) - set([""])
                    continue
                match = _GIT_RESTORE_RE.search(code)
                if match:
                    tail = match.group(1)
                    writes = "--worktree" in tail or "--source" in tail
                    op = new_op("git-restore" + ("-worktree" if writes else "-staged"), code, deferred)
                    take(op, tail, *(("writes",) if writes else ()))
                    continue
                match = _GIT_CHECKOUT_RE.search(code)
                if match:
                    op = new_op("git-checkout", code, deferred)
                    note_placeholder(match.group(1))
                    continue
                match = _SHASUM_RE.search(code)
                if match:
                    # A digest is a CONFIRMATION: it reads the file's final
                    # bytes and the report prints the expected hash beside it.
                    # So it consumes a state, and a step printed after it that
                    # still rewrites that file makes the printed hash a hash of
                    # the wrong bytes -- a step that ran and reported success
                    # on a file the undo had not restored yet.
                    take(new_op("shasum", code, deferred), match.group(1), "needs", "confirms")
                    continue
                match = _CP_RE.search(code)
                if match:
                    operands = self._operands(match.group(1))
                    op = new_op("cp", code, deferred)
                    if operands:
                        take(op, operands[0], "needs")
                    # `cp <a file in the repo> <anywhere outside it>` saves that
                    # file from the block's own deletions.  Recognised by the
                    # destination resolving to no repo-relative path -- `~/...`,
                    # `$HOME/...`, an absolute path -- never by its name.
                    if len(operands) > 1 and not self._op_path(operands[-1]):
                        op["preserves"] |= set(self._op_path(t) for t in operands[:-1]) - set([""])
                    continue

        return (ops, sorted(placeholders))

    @staticmethod
    def _under(path: str, directory: str) -> bool:
        """`path` is `directory` itself or something inside it."""
        return bool(directory) and (path == directory or path.startswith(directory + "/"))

    def _order_problems(
        self, ops: List[Dict[str, Any]], instructions: str
    ) -> Tuple[List[str], int]:
        """
        Every ordering assertion over the rendered removal block.

        ONE RULE, TWO DIRECTIONS.  The block is pasted top to bottom by a human
        who never reorders it, so a step must not destroy what a later step
        READS -- and, the direction that was missing, must not consume a state
        a later step still CHANGES.  `rmdir D` consumes "D is empty"; a
        `shasum` consumes "this file is restored".  Both of those are steps
        that succeed loudly while the undo underdelivers.

        ONE IMPLICIT INPUT, and it is the one that made the measured regression
        invisible: **the file the steps are printed in**.  Every step reads its
        own text out of `report.md`, so `report.md` is an input to all of them
        even though not one of them names it -- which is exactly why a check
        built only from named operands passed a block whose closing half (the
        `rm -f` that deletes `report.md`, the `rmdir`, the `shasum`) had been
        printed ahead of the two scripts.  The implicit need is discharged by
        the one step that copies those instructions out of the repo, and that
        is why the copy is step 1 and why the `rm -f` covering `report.md` is
        the last thing that deletes a file.

        Nothing here matches a known string.  A step is classified by what its
        operands are and where they point -- a destination outside the repo, a
        digest of a path, a directory operand -- so a rewording of the template
        is still read correctly and a reordering of it still fails.

        Returns `(problems, deferred_count)`, where each problem is one
        sentence about one step, ready to be its own row.  Several assertions
        can see the same step from different angles -- an early `rmdir` is both
        "removes what a later step needs" and "runs on a directory that is not
        empty" -- so at most one survives per step, the most specific one.  A
        step whose own comment says when to run it is exempt and counted
        instead, as before.
        """
        found = {}  # type: Dict[int, Tuple[int, str]]
        deferred = 0

        def note(op_index: int, rule: str, text: str) -> None:
            if ops[op_index]["deferred"]:
                return
            rank = _ORDER_RULES.index(rule)
            if op_index in found and found[op_index][0] <= rank:
                return
            found[op_index] = (rank, text)

        def defer(op_index: int) -> bool:
            if ops[op_index]["deferred"]:
                return True
            return False

        # -- the step that saves the instructions, and the step that deletes
        #    them.  Both are found by what they do, not by what they are called.
        saved_at = None  # type: Optional[int]
        for index, op in enumerate(ops):
            if instructions and instructions in op["preserves"]:
                saved_at = index
                break
        deletes_instructions = None  # type: Optional[int]
        for index, op in enumerate(ops):
            if not instructions:
                break
            if op["kind"] == "rm" and instructions in op["removes"]:
                if op["deferred"]:
                    # A deletion the block tells the reader to run later is not
                    # AT this position, so it fences nothing off below it.
                    deferred += 1
                    continue
                deletes_instructions = index
                break

        # A. the save comes first.  Every step above it is being read out of a
        #    file this same block later deletes, and the reader has no second
        #    copy until it runs.
        if saved_at is not None and saved_at > 0:
            above = [ops[i] for i in range(saved_at) if not ops[i]["deferred"]]
            if not above:
                deferred += 1
            else:
                note(
                    saved_at,
                    "save-first",
                    "the step that copies these instructions out of the repo has to be step 1; "
                    "`%s` is printed as step %d, and `%s` runs above it, out of the one file this "
                    "block later deletes"
                    % (_short(ops[saved_at]["line"], 52), saved_at + 1, _short(above[0]["line"], 52)),
                )

        # B. run the pairs.  A later step's inputs are what it names PLUS the
        #    instructions themselves, for as long as no step has saved them.
        for index, earlier in enumerate(ops):
            for offset, later_op in enumerate(ops[index + 1:]):
                position = index + 1 + offset
                wants = later_op["needs"] | later_op["writes"]
                if instructions and (saved_at is None or position <= saved_at):
                    wants = wants | set([instructions])
                hits = set(earlier["removes"] & wants)
                # A directory operand is `rmdir`'s alone, and `rmdir` does not
                # delete what is inside: it refuses.  So a later step's input
                # sitting in that directory is not a file that went missing --
                # it is the reason THIS step fails and leaves the directory
                # behind.  Two different failures, and saying the wrong one
                # sends the reader looking for a deletion that never happened.
                inside = set()  # type: set
                for path in wants:
                    for directory in earlier["removes_dirs"]:
                        if self._under(path, directory):
                            inside.add(path)
                refs = earlier["refs_removed"] & later_op["refs_needed"]
                if not hits and not inside and not refs:
                    continue
                if earlier["deferred"]:
                    deferred += 1
                    continue
                if refs:
                    note(
                        index,
                        "ref",
                        "`%s` deletes %s, which a later step still reads from"
                        % (earlier["line"], _short(sorted(refs)[0], 30)),
                    )
                elif inside and not hits:
                    note(
                        index,
                        "rmdir-early",
                        "`%s` runs on a directory that is not empty yet: the `%s` step below it "
                        "still needs %s inside it, so it prints `Directory not empty` and leaves "
                        "the directory behind"
                        % (
                            _short(earlier["line"], 52),
                            later_op["kind"],
                            _short(sorted(inside)[0], 36),
                        ),
                    )
                elif instructions in hits and instructions not in (
                    later_op["needs"] | later_op["writes"]
                ):
                    note(
                        index,
                        "instructions",
                        "step %d onwards is unreachable: `%s` removes %s, the file every step below "
                        "it is printed in, and nothing above it copied those instructions out of "
                        "the repo"
                        % (position + 1, _short(earlier["line"], 60), _short(instructions, 40)),
                    )
                else:
                    note(
                        index,
                        "needs",
                        "`%s` removes %s, which the later `%s` step still needs"
                        % (_short(earlier["line"], 60), _short(sorted(hits)[0], 40), later_op["kind"]),
                    )

        # C. the deletion that takes the instructions is the last one that
        #    deletes a FILE.  `rmdir` and the digests may follow it -- an empty
        #    directory holds nothing and a digest destroys nothing -- but after
        #    it the block survives only in the copy step 1 made, so nothing
        #    that removes content may be printed below it.
        if deletes_instructions is not None:
            for position in range(deletes_instructions + 1, len(ops)):
                later_op = ops[position]
                if not later_op["removes"]:
                    continue
                if defer(position):
                    deferred += 1
                    continue
                note(
                    position,
                    "last-delete",
                    "the step that removes %s has to be the last one that deletes a file: step %d "
                    "already deleted it -- the file every step is printed in -- and `%s` still "
                    "deletes %s below it" % (
                        _short(instructions, 34),
                        deletes_instructions + 1,
                        _short(later_op["line"], 52),
                        _short(sorted(later_op["removes"])[0], 34),
                    ),
                )
            # D. and the two scripts are above it, because they are printed
            #    inside it.  A script below the deletion is a step whose own
            #    text went with the file.
            for position in range(deletes_instructions + 1, len(ops)):
                later_op = ops[position]
                if later_op["kind"] not in ("marker-script", "unmerge-script"):
                    continue
                if defer(position):
                    deferred += 1
                    continue
                note(
                    position,
                    "script-below-delete",
                    "both scripts belong above everything that deletes: the %s is step %d, below "
                    "step %d, which deletes %s -- the file the script itself is printed in"
                    % (
                        "marker script" if later_op["kind"] == "marker-script" else "JSON un-merge script",
                        position + 1,
                        deletes_instructions + 1,
                        _short(instructions, 40),
                    ),
                )

        # E. an `rmdir` consumes an empty directory, so every step that takes
        #    something out of that directory has to be above it.  The forward
        #    scan cannot see this: the later step removes, it does not read.
        for index, earlier in enumerate(ops):
            if not earlier["removes_dirs"]:
                continue
            for offset, later_op in enumerate(ops[index + 1:]):
                position = index + 1 + offset
                leftovers = set()  # type: set
                for directory in earlier["removes_dirs"]:
                    for path in later_op["removes"] | later_op["removes_dirs"]:
                        if path != directory and self._under(path, directory):
                            leftovers.add(path)
                if not leftovers:
                    continue
                if defer(index):
                    deferred += 1
                    continue
                note(
                    index,
                    "rmdir-early",
                    "`%s` runs on a directory that is not empty yet: the `%s` step below it still "
                    "removes %s from it, so this prints `Directory not empty` and leaves the "
                    "directory behind"
                    % (
                        _short(earlier["line"], 52),
                        later_op["kind"],
                        _short(sorted(leftovers)[0], 40),
                    ),
                )

        # F. a digest confirms a file's FINAL bytes.  A step below it that
        #    still rewrites that file makes the printed `expected:` hash a hash
        #    of bytes the undo had not produced yet -- the confirmation passes
        #    on the unrestored file and the report calls the undo proved.
        for index, earlier in enumerate(ops):
            if not earlier["confirms"]:
                continue
            for offset, later_op in enumerate(ops[index + 1:]):
                overlap = earlier["confirms"] & later_op["writes"]
                if not overlap:
                    continue
                if defer(index):
                    deferred += 1
                    continue
                note(
                    index,
                    "confirm-early",
                    "`%s` confirms %s before the `%s` step below it restores that file: the digest "
                    "is taken of the bytes the run left, so it matches the `expected:` line only by "
                    "accident"
                    % (
                        _short(earlier["line"], 52),
                        _short(sorted(overlap)[0], 40),
                        later_op["kind"],
                    ),
                )

        return ([found[index][1] for index in sorted(found)], deferred)

    def _unmerge_handles(
        self, artifact: Dict[str, Any], parsed: Dict[str, Any], hook_commands: Sequence[str]
    ) -> bool:
        """
        Would the JSON un-merge script find at least one of this run's entries?

        It keys on what the templates actually emit, which differs between the
        two files: `settings-hooks.json.tmpl` step 6 forbids merging `_agentify`
        into `settings.json`, so there the hook COMMAND path is the whole of
        agentify's mark; `mcp.json.tmpl` does write `_agentify`, and its servers
        are keyed by name.  Zero matches is the script's own
        `FAIL ... nothing was removed`.
        """
        meta = parsed.get("_agentify")
        wanted_id = artifact["declared_id"] or artifact["id"]
        if isinstance(meta, dict) and str(meta.get("agentify-id") or "") == wanted_id:
            return True
        if artifact["type"] == "mcp":
            servers = parsed.get("mcpServers")
            return isinstance(servers, dict) and bool(servers)
        registered = [command for _event, command in _settings_hook_commands(parsed)]
        if not registered or not hook_commands:
            return False
        for wanted in hook_commands:
            base = os.path.basename(str(wanted).strip().strip("\"'"))
            if not base:
                continue
            for command in registered:
                if base in expand_command(command, self.repo, self.target).replace("\\", "/"):
                    return True
        return False

    def _check_uninstall(self) -> None:
        """
        `uninstall` -- the removal path this run is about to publish, proved
        rather than described.  FAIL on every assertion; the only WARNs are the
        two cases where an input genuinely could not be read, and they say so.
        """
        artifacts = [a for a in self.artifacts if a.get("abs")]
        if not artifacts:
            return

        statuses = []  # type: List[str]

        def emit(target: str, status: str, detail: str) -> None:
            statuses.append(status)
            self.add("uninstall", target, status, detail)

        committed_raw = self.manifest.get("committed_paths")
        uncommitted_raw = self.manifest.get("uncommitted_paths")
        if not (isinstance(committed_raw, list) or isinstance(uncommitted_raw, list)):
            # The same softening `undo_partition` makes, for the same reason: a
            # hand-written manifest still verifies.  It is a WARN because the
            # input is absent, never because a broken undo is tolerable.
            emit(
                "the run",
                WARN,
                "no `committed_paths` / `uncommitted_paths` in the manifest, so not one of the %d "
                "artifact(s) has a removal mechanism to check and phase 8 cannot generate the "
                "removal section from it (SKILL.md phase 7 step 6)" % len(artifacts),
            )
            return

        mode = str(self.manifest.get("mode") or "").strip().lower()
        branch = str(self.manifest.get("branch") or "").strip()
        base_commit = str(self.manifest.get("base_commit") or "").strip()
        committed = set()  # type: set
        uncommitted = set()  # type: set
        for raw_list, bucket in ((committed_raw, committed), (uncommitted_raw, uncommitted)):
            for value in raw_list if isinstance(raw_list, list) else []:
                key = self._undo_key(value)
                if key:
                    bucket.add(key)

        if mode not in ("branch", "stage-only", "no-git"):
            emit(
                "manifest",
                WARN,
                "`mode` is %r, not branch|stage-only|no-git, so the mode-specific half could not "
                "run; the format and coverage halves still did" % (self.manifest.get("mode"),),
            )
            mode = ""

        # -- 1. the partition.  `undo_partition` owns that enumeration; this
        #       check only refuses to report a working undo on top of it.
        broken = [
            row for row in self.checks
            if row.get("name") == "undo_partition" and row.get("status") == FAIL
        ]
        if broken:
            emit(
                "the run",
                FAIL,
                "%d `undo_partition` row(s) FAILED, so an artifact is in neither undo list or in "
                "both and the removal section cannot be generated from this manifest. Fix those "
                "first -- undo_partition owns that enumeration, this row only refuses to overrule it"
                % len(broken),
            )

        # -- 2. every artifact reachable by a mechanism its FORMAT allows.
        by_key = {}  # type: Dict[str, Dict[str, Any]]
        mechanisms = {}  # type: Dict[str, str]
        tally = {}  # type: Dict[str, List[str]]
        hook_commands = [
            str(a.get("command") or a.get("path") or "") for a in artifacts if a["type"] == "hook"
        ]
        for artifact in artifacts:
            label = self.rel(artifact["abs"])
            key = self._undo_key(artifact["path"])
            by_key[key] = artifact
            mechanism = self._uninstall_mechanism(artifact, mode, key in committed)
            mechanisms[key] = mechanism
            tally.setdefault(mechanism, []).append(label)
            action = artifact["action"]
            restore = str(artifact.get("restore") or "").strip().lower()
            text = artifact.get("text")
            hashed = str(artifact.get("pre_existing_sha256") or "").strip()

            if mechanism == "marker":
                if str(artifact["path"]).lower().endswith(".json"):
                    emit(
                        label,
                        FAIL,
                        "a JSON file typed %r routes to the MARKER script, and JSON holds no comment "
                        "and so no marker: the script prints `SKIP ... no agentify block`, exits 0 "
                        "and removes nothing. Type it `settings` or `mcp` so the JSON un-merge "
                        "script owns it (verification.md 10.1)" % artifact["type"],
                    )
                elif isinstance(text, str) and not marker_block(
                    text, artifact["declared_id"] or artifact["id"]
                ):
                    emit(
                        label,
                        FAIL,
                        "the marker script is the only thing that can take agentify's block out of "
                        "this file, and it carries no agentify:begin/end pair for id=%s -- the "
                        "script prints SKIP, exits 0, and the block stays forever"
                        % (artifact["declared_id"] or artifact["id"]),
                    )
                elif not hashed:
                    emit(
                        label,
                        WARN,
                        "routed to the marker script with no `pre_existing_sha256`, so it cannot "
                        "tell a byte-exact restore from a lucky one and warns on this file "
                        "(verification.md 10.3). Record the pre-run hash",
                    )
            elif mechanism == "unmerge":
                parsed = None
                if isinstance(text, str):
                    try:
                        parsed = json.loads(text)
                    except ValueError as exc:
                        emit(
                            label,
                            FAIL,
                            "routed to the JSON un-merge script but it is not valid JSON (%s): the "
                            "script prints STOP and writes nothing, so nothing is removed"
                            % _short(str(exc), 50),
                        )
                if isinstance(parsed, dict):
                    if not self._unmerge_handles(artifact, parsed, hook_commands):
                        emit(
                            label,
                            FAIL,
                            "routed to the JSON un-merge script, which keys on this run's merged "
                            "entries -- each hook's `command`, each `mcpServers` name, an "
                            "`_agentify` with id=%s -- and the file holds none of them. It would "
                            "print `FAIL ... nothing was removed`" % (artifact["declared_id"] or artifact["id"]),
                        )
                elif parsed is not None:
                    emit(
                        label,
                        FAIL,
                        "routed to the JSON un-merge script but its top level is a %s, not an "
                        "object, so there is nothing to un-merge" % type(parsed).__name__,
                    )
                if action == "modified" and not hashed:
                    emit(
                        label,
                        WARN,
                        "merged into with no `pre_existing_sha256`, so the un-merge script cannot "
                        "report whether it reproduced the pre-run bytes (verification.md 10.3)",
                    )
            elif mechanism == "rm" and action != "created":
                emit(
                    label,
                    FAIL,
                    "an `action: %s` file cannot be removed with `rm`: it existed before the run, "
                    "so deleting it destroys the user's own content. It needs the marker script, "
                    "or the un-merge script when it is a JSON config" % action,
                )
            elif mechanism == "git" and mode == "stage-only" and action == "modified" and restore != "head":
                emit(
                    label,
                    FAIL,
                    "stage-only step 4 restores this file from base_commit, which only works with "
                    "`restore: head`; this entry says %r" % (artifact.get("restore"),),
                )

        # -- 3. git's half: what the branch really holds, and whether the bytes
        #       `restore: head` promises are really on base_commit.
        branch_note = ""
        if mode == "branch":
            usable, why = self._git_usable()
            if not usable:
                emit(
                    "the run",
                    WARN,
                    "branch mode, but the branch could not be enumerated (%s), so `committed_paths` "
                    "was taken on trust. Run `git diff --name-only %s..%s` by hand before the "
                    "report claims the delete removes them"
                    % (_short(why, 70), _short(base_commit or "<base>", 12), _short(branch or "<branch>", 30)),
                )
            elif not branch:
                emit(
                    "manifest",
                    FAIL,
                    "`mode` is branch but the manifest names no `branch`, so the removal section "
                    "has no branch to delete",
                )
            else:
                held, note = self._branch_contents(branch, base_commit)
                if held is None:
                    emit(
                        "the run",
                        FAIL,
                        "branch mode, but git cannot enumerate `%s` (%s). The undo's first step is "
                        "`git branch -D %s`, and a branch git cannot read is not one it can delete"
                        % (_short(branch, 30), _short(note, 70), _short(branch, 30)),
                    )
                else:
                    missing = []  # type: List[str]
                    later = []  # type: List[str]
                    for key in sorted(committed):
                        if key in held:
                            continue
                        kind = (by_key.get(key) or {}).get("type") or ""
                        # report.md and the manifest are committed by phase 8
                        # step 5, AFTER this check runs -- 9 step 4a reserves
                        # the report's path here on purpose.  Anything else
                        # missing is the branch that held nothing.
                        if kind in PHASE8_COMMITTED_TYPES or key.rsplit("/", 1)[-1] == "report.md":
                            later.append(key)
                            continue
                        missing.append(key)
                    if missing:
                        emit(
                            "the run",
                            FAIL,
                            "%d committed_paths entry(s) are NOT on `%s` (%s): %s. `git branch -D` "
                            "prints `Deleted branch` and leaves them on disk -- commit them, or "
                            "move them to uncommitted_paths and give them a per-file step"
                            % (len(missing), _short(branch, 24), note, ", ".join(missing[:3])),
                        )
                    stowaways = sorted(uncommitted & held)
                    if stowaways:
                        emit(
                            "the run",
                            FAIL,
                            "%d uncommitted_paths entry(s) ARE on `%s`: %s. Either the undo `rm`s "
                            "what the branch delete already took, or a path the user excluded is "
                            "now in history" % (len(stowaways), _short(branch, 24), ", ".join(stowaways[:3])),
                        )
                    branch_note = "branch holds %d/%d committed_paths" % (
                        len(held & committed), len(committed)
                    )
                    if later:
                        branch_note += " (+%d by phase 8)" % len(later)
                    # 3b. The branch holding the PATH is not the branch holding
                    #     the BYTES.  `git branch -D` restores the committed
                    #     copy, so an entry edited after its commit loses that
                    #     edit and every enumeration above still balances.
                    on_branch = sorted((committed & held) - set(later))
                    if on_branch:
                        branch_note += "; " + self._check_committed_worktree(
                            emit, on_branch, branch,
                            "`%s`" % _short(branch, 24),
                            "`git branch -D %s`" % _short(branch, 24),
                        )

        if mode == "stage-only" and committed and self._git_usable()[0]:
            # The same question, against the copy stage-only's undo restores:
            # step 4 is `git checkout <base_commit> -- <path>` for a `restore:
            # head` entry and `git restore --staged` for the rest, so the INDEX
            # is what a "committed" path really holds here.
            branch_note = self._check_committed_worktree(
                emit, sorted(committed), "", "the index",
                "the stage-only undo's `git restore` / `git checkout`",
            )

        if base_commit and self._git_usable()[0]:
            for artifact in artifacts:
                if artifact["action"] != "modified":
                    continue
                if str(artifact.get("restore") or "").strip().lower() != "head":
                    continue
                want = str(artifact.get("pre_existing_sha256") or "").strip().lower()
                if not want:
                    continue
                key = self._undo_key(artifact["path"])
                ok, blob, note = self._git_read(["show", "%s:%s" % (base_commit, key)], binary=True)
                if not ok:
                    emit(
                        self.rel(artifact["abs"]),
                        FAIL,
                        "`restore: head` says git holds this file's pre-run bytes on base_commit, "
                        "but `git show %s:%s` fails (%s), so the undo cannot restore it. Downgrade "
                        "the entry to `restore: span` and route it to the marker or un-merge script"
                        % (_short(base_commit, 10), _short(key, 40), _short(note, 50)),
                    )
                elif hashlib.sha256(blob).hexdigest() != want:
                    emit(
                        self.rel(artifact["abs"]),
                        FAIL,
                        "`restore: head` but git's copy on base_commit hashes %s, not the "
                        "`pre_existing_sha256` %s this entry records: restoring it would write "
                        "bytes that were never this file's. Downgrade to `restore: span` "
                        "(verification.md 10.3)"
                        % (hashlib.sha256(blob).hexdigest()[:12], want[:12]),
                    )

        # -- 4. the rendered block: does it survive being run in order?
        section, report_path, note = self._removal_section()
        order_note = note
        ops = []  # type: List[Dict[str, Any]]
        if section:
            ops, placeholders = self._parse_removal_ops(section)
            if placeholders:
                emit(
                    report_path,
                    FAIL,
                    "the removal block still carries template placeholder(s) %s -- it was pasted, "
                    "not generated from the manifest. Every operand has to be a real path, branch "
                    "or hash (report-template.md 3.1)" % ", ".join(placeholders[:4]),
                )
            if not ops:
                emit(
                    report_path,
                    FAIL,
                    "the `How to remove everything` section carries no removal command at all, so "
                    "the report documents no undo (PRD 13)",
                )
                order_note = "no commands found"

        if ops:
            named = set()  # type: set
            by_kind = {"marker-script": set(), "unmerge-script": set(), "rm": set(), "rmdir": set()}
            for op in ops:
                named |= op["mentions"]
                if op["kind"] in ("marker-script", "unmerge-script"):
                    by_kind[op["kind"]] |= op["needs"]
                elif op["kind"] == "rm":
                    by_kind["rm"] |= op["removes"]
                elif op["kind"] == "rmdir":
                    by_kind["rmdir"] |= op["removes_dirs"]

            # 4a. format routing, read off the block the user will really run.
            for key in sorted(mechanisms):
                artifact = by_key[key]
                label = self.rel(artifact["abs"])
                mechanism = mechanisms[key]
                # Format, not type name: a Codex `mcp` artifact is TOML, and
                # `rm` is the RIGHT removal for the draft agentify owns whole.
                merged_json = self._is_merged_json(artifact)
                if merged_json and key in by_kind["marker-script"]:
                    emit(
                        label,
                        FAIL,
                        "the removal block hands this JSON config to the MARKER script, which finds "
                        "no `agentify:begin` in a file that can never hold one, prints SKIP and "
                        "exits 0. It belongs in the un-merge script's UNMERGE list (the axios defect)",
                    )
                if merged_json and key in by_kind["rm"]:
                    emit(
                        label,
                        FAIL,
                        "the removal block `rm`s this JSON config. A blind `rm` destroys whatever "
                        "the user added to it after the run; the un-merge script deletes it only "
                        "when nothing but agentify's entries is left (report-template.md 3.1)",
                    )
                if artifact["action"] == "modified" and key in by_kind["rm"]:
                    emit(
                        label,
                        FAIL,
                        "the removal block `rm`s a file that existed BEFORE this run, so the undo "
                        "deletes the user's own file. agentify only added to it: the marker script "
                        "(or the un-merge script for a JSON config) takes that back out, never `rm`",
                    )
                if not merged_json and key in by_kind["unmerge-script"]:
                    emit(
                        label,
                        FAIL,
                        "the removal block hands this file to the JSON un-merge script, which "
                        "prints `STOP ... not valid JSON` and writes nothing. A marked text file "
                        "belongs in the marker script's BLOCKS list",
                    )
                if mechanism == "marker" and key not in by_kind["marker-script"]:
                    emit(
                        label,
                        FAIL,
                        "nothing in the removal block takes agentify's block out of this file: it "
                        "is not in the marker script's BLOCKS list and no git step can reach it, so "
                        "it survives the undo intact (verification.md 10.2)",
                    )
                if mechanism == "unmerge" and key not in by_kind["unmerge-script"]:
                    emit(
                        label,
                        FAIL,
                        "nothing in the removal block un-merges agentify's entries from this JSON "
                        "config: it is not in the un-merge script's UNMERGE list. `restore: span` "
                        "names the git half of the problem only, never the mechanism",
                    )
                if mechanism == "rm" and key not in by_kind["rm"] and key not in named:
                    emit(
                        label,
                        FAIL,
                        "created by this run and named by no removal step at all, so the undo "
                        "leaves it on disk (verification.md 10.2, the turborepo failure)",
                    )

            # report.md's path is reserved in the undo lists at 9 step 4a before
            # its artifacts[] entry exists, so it is checked as a set of one --
            # in the two modes where a step has to name it by hand.
            if mode in ("stage-only", "no-git"):
                for key in sorted(uncommitted | committed):
                    if key in by_key or key in named:
                        continue
                    emit(
                        report_path,
                        FAIL,
                        "`%s` is in the manifest's undo lists but no step in the removal block "
                        "names it, so nothing removes it in %s mode" % (_short(key, 50), mode),
                    )

            for directory in self.manifest.get("created_dirs") or []:
                key = self._undo_key(directory)
                if not key or key in by_kind["rmdir"]:
                    continue
                if mode == "branch" and not any(p.startswith(key + "/") for p in uncommitted):
                    continue  # emptied and removed by step 1's checkout
                emit(
                    report_path,
                    FAIL,
                    "`%s` is in `created_dirs` but no `rmdir` in the removal block names it, so the "
                    "undo leaves an empty directory behind" % _short(key, 50),
                )

            # 4b. ordering: run the steps in the order they are printed.
            #
            # Two facts the parse cannot know are filled in here, because both
            # need the manifest: what the un-merge script DELETES (it removes a
            # JSON config it created once nothing but agentify's entries is
            # left, which is what empties the directory a later `rmdir` wants),
            # and what a branch checkout takes off the working tree.
            for op in ops:
                if op["kind"] == "unmerge-script":
                    op["removes"] |= set(
                        key for key in op["needs"]
                        if (by_key.get(key) or {}).get("action") == "created"
                    )
                elif op["kind"] == "git-checkout" and mode == "branch":
                    op["removes"] |= set(
                        key for key in committed
                        if (by_key.get(key) or {}).get("action", "created") == "created"
                    )
            problems, deferred = self._order_problems(ops, self._undo_key(report_path))
            # One row per defect, not one row listing them: a 300-character
            # detail shared between three findings is a detail that names one
            # of them and truncates the rest, and the truncated one is as
            # likely as not the sentence that says what to move.
            for problem in problems[:_ORDER_ROWS_MAX]:
                emit(
                    report_path,
                    FAIL,
                    "removal block, printed order: %s" % problem,
                )
            if len(problems) > _ORDER_ROWS_MAX:
                emit(
                    report_path,
                    FAIL,
                    "%d further ordering defect(s) in the removal block, not listed individually. "
                    "Fix the ones above and re-run: they usually share one cause -- a block printed "
                    "out of the A, B, C, D sequence (report-template.md 3.1)"
                    % (len(problems) - _ORDER_ROWS_MAX),
                )
            # The summary row quotes this verbatim, so it says what happened.
            # It used to read `order consistent` whichever way the assertions
            # came out, which put the words the report wants next to the
            # failure it must not paper over.
            order_note = "%d step(s), %s%s" % (
                len(ops),
                "%d ordering defect(s)" % len(problems) if problems else "order consistent",
                " (%d deferred by their own comment)" % deferred if deferred else "",
            )

        # -- the row 10.5 publishes.  Generated, so the report never has to
        #    author it: `target` is `the run`, and the detail names every
        #    mechanism that was used and adds up to every artifact.
        mech_words = {
            "git": "the branch delete" if mode == "branch" else "git restore",
            "rm": "rm",
            "marker": "the marker script",
            "unmerge": "the JSON un-merge",
        }
        dirs = len(self.manifest.get("created_dirs") or [])

        def compose(with_names: bool) -> str:
            parts = []  # type: List[str]
            for mechanism in ("git", "rm", "marker", "unmerge"):
                paths = tally.get(mechanism) or []
                if not paths:
                    continue
                names = ""
                if with_names and mechanism in ("marker", "unmerge"):
                    names = " (%s%s)" % (
                        _short(paths[0], 42),
                        ", +%d" % (len(paths) - 1) if len(paths) > 1 else "",
                    )
                parts.append("%d by %s%s" % (len(paths), mech_words[mechanism], names))
            bits = [
                "%s mode: %d artifact(s) -- %s"
                % (mode or "unknown", len(artifacts), ", ".join(parts) or "no mechanism derived")
            ]
            if dirs:
                bits.append("%d created dir(s) by rmdir" % dirs)
            if branch_note:
                bits.append(branch_note)
            if order_note:
                bits.append("report.md: %s" % order_note)
            return "; ".join(bits)

        summary = compose(True)
        not_pass = len([status for status in statuses if status != PASS])
        room = DETAIL_MAX - (60 if not_pass else 0)
        if len(summary) > room:
            summary = compose(False)
        if not_pass:
            emit(
                "the run",
                FAIL if FAIL in statuses else WARN,
                "%s; %d row(s) above are not pass, so the removal section may not yet claim it "
                "removes everything (verification.md 10.5)" % (summary, not_pass),
            )
        else:
            emit("the run", PASS, summary)

    # -- output -----------------------------------------------------------

    def payload(self, manifest_label: str, timing_ms: int) -> Dict[str, Any]:
        # Top-level shape is fixed by the build contract: schema_version, tool,
        # checks, summary, warnings (+ timing_ms, emitted by every agentify
        # script).  Do not add keys here -- per-run context such as the
        # manifest label and the artifact count is reported through `checks`
        # and `warnings`, which SKILL.md already reads.
        summary = dict(self.counts)
        return {
            "schema_version": SCHEMA_VERSION,
            "tool": TOOL,
            "checks": self.checks,
            "summary": summary,
            "warnings": self.warnings,
            "timing_ms": timing_ms,
        }


def _settings_hook_commands(settings: Dict[str, Any]) -> List[Tuple[str, str]]:
    """Every `{"type": "command", "command": "..."}` in a settings object."""
    found = []  # type: List[Tuple[str, str]]
    hooks = settings.get("hooks")
    if not isinstance(hooks, dict):
        return found
    for event, matchers in hooks.items():
        if not isinstance(matchers, list):
            continue
        for matcher in matchers:
            if not isinstance(matcher, dict):
                continue
            entries = matcher.get("hooks")
            if not isinstance(entries, list):
                continue
            for entry in entries:
                if not isinstance(entry, dict):
                    continue
                command = entry.get("command")
                if isinstance(command, str) and command.strip():
                    found.append((str(event), command.strip()))
    return found


# ---------------------------------------------------------------------------
# CLI
# ---------------------------------------------------------------------------


def build_parser():
    parser = emit_lib.base_parser(
        TOOL,
        "Deterministic post-build verification of the artifacts named in a build manifest.",
    )
    parser.add_argument(
        # Deliberately NOT `required=True`: argparse would then reject
        # `--selftest` on its own, and a missing manifest has to come out of
        # `load_manifest` as the documented exit-1 JSON rather than as
        # argparse's bare stderr message.  main() enforces it.
        "--manifest",
        default=None,
        metavar="PATH",
        help="build manifest JSON written in phase 7; `-` reads it from stdin "
             "(required unless --selftest)",
    )
    parser.add_argument(
        "--discovery",
        default=None,
        metavar="PATH",
        help=(
            "optional phase-1 discovery.json. Supplying it turns on the second half of "
            "`rule_contradiction`: every rule is also compared against what the repo "
            "demonstrably does (package manager, test runner, linter, formatter, ...). "
            "That half is the only one that can FAIL -- a rule saying 'use npm' in a repo "
            "with bun.lock is caught by nothing else -- so without this flag such a rule "
            "ships and reports clean. Without it that half is skipped and the check's PASS "
            "row says so. A missing or unparseable file is degraded, not fatal: a warning, "
            "and the run continues rule-against-rule only"
        ),
    )
    parser.add_argument(
        "--hook-timeout-s",
        "--timeout-s",
        type=float,
        default=DEFAULT_HOOK_TIMEOUT,
        dest="hook_timeout_s",
        metavar="SECONDS",
        help="per-hook smoke-test budget (default: %.0f)" % DEFAULT_HOOK_TIMEOUT,
    )
    parser.add_argument(
        "--exec-hooks",
        action="store_true",
        default=False,
        dest="exec_hooks",
        help=(
            "opt in to executing generated hooks for the smoke test. OFF by default. "
            "Only a hook this run generated inside the repo is ever executed, only after its "
            "static network scan is clean, and only with an allowlisted environment (PATH, HOME), "
            "cwd in a throwaway fixture directory, shell=False and a hard timeout. "
            "SKILL.md passes this only after the user says yes in phase 8"
        ),
    )
    parser.add_argument(
        "--no-exec",
        action="store_true",
        default=False,
        dest="no_exec",
        help=(
            "do not execute hook scripts. This is already the default; the flag is kept so "
            "existing call sites keep working, and it wins if --exec-hooks is also given"
        ),
    )
    return parser


def main(argv: Optional[Sequence[str]] = None) -> int:
    parser = build_parser()
    args = parser.parse_args(argv)
    if getattr(args, "selftest", False):
        return selftest()

    repo = emit_lib.resolve_repo(args.repo)
    cap = args.cap_chars if getattr(args, "cap_chars", None) else CAP_CHARS

    try:
        if not args.manifest:
            raise ValueError("--manifest is required (or pass --selftest)")
        manifest, label = load_manifest(args.manifest)
    except ValueError as exc:
        emit_lib.fail(
            str(exc),
            tool=TOOL,
            exit_code=1,
            extra={
                "checks": [],
                "summary": {"pass": 0, "fail": 0, "warn": 0},
            },
        )
        return 1  # pragma: no cover - fail() exits

    conventions, conventions_label, conventions_note, discovery_raw = load_discovery(
        getattr(args, "discovery", None))

    timer = emit_lib.Timer()
    with timer:
        verifier = Verifier(
            repo,
            manifest,
            args,
            manifest_label=label,
            conventions=conventions,
            conventions_label=conventions_label,
            discovery=discovery_raw,
        )
        if conventions_note:
            verifier.warn(conventions_note)
        try:
            verifier.run()
        except Exception as exc:  # pragma: no cover - defensive
            verifier.warn("verification aborted early: %s: %s" % (type(exc).__name__, exc))
            if getattr(args, "debug", False):
                import traceback

                traceback.print_exc(file=sys.stderr)
        finally:
            # The fixture is a throwaway; it never survives the run, pass or fail.
            verifier.cleanup_fixture()

    emit_lib.emit(verifier.payload(label, timer.ms), cap_chars=cap)
    return 0


